function ProjectAccessoryInventory({mode,project,rows,allRows,projectUnits,openUnit,openClient,canManage,assign,release,create,update,remove,onCatalogChanged}:{mode:"cellar"|"parking";project:ProjectRecord;rows:CatalogAccessoryRecord[];allRows:CatalogAccessoryRecord[];projectUnits:UnitRecord[];openUnit:(unit:UnitRecord)=>void;openClient:(name:string)=>void;canManage:boolean;assign:(unit:UnitRecord,accessory:CatalogAccessoryRecord)=>Promise<void>;release:(accessory:AccessoryAssignmentRecord)=>Promise<void>;create:(value:{category:"parking"|"cellar"|"wallbox";code:string;areaM2?:number|null;amount:number;amountNet?:number|null;relatedAccessoryId?:string|null})=>Promise<void>;update:(value:{accessoryId:string;code:string;areaM2?:number|null;amount:number;amountNet?:number|null;reason?:string})=>Promise<void>;remove:(accessory:CatalogAccessoryRecord,reason:string)=>Promise<{mode:"delete"|"archive"}>;onCatalogChanged:()=>void}){
  const columns=mode==="cellar"?cellarTableColumns:parkingTableColumns;const columnState=useTableColumns(mode==="cellar"?"cellars-table":"parking-table",columns);
  const [types,setTypes]=useState<string[]>([]);const [states,setStates]=useState<string[]>([]);const [unitsFilter,setUnitsFilter]=useState<string[]>([]);const [wallboxFilter,setWallboxFilter]=useState<string[]>([]);const [sort,setSort]=useState<"code"|"type"|"area"|"price"|"state"|"unit"|"wallbox">("code");const [direction,setDirection]=useState<SortDirection>("asc");
  const [selected,setSelected]=useState<CatalogAccessoryRecord|null>(null);const [assignTarget,setAssignTarget]=useState<CatalogAccessoryRecord|null>(null);const [selectedUnitId,setSelectedUnitId]=useState("");const [creating,setCreating]=useState(false);const [importing,setImporting]=useState(false);const [editing,setEditing]=useState<CatalogAccessoryRecord|null>(null);const [removing,setRemoving]=useState<CatalogAccessoryRecord|null>(null);const [error,setError]=useState("");
  const typeOptions=Array.from(new Set(rows.map(row=>row.subtype??row.type)));const unitOptions=Array.from(new Set(rows.map(row=>row.assignedUnitCode).filter(Boolean) as string[]));
  const filtered=rows.filter(row=>{const state=row.archived?"Archivované":row.available?"Volné":"Přiřazené";const wallbox=row.relation?"Ano":"Ne";return(states.length?states.includes(state):!row.archived)&&(!types.length||types.includes(row.subtype??row.type))&&(!unitsFilter.length||Boolean(row.assignedUnitCode&&unitsFilter.includes(row.assignedUnitCode)))&&(mode!=="parking"||!wallboxFilter.length||wallboxFilter.includes(wallbox));});
  const selector=(row:CatalogAccessoryRecord)=>sort==="code"?row.code:sort==="type"?(row.subtype??row.type):sort==="area"?(row.areaM2??0):sort==="price"?(row.amount??0):sort==="state"?(row.archived?"Archivované":row.available?"Volné":"Přiřazené"):sort==="wallbox"?(row.relation??""):(row.assignedUnitCode??"");
  const visible=stableSort(filtered,selector,direction,row=>row.id);
  const changeSort=(key:typeof sort)=>(next:SortDirection)=>{setSort(key);setDirection(next);};
  const releaseItem=async(item:CatalogAccessoryRecord)=>{if(!item.assignmentId)return setError("Aktivní přiřazení nemá platný identifikátor. Obnovte prosím stránku.");if(!window.confirm(`Opravdu uvolnit ${item.type.toLocaleLowerCase("cs-CZ")} ${item.code} z jednotky ${item.assignedUnitCode??""}? Historie přiřazení zůstane zachována.`))return;setError("");try{await release(item);setSelected(null);}catch(reason){setError(reason instanceof Error?reason.message:"Příslušenství se nepodařilo uvolnit.");}};
  const title=mode==="cellar"?"Sklepy":"Parkovací místa";const activeRows=rows.filter(row=>!row.archived);const summaryRows=states.includes("Archivované")?rows:activeRows;const available=summaryRows.filter(row=>!row.archived&&row.available).length;const assigned=summaryRows.filter(row=>!row.archived&&!row.available).length;
  return <section className="card project-module-card project-accessories-card">
    <div className="accessory-inventory-summary" aria-label={`Souhrn ${title.toLocaleLowerCase("cs-CZ")}`}><div className="accessory-summary-metrics"><span><small>Celkem</small><strong>{summaryRows.length}</strong></span><span><small>Volné</small><strong>{available}</strong></span><span><small>Přiřazené</small><strong>{assigned}</strong></span></div><span className="list-toolbar-actions"><TableColumnMenu columns={columns} state={columnState}/>{canManage&&<><button className="secondary-button compact" onClick={()=>setImporting(true)}><Upload size={16}/> Importovat {mode==="cellar"?"sklepy":"parkovací místa"}</button><button className="primary-button" onClick={()=>setCreating(true)}><Plus size={16}/> {mode==="cellar"?"Přidat sklep":"Přidat parkovací místo"}</button></>}</span></div>
    {error&&<div className="form-error accessory-inventory-error"><AlertTriangle size={15}/>{error}</div>}
    <div className="unit-table-wrap"><table className="data-table filter-table accessory-inventory-table configurable-table"><thead><tr>
      <TableColumnFilter label="Označení" sortDirection={sort==="code"?direction:undefined} onSort={changeSort("code")} className="column-primary"/>
      {mode==="cellar"&&columnState.isVisible("area")&&<TableColumnFilter label="Výměra" sortType="number" sortDirection={sort==="area"?direction:undefined} onSort={changeSort("area")}/>} {mode==="parking"&&columnState.isVisible("type")&&<TableColumnFilter label="Typ" active={types.length>0} sortDirection={sort==="type"?direction:undefined} onSort={changeSort("type")}><MultiSelectFilter options={typeOptions} selected={types} onChange={setTypes} allLabel="Všechny typy" ariaLabel="Filtrovat typ parkování"/></TableColumnFilter>}
      {columnState.isVisible("price")&&<TableColumnFilter label="Cena" sortType="number" sortDirection={sort==="price"?direction:undefined} onSort={changeSort("price")}/>} {columnState.isVisible("state")&&<TableColumnFilter label="Stav" active={states.length>0} sortDirection={sort==="state"?direction:undefined} onSort={changeSort("state")}><MultiSelectFilter options={["Volné","Přiřazené","Archivované"]} selected={states} onChange={setStates} allLabel="Aktivní položky" ariaLabel="Filtrovat stav příslušenství"/></TableColumnFilter>}
      {columnState.isVisible("unit")&&<TableColumnFilter label="Přiřazená jednotka" active={unitsFilter.length>0} sortDirection={sort==="unit"?direction:undefined} onSort={changeSort("unit")}><MultiSelectFilter options={unitOptions} selected={unitsFilter} onChange={setUnitsFilter} allLabel="Všechny jednotky" ariaLabel="Filtrovat přiřazenou jednotku"/></TableColumnFilter>} {columnState.isVisible("client")&&<th>Klient / obchodní stav</th>}{mode==="parking"&&columnState.isVisible("wallbox")&&<TableColumnFilter label="Wallbox" active={wallboxFilter.length>0} sortDirection={sort==="wallbox"?direction:undefined} onSort={changeSort("wallbox")}><MultiSelectFilter options={["Ano","Ne"]} selected={wallboxFilter} onChange={setWallboxFilter} allLabel="S wallboxem i bez" ariaLabel="Filtrovat wallbox"/></TableColumnFilter>}{columnState.isVisible("location")&&<th>Umístění</th>}<th/>
    </tr></thead><tbody>{visible.map(row=>{const unit=projectUnits.find(item=>(item.backendId??item.id)===row.assignedUnitId||item.id===row.assignedUnitCode);const client=row.assignedClient??unit?.client;return <tr key={row.id} className={row.archived?"archived-row":""} onClick={()=>setSelected(row)}><td className="column-primary"><strong>{row.code}</strong></td>{mode==="cellar"&&columnState.isVisible("area")&&<td>{row.areaM2!==null?`${row.areaM2.toLocaleString("cs-CZ")} m²`:"—"}</td>}{mode==="parking"&&columnState.isVisible("type")&&<td>{row.type}</td>}{columnState.isVisible("price")&&<td><strong>{formatMoney(row.amount??0)}</strong></td>}{columnState.isVisible("state")&&<td><Badge tone={row.archived?"neutral":row.available?"success":"blue"}>{row.archived?"Archivované":row.available?"Volné":"Přiřazené"}</Badge></td>}{columnState.isVisible("unit")&&<td>{unit?<button className="unit-link" onClick={event=>{event.stopPropagation();openUnit(unit);}}>{unit.id}</button>:"—"}</td>}{columnState.isVisible("client")&&<td>{client?<button className="client-inline-link" onClick={event=>{event.stopPropagation();openClient(client);}}>{client}</button>:"—"}<small>{row.assignedUnitStatus?unitCommercialStatusLabel(row.assignedUnitStatus):"Bez aktivního obchodního vztahu"}</small></td>}{mode==="parking"&&columnState.isVisible("wallbox")&&<td>{row.relation?<Badge tone="purple">Wallbox {row.relation}</Badge>:"—"}</td>}{columnState.isVisible("location")&&<td>{row.location??"—"}</td>}<td><button className="ghost-icon" onClick={event=>{event.stopPropagation();setSelected(row);}} aria-label={`Akce ${row.type.toLocaleLowerCase("cs-CZ")} ${row.code}`}><MoreHorizontal size={17}/></button></td></tr>})}</tbody></table></div>
    {!visible.length&&<div className="empty-filter-state"><PackageOpen size={22}/><strong>Žádné položky neodpovídají filtrům</strong><button className="text-button" onClick={()=>{setTypes([]);setStates([]);setUnitsFilter([]);setWallboxFilter([]);}}>Zrušit filtry</button></div>}
    {selected&&<AccessoryDetailModal
      item={selected}
      unit={projectUnits.find(candidate=>(candidate.backendId??candidate.id)===selected.assignedUnitId||candidate.id===selected.assignedUnitCode)}
      close={()=>setSelected(null)}
      openUnit={openUnit}
      openClient={openClient}
      canManage={canManage}
      assign={()=>{setAssignTarget(selected);setSelectedUnitId("");setSelected(null);}}
      release={()=>void releaseItem(selected)}
      edit={()=>{setEditing(selected);setSelected(null);}}
      remove={()=>{setRemoving(selected);setSelected(null);}}
    />}
    {assignTarget&&<FormModal title={`Přiřadit ${assignTarget.type.toLocaleLowerCase("cs-CZ")} ${assignTarget.code}`} close={()=>setAssignTarget(null)} onSave={async()=>{const unit=projectUnits.find(item=>(item.backendId??item.id)===selectedUnitId);if(!unit)throw new Error("Vyberte jednotku");await assign(unit,assignTarget);setAssignTarget(null);}} saveLabel="Přiřadit"><label><span>Jednotka</span><select value={selectedUnitId} onChange={event=>setSelectedUnitId(event.target.value)}><option value="">Vyberte jednotku</option>{projectUnits.map(unit=><option key={unit.backendId??unit.id} value={unit.backendId??unit.id}>{unit.id} · {unit.layout} · {unit.status}</option>)}</select></label><p className="form-help"><History size={14}/> Přiřazení bude časově evidované a zapíše se do historie jednotky i příslušenství.</p></FormModal>}
    {creating&&<CreateAccessoryModal inventory={allRows} initialCategory={mode} close={()=>setCreating(false)} save={async value=>{await create(value);setCreating(false);}}/>}
    {importing&&<InventoryImportModal project={project} entityType={mode} close={()=>setImporting(false)} completed={()=>{setImporting(false);onCatalogChanged();}}/>}
    {editing&&<EditAccessoryModal item={editing} close={()=>setEditing(null)} save={async value=>{await update(value);setEditing(null);}}/>}
    {removing&&<FormModal title={`${removing.assignmentId?"Nelze smazat":"Smazat"} ${removing.type.toLocaleLowerCase("cs-CZ")} ${removing.code}`} close={()=>setRemoving(null)} saveLabel={removing.assignmentId?"Rozumím":"Smazat / archivovat"} onSave={async()=>{if(removing.assignmentId){setRemoving(null);return;}await remove(removing,"Odstranění z projektového inventáře");setRemoving(null);}}><div className="archive-impact-warning"><AlertTriangle size={18}/><div><strong>{removing.assignmentId?"Položka je aktuálně přiřazená":"Opravdu chcete položku odstranit?"}</strong><span>{removing.assignmentId?`Nejprve ji uvolněte z jednotky ${removing.assignedUnitCode??""}.`:(removing.assignmentHistory?.length??0)>0?"Položka už má historii, proto bude bezpečně archivována. Historie přiřazení, cen a auditu zůstane zachována.":"Pokud položka nemá obchodní historii, bude smazána. Jinak ji systém bezpečně archivuje."}</span></div></div></FormModal>}
  </section>;
}

function AccessoryDetailModal({item,unit,close,openUnit,openClient,canManage,assign,release,edit,remove}:{item:CatalogAccessoryRecord;unit?:UnitRecord;close:()=>void;openUnit:(unit:UnitRecord)=>void;openClient:(name:string)=>void;canManage:boolean;assign:()=>void;release:()=>void;edit:()=>void;remove:()=>void}){
  const client=item.assignedClient??unit?.client;
  return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label="Zavřít detail příslušenství"/><div className="modal form-modal accessory-detail-modal"><div className="modal-head"><div><h2>{item.type} · {item.code}</h2><p>{item.archived?"Archivovaná položka":item.available?"Volné k přiřazení":"Aktuálně přiřazené příslušenství"}</p></div><button className="icon-button" onClick={close}><X size={19}/></button></div><div className="modal-form"><div className="accessory-detail-summary"><span><small>Cena</small><strong>{formatMoney(item.amount??0)}</strong></span><span><small>Stav</small><Badge tone={item.archived?"neutral":item.available?"success":"blue"}>{item.archived?"Archivované":item.available?"Volné":"Přiřazené"}</Badge></span><span><small>Aktuální jednotka</small><strong>{item.assignedUnitCode??"—"}</strong></span>{client&&<span><small>Aktuální klient</small><button className="client-inline-link" onClick={()=>{close();openClient(client);}}>{client}</button></span>}{item.areaM2!==null&&<span><small>Výměra</small><strong>{item.areaM2.toLocaleString("cs-CZ")} m²</strong></span>}{item.relation&&<span><small>{item.category==="parking"?"Wallbox":"Fyzická vazba"}</small><strong>{item.relation}</strong></span>}</div><section className="accessory-history"><strong>Historie přiřazení</strong>{item.assignmentHistory?.length?item.assignmentHistory.map(history=><article key={history.assignmentId}><History size={15}/><span><b>Jednotka {history.unitCode}</b><small>{formatPragueDateTime(history.validFrom)} – {history.validTo?formatPragueDateTime(history.validTo):"dosud"}{history.assignedBy?` · ${history.assignedBy}`:""}</small></span></article>):<p className="empty-copy">Položka zatím nemá historii přiřazení.</p>}</section></div><div className="modal-foot">{unit&&<button className="secondary-button" onClick={()=>{close();openUnit(unit);}}>Otevřít jednotku</button>}<span className="modal-foot-spacer"/>{canManage&&!item.archived&&<><button className="secondary-button" onClick={edit}>Upravit</button>{item.available?<button className="primary-button" onClick={assign}>Přiřadit</button>:<button className="secondary-button" onClick={release}>Uvolnit</button>}<button className="secondary-button danger-text" onClick={remove}>{item.category==="cellar"?"Smazat sklep":item.category==="parking"?"Smazat parkovací místo":"Smazat příslušenství"}</button></>}</div></div></div>;
}

function EditAccessoryModal({item,close,save}:{item:CatalogAccessoryRecord;close:()=>void;save:(value:{accessoryId:string;code:string;areaM2?:number|null;amount:number;amountNet?:number|null;reason?:string})=>Promise<void>}){
  const [code,setCode]=useState(item.code);const [area,setArea]=useState(item.areaM2?.toString()??"");const [amount,setAmount]=useState(String(item.amount??0));const [reason,setReason]=useState("");
  return <FormModal title={`Upravit ${item.type.toLocaleLowerCase("cs-CZ")} ${item.code}`} close={close} onSave={async()=>{const parsed=Number(amount.replace(/\s/g,"").replace(",","."));const areaValue=area?Number(area.replace(",",".")):null;if(!code.trim())throw new Error("Doplňte označení příslušenství");if(!Number.isFinite(parsed)||parsed<0)throw new Error("Doplňte platnou cenu");if(area&&(!Number.isFinite(areaValue)||Number(areaValue)<=0))throw new Error("Doplňte platnou výměru");await save({accessoryId:item.id,code:code.trim(),areaM2:areaValue,amount:parsed,amountNet:item.amountNet,reason:reason.trim()||"Úprava příslušenství"});}}><div className="form-row"><label><span>Označení</span><input value={code} onChange={event=>setCode(event.target.value)}/></label>{item.category==="cellar"&&<label><span>Výměra m²</span><input inputMode="decimal" value={area} onChange={event=>setArea(event.target.value)}/></label>}<label><span>Aktuální cena</span><input inputMode="decimal" value={amount} onChange={event=>setAmount(event.target.value)}/></label></div><label><span>Důvod změny</span><textarea rows={2} value={reason} onChange={event=>setReason(event.target.value)} placeholder="Volitelné upřesnění pro audit"/></label><p className="form-help"><History size={14}/> Změna ceny vytvoří nový historický záznam; předchozí cena se nepřepisuje.</p></FormModal>;
}

function CreateUnitModal({project,close,save}:{project:ProjectRecord;close:()=>void;save:(row:InventoryImportRow)=>Promise<void>}){
  const [code,setCode]=useState("");const [layout,setLayout]=useState("");const [area,setArea]=useState("");const [usable,setUsable]=useState("");const [floor,setFloor]=useState("");const [orientation,setOrientation]=useState("");const [price,setPrice]=useState("");
  return <FormModal title={`Nová jednotka · ${project.name}`} close={close} saveLabel="Vytvořit jednotku" onSave={async()=>{const areaM2=numberValue(area);const amount=price?numberValue(price):null;if(!code.trim())throw new Error("Doplňte označení jednotky");if(!Number.isFinite(areaM2)||areaM2<=0)throw new Error("Doplňte platnou plochu");await save({rowNumber:1,code:code.trim(),layout:layout.trim(),areaM2,usableAreaM2:usable?numberValue(usable):null,floorLabel:floor.trim(),orientation:orientation.trim(),price:amount,commercialStatus:"available"});}}><div className="form-row"><label><span>Označení</span><input autoFocus value={code} onChange={event=>setCode(event.target.value)} placeholder="A101"/></label><label><span>Dispozice</span><input value={layout} onChange={event=>setLayout(event.target.value)} placeholder="3+kk"/></label></div><div className="form-row"><label><span>Podlahová plocha m²</span><input inputMode="decimal" value={area} onChange={event=>setArea(event.target.value)}/></label><label><span>Užitná plocha m²</span><input inputMode="decimal" value={usable} onChange={event=>setUsable(event.target.value)}/></label></div><div className="form-row"><label><span>Podlaží</span><input value={floor} onChange={event=>setFloor(event.target.value)} placeholder="4. NP"/></label><label><span>Orientace</span><input value={orientation} onChange={event=>setOrientation(event.target.value)} placeholder="JZ"/></label></div><label><span>Ceníková cena</span><input inputMode="decimal" value={price} onChange={event=>setPrice(event.target.value)} placeholder="8 900 000"/></label></FormModal>;
}

type SpreadsheetRow=Record<string,unknown>;
const inventoryColumns:Record<InventoryEntityType,Array<{key:keyof InventoryImportRow;label:string;required?:boolean;aliases:string[]}>>={
  unit:[{key:"code",label:"Označení jednotky",required:true,aliases:["jednotka","oznaceni","označení","code","cislo","číslo"]},{key:"layout",label:"Dispozice",aliases:["dispozice","layout"]},{key:"areaM2",label:"Podlahová plocha m²",required:true,aliases:["plocha","plocha m2","podlahova plocha","podlahová plocha"]},{key:"usableAreaM2",label:"Užitná plocha m²",aliases:["uzitna plocha","užitná plocha"]},{key:"floorLabel",label:"Podlaží",aliases:["podlazi","podlaží","floor"]},{key:"orientation",label:"Orientace",aliases:["orientace","orientation"]},{key:"balconyM2",label:"Balkon m²",aliases:["balkon","balkon m2"]},{key:"terraceM2",label:"Terasa m²",aliases:["terasa","terasa m2"]},{key:"gardenM2",label:"Zahrada m²",aliases:["zahrada","zahrada m2"]},{key:"price",label:"Cena",aliases:["cena","price"]},{key:"commercialStatus",label:"Obchodní stav",aliases:["obchodni stav","obchodní stav","stav"]},{key:"constructionStatus",label:"Stavební stav",aliases:["stavebni stav","stavební stav"]}],
  cellar:[{key:"code",label:"Označení sklepa",required:true,aliases:["sklep","oznaceni","označení","code"]},{key:"areaM2",label:"Výměra m²",required:true,aliases:["vymera","výměra","plocha","plocha m2"]},{key:"price",label:"Cena",required:true,aliases:["cena","price"]},{key:"floorLabel",label:"Podlaží / umístění",aliases:["podlazi","podlaží","umisteni","umístění"]},{key:"unitCode",label:"Přiřazená jednotka",aliases:["jednotka","byt","unit"]}],
  parking:[{key:"code",label:"Označení stání",required:true,aliases:["parking","stani","stání","oznaceni","označení","code"]},{key:"type",label:"Typ",aliases:["typ","type"]},{key:"price",label:"Cena",required:true,aliases:["cena","price"]},{key:"floorLabel",label:"Umístění",aliases:["umisteni","umístění","podlazi","podlaží"]},{key:"unitCode",label:"Přiřazená jednotka",aliases:["jednotka","byt","unit"]},{key:"wallboxCode",label:"Wallbox / označení",aliases:["wallbox","wallbox code","wallbox kod"]},{key:"wallboxPrice",label:"Cena wallboxu",aliases:["cena wallboxu","wallbox cena","wallbox price"]}],
};

function InventoryImportModal({project,entityType,close,completed}:{project:ProjectRecord;entityType:InventoryEntityType;close:()=>void;completed:()=>void}){
  const [fileName,setFileName]=useState("");const [headers,setHeaders]=useState<string[]>([]);const [sourceRows,setSourceRows]=useState<SpreadsheetRow[]>([]);const [mapping,setMapping]=useState<Record<string,string>>({});const [strategy,setStrategy]=useState<"update"|"skip">("update");const [preview,setPreview]=useState<InventoryImportPreview|null>(null);const [idempotencyKey,setIdempotencyKey]=useState("");const projectId=backendEntityId(project.backendId);
  const load=async(file:File)=>{if(!/\.xlsx$/i.test(file.name))throw new Error("Vyberte soubor XLSX");if(file.size>25*1024*1024)throw new Error("Soubor je příliš velký. Maximální velikost je 25 MB.");const buffer=await file.arrayBuffer();const ExcelJS=await import("exceljs");const workbook=new ExcelJS.Workbook();await workbook.xlsx.load(buffer);const sheet=workbook.worksheets[0];if(!sheet)throw new Error("Sešit neobsahuje žádný list");const matrix:unknown[][]=[];sheet.eachRow({includeEmpty:false},row=>matrix.push(Array.from({length:row.cellCount},(_,index)=>excelCellValue(row.getCell(index+1).value))));const header=(matrix[0]??[]).map(value=>String(value).trim()).filter(Boolean);if(!header.length)throw new Error("První řádek musí obsahovat názvy sloupců");const rows=matrix.slice(1).filter(row=>row.some(value=>String(value).trim())).map(row=>Object.fromEntries(header.map((name,index)=>[name,row[index]??""])));const normalized=(value:string)=>value.toLocaleLowerCase("cs-CZ").normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim();const auto=Object.fromEntries(inventoryColumns[entityType].map(column=>[column.key,header.find(name=>column.aliases.map(normalized).includes(normalized(name)))??""]));const digest=await crypto.subtle.digest("SHA-256",buffer);setIdempotencyKey(Array.from(new Uint8Array(digest)).map(value=>value.toString(16).padStart(2,"0")).join(""));setFileName(file.name);setHeaders(header);setSourceRows(rows);setMapping(auto);setPreview(null);};
  const rows=()=>sourceRows.map((source,index)=>{const result:InventoryImportRow={rowNumber:index+2};for(const column of inventoryColumns[entityType]){const header=mapping[column.key];if(!header)continue;const raw=source[header];if(["areaM2","usableAreaM2","balconyM2","terraceM2","gardenM2","price","wallboxPrice"].includes(String(column.key)))(result as Record<string,unknown>)[column.key]=spreadsheetNumber(raw);else(result as Record<string,unknown>)[column.key]=String(raw??"").trim();}return result;});
  const proceed=async()=>{if(!projectId)throw new Error("Projekt nemá platný databázový identifikátor");if(!sourceRows.length)throw new Error("Nejdříve vyberte XLSX soubor");for(const column of inventoryColumns[entityType].filter(item=>item.required))if(!mapping[column.key])throw new Error(`Přiřaďte sloupec „${column.label}“`);if(!preview){setPreview(await catalogRepository.previewInventoryImport(projectId,{entityType,rows:rows(),strategy}));return;}if(preview.summary.errors)throw new Error("Import obsahuje chyby. Opravte zdrojový soubor a nahrajte ho znovu.");await catalogRepository.confirmInventoryImport(projectId,{entityType,rows:rows(),strategy,idempotencyKey:`${entityType}-${strategy}-${idempotencyKey}`,fileName});completed();};
  const title=entityType==="unit"?"Import jednotek":entityType==="cellar"?"Import sklepů":"Import parkovacích míst";
  return <FormModal title={`${title} · ${project.name}`} close={close} saveLabel={preview?"Potvrdit import":"Zkontrolovat data"} onSave={proceed}>{!sourceRows.length?<label className="file-drop"><Upload size={24}/><span><strong>Vyberte XLSX soubor</strong><small>První řádek musí obsahovat názvy sloupců.</small></span><input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={event=>{const file=event.target.files?.[0];if(file)void load(file);}}/></label>:<><div className="import-file-summary"><FileText size={18}/><span><strong>{fileName}</strong><small>{sourceRows.length} datových řádků</small></span><button className="text-button" onClick={()=>{setSourceRows([]);setHeaders([]);setPreview(null);}}>Změnit soubor</button></div>{!preview?<><div className="import-mapping"><strong>Přiřazení sloupců</strong>{inventoryColumns[entityType].map(column=><label key={column.key}><span>{column.label}{column.required?" *":""}</span><select value={mapping[column.key]??""} onChange={event=>setMapping(current=>({...current,[column.key]:event.target.value}))}><option value="">Nevyužít</option>{headers.map(header=><option key={header} value={header}>{header}</option>)}</select></label>)}</div><label><span>Existující položky se stejným označením</span><select value={strategy} onChange={event=>setStrategy(event.target.value as typeof strategy)}><option value="update">Bezpečně aktualizovat</option><option value="skip">Přeskočit</option></select></label></>:<><div className="import-preview-metrics"><span><small>Nové</small><strong>{preview.summary.created}</strong></span><span><small>Aktualizace</small><strong>{preview.summary.updated}</strong></span><span><small>Přeskočené</small><strong>{preview.summary.skipped}</strong></span><span className={preview.summary.errors?"danger":""}><small>Chyby</small><strong>{preview.summary.errors}</strong></span></div><div className="import-preview-list">{preview.rows.slice(0,50).map(row=><div key={`${row.rowNumber}-${row.code}`}><span><strong>Řádek {row.rowNumber} · {row.code||"bez označení"}</strong><small>{row.errors.length?row.errors.join(" · "):row.action==="create"?"Nový záznam":row.action==="update"?"Aktualizace existujícího záznamu":"Přeskočeno"}</small></span><Badge tone={row.errors.length?"danger":row.action==="create"?"success":"neutral"}>{row.errors.length?"Chyba":row.action==="create"?"Nový":row.action==="update"?"Aktualizace":"Přeskočit"}</Badge></div>)}</div></>}</>}</FormModal>;
}

function spreadsheetNumber(value:unknown){if(typeof value==="number")return value;const normalized=String(value??"").replace(/\s/g,"").replace(",",".").replace(/[^0-9.-]/g,"");if(!normalized)return null;const parsed=Number(normalized);return Number.isFinite(parsed)?parsed:null;}
function excelCellValue(value:unknown):unknown{if(value&&typeof value==="object"){const item=value as {text?:string;result?:unknown;richText?:Array<{text:string}>};if(item.text!==undefined)return item.text;if(item.result!==undefined)return item.result;if(item.richText)return item.richText.map(part=>part.text).join("");}return value??"";}

function CreateAccessoryModal({inventory,initialCategory="parking",close,save}:{inventory:CatalogAccessoryRecord[];initialCategory?:"parking"|"cellar"|"wallbox";close:()=>void;save:(value:{category:"parking"|"cellar"|"wallbox";code:string;areaM2?:number|null;amount:number;amountNet?:number|null;relatedAccessoryId?:string|null})=>Promise<void>}){
  const [category,setCategory]=useState<"parking"|"cellar"|"wallbox">(initialCategory);const [code,setCode]=useState("");const [area,setArea]=useState("");const [amount,setAmount]=useState("");const [relation,setRelation]=useState("");
  return <FormModal title="Nové příslušenství" close={close} onSave={async()=>{const parsed=Number(amount.replace(/\s/g,"").replace(",","."));if(!code.trim())throw new Error("Doplňte označení příslušenství");if(!Number.isFinite(parsed)||parsed<0)throw new Error("Doplňte platnou cenu");await save({category,code:code.trim(),areaM2:area?Number(area.replace(",",".")):null,amount:parsed,relatedAccessoryId:category==="wallbox"&&relation?relation:null});}} saveLabel="Vytvořit"><div className="form-row"><label><span>Typ</span><select value={category} onChange={event=>setCategory(event.target.value as typeof category)}><option value="parking">Parkovací stání</option><option value="cellar">Sklep</option><option value="wallbox">Wallbox</option></select></label><label><span>Označení</span><input value={code} onChange={event=>setCode(event.target.value)} placeholder={category==="parking"?"P30":category==="cellar"?"S20":"W9"}/></label></div><div className="form-row">{category==="cellar"&&<label><span>Plocha m²</span><input inputMode="decimal" value={area} onChange={event=>setArea(event.target.value)}/></label>}<label><span>Cena včetně DPH</span><input inputMode="decimal" value={amount} onChange={event=>setAmount(event.target.value)}/></label>{category==="wallbox"&&<label><span>Navázané parkovací stání</span><select value={relation} onChange={event=>setRelation(event.target.value)}><option value="">Bez vazby</option>{inventory.filter(item=>item.category==="parking").map(item=><option key={item.id} value={item.id}>{item.code}</option>)}</select></label>}</div></FormModal>;
}

function ProjectOverview({ project, onTab,taskRows,paymentRows,handoverRows }: { project: ProjectRecord; onTab: (tab: ProjectTab) => void;taskRows:TaskRecord[];paymentRows:PaymentRecord[];handoverRows:HandoverRecord[] }) {
  const [projectActivity,setProjectActivity]=useState<TimelineRecord[]>([]);
  useEffect(()=>{const controller=new AbortController();const projectId=backendEntityId(project.backendId);if(!projectId){Promise.resolve().then(()=>setProjectActivity([]));return()=>controller.abort();}activityRepository.projectTimeline(projectId,controller.signal).then(setProjectActivity).catch(()=>setProjectActivity([]));return()=>controller.abort();},[project.backendId]);
  if(project.units===0)return <div className="project-empty-onboarding card"><span className="metric-icon green"><Building2 size={22}/></span><div><h2>Projekt je založený</h2><p>Zatím nemá strukturu ani jednotky. Souhrny se začnou počítat až ze skutečně vložených dat.</p><ol><li><CheckCircle2 size={16}/> Základní údaje projektu</li><li><Building2 size={16}/> Přidat etapy, budovy a sekce</li><li><Home size={16}/> Importovat nebo založit jednotky</li><li><KeyRound size={16}/> Doplnit příslušenství a ceny</li><li><Users size={16}/> Přiřadit uživatele projektu</li></ol><button className="primary-button" onClick={()=>onTab("units")}><Home size={16}/> Pokračovat k jednotkám</button></div></div>;
  const projectTasks = taskRows.filter((task) => taskBelongsToProject(task,project));
  const projectPayments = paymentRows;
  const projectHandovers = handoverRows;
  const projectUnitIds = units.filter((unit) => unitBelongsToProject(unit,project)).map((unit) => unit.id);
  const firstUnit = projectUnitIds[0] || "—";
  const nextPayment = projectPayments.find((payment) => payment.status !== "paid");
  const nextHandover = projectHandovers[0];
  const deadlines = [
    { date: "23. 7.", detail: `Kontrola smluvních dat ${firstUnit}`, tab: "contracts" as ProjectTab, icon: FileText },
    { date: nextPayment?formatPragueDate(nextPayment.dueAt):"—", detail: nextPayment ? `Splatnost · ${nextPayment.unit}` : "Bez nejbližší splatnosti", tab: "payments" as ProjectTab, icon: Clock3 },
    { date: nextHandover?formatPragueDate(nextHandover.scheduledAt):project.plannedHandover, detail: nextHandover ? `Příprava předání ${nextHandover.unit}` : "Milník předávání projektu", tab: "handovers" as ProjectTab, icon: CalendarDays },
  ];
  const paid = projectPayments.reduce((sum, payment) => sum + payment.paid, 0);
  const expected = projectPayments.reduce((sum, payment) => sum + payment.amount, 0);
  return (
    <div className="project-dashboard-grid">
      <div className="project-main-column">
        <section className="card project-work-card">
          <div className="project-section-head"><div><h2>Úkoly a vyžaduje pozornost</h2><p>Nejdůležitější práce v kontextu projektu.</p></div><Badge tone="danger">{project.attention} položek</Badge></div>
          <div className="project-work-list">
            {projectTasks.slice(0, 3).map((task) => { const title = task.title.toLowerCase(); return <button key={task.id} onClick={() => onTab(title.includes("platb") ? "payments" : title.includes("předání") ? "handovers" : "units")}><span className={`attention-type ${task.priority === "Vysoká" ? "danger" : "warning"}`}><AlertTriangle size={17} /></span><span><strong>{task.title}</strong><small>{task.object} · {task.owner}</small></span><Badge>{task.due}</Badge><ChevronRight size={16} /></button>; })}
            <button onClick={() => onTab("contracts")}><span className="attention-type blue"><FileText size={17} /></span><span><strong>Dokončit rozpracované smlouvy</strong><small>{contracts.filter((contract) => contractBelongsToProject(contract,project) && normalizeContractStatus(contract.statusCode??contract.state) !== "signed").length} smlouvy čekají na další krok</small></span><Badge tone="blue">Smlouvy</Badge><ChevronRight size={16} /></button>
          </div>
        </section>
        <section className="card project-activity-card"><div className="project-section-head"><div><h2>Poslední aktivita</h2><p>Smlouvy, platby, dokumenty a změny jednotek.</p></div><Badge tone="neutral">{project.name}</Badge></div><div className="timeline-mini project-activity-list">{projectActivity.length ? projectActivity.slice(0, 5).map((item) => <div key={item.id}><span className={`timeline-icon ${item.icon}`}><Activity size={16} /></span><span><strong>{item.title}</strong><small>{item.detail}</small></span><time>{formatPragueDateTime(item.date)}</time></div>) : <div><span className="timeline-icon"><Activity size={16} /></span><span><strong>Zatím bez nové aktivity</strong><small>Nové změny projektu se zobrazí zde.</small></span></div>}</div></section>
      </div>
      <aside className="project-side-column">
        <section className="card project-deadlines-card"><SectionTitle title="Nejbližší termíny" /><div>{deadlines.map((deadline) => { const Icon = deadline.icon; return <button key={`${deadline.date}-${deadline.detail}`} onClick={() => onTab(deadline.tab)}><Icon size={18} /><span><strong>{deadline.date}</strong><small>{deadline.detail}</small></span><ChevronRight size={16} /></button>; })}</div></section>
        <section className="card project-brief-card"><div className="project-section-head"><div><h2>Platby</h2><p>Stručný finanční přehled.</p></div><button className="text-button" onClick={() => onTab("payments")}>Detail <ArrowRight size={14} /></button></div><strong>{formatMoney(paid)}</strong><small>uhrazeno z evidovaných {formatMoney(expected)}</small><span className="payment-progress"><i style={{ width: `${expected ? paid / expected * 100 : 0}%` }} /></span><p>{projectPayments.filter((payment) => payment.status === "overdue").length} položek po splatnosti</p></section>
        <section className="card project-brief-card"><div className="project-section-head"><div><h2>Připravovaná předání</h2><p>Nejbližší jednotky k dokončení.</p></div><button className="text-button" onClick={() => onTab("handovers")}>Detail <ArrowRight size={14} /></button></div>{projectHandovers.length ? projectHandovers.slice(0, 3).map((handover) => <button className="project-brief-row" key={handover.id} onClick={() => onTab("handovers")}><span><strong>{handover.unit}</strong><small>{handover.client || "Bez klienta"}</small></span><Badge>{formatPragueDate(handover.scheduledAt)}</Badge></button>) : <p>Termíny předání zatím nejsou naplánované.</p>}</section>
      </aside>
    </div>
  );
}

function ProjectUnitList(props: UnitListProps&{canManage:boolean;onCatalogChanged:()=>void}) {
  const router=useRouter();const pathname=usePathname();const searchParams=useSearchParams();
  const columnState=useTableColumns("units-table",unitTableColumns);
  const [creating,setCreating]=useState(false);const [importing,setImporting]=useState(false);
  const { project, unitView, setUnitView, filteredUnits, previewUnit, openUnit, buildingFilter, floorFilter, statusFilter, layoutFilter, areaFrom, areaTo, priceFrom, priceTo,unitQuery,setUnitQuery,clientQuery,setClientQuery } = props;
  const projectUnits = units.filter((unit) => unitBelongsToProject(unit,project));
  const buildings = Array.from(new Set(projectUnits.map((unit) => unit.building)));
  const floors = Array.from(new Set(projectUnits.map((unit) => unit.floor)));
  const filteredVisibleUnits = filteredUnits.filter((unit) => unit.id.toLowerCase().includes(unitQuery.toLowerCase()) && (unit.client || "").toLowerCase().includes(clientQuery.toLowerCase()));
  const sort=searchParams.get("sort")??"code";const direction=(searchParams.get("dir")==="desc"?"desc":"asc") as SortDirection;
  const visibleUnits=stableSort(filteredVisibleUnits,unit=>sort==="floor"?unit.floor:sort==="layout"?unit.layout:sort==="price"?unit.price:sort==="status"?unit.status:sort==="updated"?unit.updatedAt??"":unit.id,direction,unit=>unit.backendId??unit.id);
  const activeCount = [unitQuery, buildingFilter.length, floorFilter.length, statusFilter.length, layoutFilter.length, areaFrom, areaTo, priceFrom, priceTo, clientQuery].filter(Boolean).length;
  const reset = props.resetFilters;
  return (
    <section className="card units-section">
      <div className="list-action-toolbar"><span className="compact-result-count"><strong>{visibleUnits.length}</strong> jednotek {activeCount>0&&<Badge tone="blue">{activeCount} filtrů</Badge>}{activeCount>0&&<button className="text-button" onClick={reset}>Vymazat</button>}</span><span className="list-toolbar-actions">{unitView==="table"&&<TableColumnMenu columns={unitTableColumns} state={columnState}/>} {props.canManage&&<><button className="secondary-button compact" onClick={()=>setImporting(true)}><Upload size={16}/> Importovat jednotky</button><button className="primary-button compact" onClick={()=>setCreating(true)}><Plus size={16}/> Přidat jednotku</button></>}<span className="view-toggle"><button className={unitView === "table" ? "active" : ""} onClick={() => setUnitView("table")} aria-label="Tabulkové zobrazení" title="Seznam"><List size={17} /></button><button className={unitView === "cards" ? "active" : ""} onClick={() => setUnitView("cards")} aria-label="Kartové zobrazení" title="Karty"><LayoutGrid size={17} /></button></span></span></div>
      {unitView === "table" ? <div className="unit-table-wrap"><table className="data-table unit-table filter-table configurable-table"><thead><tr><TableColumnFilter className="column-primary" label="Jednotka" active={Boolean(unitQuery)} sortDirection={sort==="code"?direction:undefined} onSort={next=>router.replace(updateSearch(pathname,searchParams.toString(),{sort:"code",dir:next}),{scroll:false})}><input value={unitQuery} onChange={(event) => setUnitQuery(event.target.value)} placeholder="A203…" aria-label="Filtrovat jednotky" /></TableColumnFilter>{columnState.isVisible("building")&&<TableColumnFilter label="Budova / etapa" active={buildingFilter.length > 0}><MultiSelectFilter options={buildings} selected={buildingFilter} onChange={props.setBuildingFilter} allLabel="Všechny budovy / etapy" ariaLabel="Filtrovat budovu nebo etapu" /></TableColumnFilter>}{columnState.isVisible("floor")&&<TableColumnFilter label="Podlaží" active={floorFilter.length > 0} sortDirection={sort==="floor"?direction:undefined} onSort={next=>router.replace(updateSearch(pathname,searchParams.toString(),{sort:"floor",dir:next}),{scroll:false})}><MultiSelectFilter options={floors} selected={floorFilter} onChange={props.setFloorFilter} allLabel="Všechna podlaží" ariaLabel="Filtrovat podlaží" /></TableColumnFilter>}{columnState.isVisible("layout")&&<TableColumnFilter label="Dispozice" active={layoutFilter.length > 0} sortDirection={sort==="layout"?direction:undefined} onSort={next=>router.replace(updateSearch(pathname,searchParams.toString(),{sort:"layout",dir:next}),{scroll:false})}><MultiSelectFilter options={["1+kk", "2+kk", "3+kk", "4+kk", "5+kk"]} selected={layoutFilter} onChange={props.setLayoutFilter} allLabel="Všechny dispozice" ariaLabel="Filtrovat dispozici" /></TableColumnFilter>}{columnState.isVisible("area")&&<TableColumnFilter label="Podlahová plocha" active={Boolean(areaFrom || areaTo)} sortType="number"><span className="column-range"><input inputMode="decimal" value={areaFrom} onChange={(event) => props.setAreaFrom(event.target.value)} placeholder="Od" aria-label="Plocha od" /><i>–</i><input inputMode="decimal" value={areaTo} onChange={(event) => props.setAreaTo(event.target.value)} placeholder="Do" aria-label="Plocha do" /></span></TableColumnFilter>}{columnState.isVisible("usableArea")&&<th>Užitná plocha</th>}{columnState.isVisible("balcony")&&<th>Balkon</th>}{columnState.isVisible("terrace")&&<th>Terasa</th>}{columnState.isVisible("garden")&&<th>Zahrada</th>}{columnState.isVisible("orientation")&&<th>Orientace</th>}{columnState.isVisible("basePrice")&&<TableColumnFilter label="Cena jednotky" active={Boolean(priceFrom || priceTo)} sortType="number" sortDirection={sort==="price"?direction:undefined} onSort={next=>router.replace(updateSearch(pathname,searchParams.toString(),{sort:"price",dir:next}),{scroll:false})}><span className="column-range"><input inputMode="decimal" value={priceFrom} onChange={(event) => props.setPriceFrom(event.target.value)} placeholder="Od mil." aria-label="Cena od" /><i>–</i><input inputMode="decimal" value={priceTo} onChange={(event) => props.setPriceTo(event.target.value)} placeholder="Do mil." aria-label="Cena do" /></span></TableColumnFilter>}{columnState.isVisible("accessoryPrice")&&<th>Cena příslušenství</th>}{columnState.isVisible("totalPrice")&&<th>Celková cena</th>}{columnState.isVisible("status")&&<TableColumnFilter label="Obchodní stav" active={statusFilter.length > 0} sortDirection={sort==="status"?direction:undefined} onSort={next=>router.replace(updateSearch(pathname,searchParams.toString(),{sort:"status",dir:next}),{scroll:false})}><MultiSelectFilter options={["Volný", "Předrezervace", "Rezervovaná", "SBK", "KS", "Předáno"]} selected={statusFilter} onChange={props.setStatusFilter} allLabel="Všechny stavy" ariaLabel="Filtrovat obchodní stav" /></TableColumnFilter>}{columnState.isVisible("construction")&&<th>Stav výstavby</th>}{columnState.isVisible("client")&&<TableColumnFilter label="Klient" active={Boolean(clientQuery)}><input value={clientQuery} onChange={(event) => setClientQuery(event.target.value)} placeholder="Jméno…" aria-label="Filtrovat klienta" /></TableColumnFilter>}{columnState.isVisible("cellar")&&<th>Sklep</th>}{columnState.isVisible("parking")&&<th>Parkovací místa</th>}{columnState.isVisible("wallbox")&&<th>Wallbox</th>}{columnState.isVisible("handover")&&<th>Předání</th>}<th /></tr></thead><tbody>{visibleUnits.map((unit) => {const accessory=(kind:string)=>unit.accessories?.filter(item=>item.category===kind).map(item=>item.code).join(", ")||"—";return <tr key={unit.id} onClick={() => openUnit(unit)} tabIndex={0} onKeyDown={(event) => event.key === "Enter" && openUnit(unit)}><td className="column-primary"><strong>{unit.id}</strong></td>{columnState.isVisible("building")&&<td>{unit.building}</td>}{columnState.isVisible("floor")&&<td>{unit.floor}</td>}{columnState.isVisible("layout")&&<td>{unit.layout}</td>}{columnState.isVisible("area")&&<td>{unit.area.toLocaleString("cs-CZ")} m²</td>}{columnState.isVisible("usableArea")&&<td>{unit.usableArea!=null?`${unit.usableArea.toLocaleString("cs-CZ")} m²`:"—"}</td>}{columnState.isVisible("balcony")&&<td>{unit.balcony!=null?`${unit.balcony.toLocaleString("cs-CZ")} m²`:"—"}</td>}{columnState.isVisible("terrace")&&<td>{unit.terrace!=null?`${unit.terrace.toLocaleString("cs-CZ")} m²`:"—"}</td>}{columnState.isVisible("garden")&&<td>{unit.garden!=null?`${unit.garden.toLocaleString("cs-CZ")} m²`:"—"}</td>}{columnState.isVisible("orientation")&&<td>{unit.orientation||"—"}</td>}{columnState.isVisible("basePrice")&&<td><strong>{formatMoney(unit.basePrice??unit.price)}</strong></td>}{columnState.isVisible("accessoryPrice")&&<td>{formatMoney(unit.accessoryPrice??0)}</td>}{columnState.isVisible("totalPrice")&&<td><strong>{formatMoney(unit.price)}</strong></td>}{columnState.isVisible("status")&&<td><Badge>{unit.status}</Badge></td>}{columnState.isVisible("construction")&&<td>{unit.construction||"—"}</td>}{columnState.isVisible("client")&&<td>{unit.client || <span className="muted">—</span>}</td>}{columnState.isVisible("cellar")&&<td>{accessory("cellar")}</td>}{columnState.isVisible("parking")&&<td>{accessory("parking")}</td>}{columnState.isVisible("wallbox")&&<td>{accessory("wallbox")}</td>}{columnState.isVisible("handover")&&<td>{unit.handover||"—"}</td>}<td><ChevronRight size={18} /></td></tr>})}</tbody></table></div> : <div className="unit-card-grid">{visibleUnits.map((unit) => <button className="unit-card" key={unit.id} onClick={() => previewUnit(unit)}><span className="unit-card-top"><strong>{unit.id}</strong><Badge>{unit.status}</Badge></span><span className="unit-card-plan"><span className="plan-room r1" /><span className="plan-room r2" /><span className="plan-room r3" /><Home size={22} /></span><span className="unit-card-info"><strong>{unit.layout} · {unit.area.toLocaleString("cs-CZ")} m²</strong><small>{unit.building} · {unit.floor}</small></span><span className="unit-card-price"><strong>{formatMoney(unit.price)}</strong><ChevronRight size={17} /></span></button>)}</div>}
      {!visibleUnits.length && <div className="empty-filter-state"><Search size={22} /><strong>Žádná jednotka neodpovídá kombinaci filtrů</strong><small>Zkuste upravit filtry přímo v hlavičce tabulky.</small><button className="secondary-button compact" onClick={reset}>Vymazat filtry</button></div>}
      {creating&&<CreateUnitModal project={project} close={()=>setCreating(false)} save={async row=>{const projectId=backendEntityId(project.backendId);if(!projectId)throw new Error("Projekt nemá platný databázový identifikátor");await catalogRepository.createUnit(projectId,row);setCreating(false);props.onCatalogChanged();}}/>}
      {importing&&<InventoryImportModal project={project} entityType="unit" close={()=>setImporting(false)} completed={()=>{setImporting(false);props.onCatalogChanged();}}/>}
    </section>
  );
}

function ProjectClients({ project, openClient, openUnit, notify }: { project: ProjectRecord; openClient: (name: string) => void; openUnit: (unit: UnitRecord) => void; notify: (message: string) => void }) {
  const columnState=useTableColumns("clients-table",clientTableColumns);
  const [rows,setRows]=useState<ClientRecord[]>(()=>clients.filter((client) => clientBelongsToProject(client,project)));
  useEffect(()=>{const controller=new AbortController();const projectId=backendEntityId(project.backendId);if(!projectId)return()=>controller.abort();clientRepository.getPage({page:1,pageSize:100,projectId},controller.signal).then(result=>setRows(result.clients)).catch(()=>setRows([]));return()=>controller.abort();},[project.backendId]);
  return <ProjectModuleFrame label="Klienti" summary={<span className="compact-result-count"><strong>{rows.length}</strong> klientů</span>} tools={<TableColumnMenu columns={clientTableColumns} state={columnState}/>} action="Přidat klienta" onAction={() => notify("Formulář nového klienta je připraven")}><table className="data-table configurable-table"><thead><tr><th className="column-primary">Klient</th>{columnState.isVisible("type")&&<th>Typ</th>}{columnState.isVisible("units")&&<th>Jednotky v projektu</th>}{columnState.isVisible("relation")&&<th>Stav vztahu</th>}{columnState.isVisible("contract")&&<th>Smluvní stav</th>}{columnState.isVisible("phone")&&<th>Telefon</th>}{columnState.isVisible("email")&&<th>E-mail</th>}<th /></tr></thead><tbody>{rows.map((client) => <tr key={client.id} onClick={() => openClient(client.name)}><td className="column-primary"><span className="client-name-cell"><Avatar initials={client.initials} small /><strong>{client.name}</strong></span></td>{columnState.isVisible("type")&&<td><Badge tone="neutral">{client.kind}</Badge></td>}{columnState.isVisible("units")&&<td><ClientUnitChips client={client} project={project} openUnit={openUnit}/></td>}{columnState.isVisible("relation")&&<td><Badge>{client.state}</Badge></td>}{columnState.isVisible("contract")&&<td>{clientContractStatus(client,project)}</td>}{columnState.isVisible("phone")&&<td>{client.phone}</td>}{columnState.isVisible("email")&&<td>{client.email}</td>}<td><ChevronRight size={17} /></td></tr>)}</tbody></table></ProjectModuleFrame>;
}

function ProjectContracts({ project, openUnit,openContract, notify }: { project: ProjectRecord; openUnit: (unit: UnitRecord) => void;openContract:(contract:(typeof contracts)[number])=>void; notify: (message: string) => void }) {
  const columnState=useTableColumns("contracts-table",contractTableColumns);
  const [rows,setRows]=useState<ContractRecord[]>(()=>contracts.filter((contract) => contractBelongsToProject(contract,project)));
  useEffect(()=>{const controller=new AbortController();const projectId=backendEntityId(project.backendId);if(!projectId)return()=>controller.abort();commercialRepository.getSnapshot(controller.signal,projectId).then(snapshot=>setRows(snapshot.contracts)).catch(()=>setRows([]));return()=>controller.abort();},[project.backendId]);
  return <ProjectModuleFrame label="Smlouvy" summary={<span className="compact-result-count"><strong>{rows.length}</strong> smluv</span>} tools={<TableColumnMenu columns={contractTableColumns} state={columnState}/>} action="Nová smlouva" onAction={() => notify("Formulář nové smlouvy je připraven")}><table className="data-table configurable-table"><thead><tr><th className="column-primary">Smlouva</th>{columnState.isVisible("unit")&&<th>Jednotka</th>}{columnState.isVisible("client")&&<th>Klient</th>}{columnState.isVisible("type")&&<th>Typ smlouvy</th>}{columnState.isVisible("status")&&<th>Stav</th>}{columnState.isVisible("updated")&&<th>Aktualizováno</th>}{columnState.isVisible("owner")&&<th>Odpovědná osoba</th>}<th /></tr></thead><tbody>{rows.map((contract) => <tr key={`${contract.unit}-${contract.type}`} onClick={() => openContract(contract)}><td className="column-primary"><strong>{contract.reference??`${contract.type} · ${contract.unit}`}</strong></td>{columnState.isVisible("unit")&&<td><button className="unit-link" onClick={event=>{event.stopPropagation();const unit=units.find(item=>item.id===contract.unit);if(unit)openUnit(unit);}}>{contract.unit}</button></td>}{columnState.isVisible("client")&&<td>{contract.client}</td>}{columnState.isVisible("type")&&<td><Badge tone="blue">{contract.type}</Badge></td>}{columnState.isVisible("status")&&<td><Badge>{displayedContractStatus(contract)}</Badge></td>}{columnState.isVisible("updated")&&<td>{contract.updated}</td>}{columnState.isVisible("owner")&&<td>{contract.owner}</td>}<td><ChevronRight size={17} /></td></tr>)}</tbody></table></ProjectModuleFrame>;
}

function ProjectPayments({ project, openUnit }: { project: ProjectRecord; openUnit: (unit: UnitRecord) => void }) {
  return <PaymentContextTable title="Platby projektu" description="Splátkový kalendář a skutečné úhrady z centrálního platebního repository." filters={{projectId:project.backendId}} openUnit={openUnit} project={project}/>;
}

function ProjectClientChanges({ project,openUnit, notify }: { project: ProjectRecord; openUnit: (unit: UnitRecord) => void; notify: (message: string) => void }) {
  return <ClientChangesWorkspace project={project} openUnit={openUnit} notify={notify}/>;
}

function ProjectHandovers({rows, openUnit,onNew }: { project: ProjectRecord;rows:HandoverRecord[]; openUnit: (unit: UnitRecord) => void;onNew?:()=>void }) {
  const columnState=useTableColumns("handovers-table",handoverTableColumns);
  return <ProjectModuleFrame label="Předání" summary={<span className="compact-result-count"><strong>{rows.length}</strong> předání</span>} tools={<TableColumnMenu columns={handoverTableColumns} state={columnState}/>} action={onNew?"Naplánovat předání":undefined} onAction={onNew}><table className="data-table configurable-table"><thead><tr><th className="column-primary">Jednotka</th>{columnState.isVisible("client")&&<th>Klient</th>}{columnState.isVisible("date")&&<th>Termín</th>}{columnState.isVisible("place")&&<th>Místo</th>}{columnState.isVisible("status")&&<th>Stav</th>}{columnState.isVisible("readiness")&&<th>Připravenost</th>}<th /></tr></thead><tbody>{rows.map(row=>{const unit=units.find(item=>item.backendId===row.unitId||item.id===row.unit);return <tr key={row.id} onClick={()=>unit&&openUnit(unit)}><td className="column-primary"><strong>{row.unit}</strong></td>{columnState.isVisible("client")&&<td>{row.client}</td>}{columnState.isVisible("date")&&<td>{formatPragueDateTime(row.scheduledAt)}</td>}{columnState.isVisible("place")&&<td>{row.place??"—"}</td>}{columnState.isVisible("status")&&<td><Badge>{handoverStatusLabel(row.status)}</Badge></td>}{columnState.isVisible("readiness")&&<td><span className="readiness"><span><strong>{row.readiness} %</strong></span><div><i style={{width:`${row.readiness}%`}}/></div></span></td>}<td><ChevronRight size={17}/></td></tr>})}</tbody></table>{!rows.length&&<div className="empty-filter-state"><KeyRound size={22}/><strong>Žádné naplánované předání</strong><small>První termín založíte tlačítkem vpravo.</small></div>}</ProjectModuleFrame>;
}

function ProjectDocuments({ project, notify }: { project: ProjectRecord; notify: (message: string) => void }) {
  const [documents,setDocuments]=useState<DocumentRecord[]>([]);const [connection,setConnection]=useState<DocumentConnectionState>(previewConnection);const [loading,setLoading]=useState(true);
  const [category,setCategory]=useState("");const [unitId,setUnitId]=useState("");const [partyId,setPartyId]=useState("");
  const projectUnits=units.filter(unit=>unitBelongsToProject(unit,project));const projectClients=clients.filter(client=>clientBelongsToProject(client,project));
  useEffect(()=>{const controller=new AbortController();documentRepository.listProject(project.backendId??project.code,{category:category||undefined,unitId:unitId||undefined,partyId:partyId||undefined},controller.signal).then(result=>{setDocuments(result.documents);setConnection(result.connection);}).catch(()=>{setDocuments([]);setConnection(previewConnection);}).finally(()=>setLoading(false));return()=>controller.abort();},[project.backendId,project.code,category,unitId,partyId]);
  return <ProjectModuleFrame label="Dokumenty"><DocumentConnectionBanner connection={connection}/><div className="module-toolbar document-toolbar"><div className="inline-search"><Search size={17}/><span>{loading?"Načítám dokumenty…":`${documents.length} dokumentů`}</span></div><label><span>Kategorie</span><select value={category} onChange={event=>{setLoading(true);setCategory(event.target.value);}}><option value="">Všechny kategorie</option>{documentCategoryOptions.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label><label><span>Jednotka</span><select value={unitId} onChange={event=>{setLoading(true);setUnitId(event.target.value);}}><option value="">Všechny jednotky</option>{projectUnits.map(unit=><option key={unit.id} value={unit.backendId??unit.id}>{unit.id}</option>)}</select></label><label><span>Klient</span><select value={partyId} onChange={event=>{setLoading(true);setPartyId(event.target.value);}}><option value="">Všichni klienti</option>{projectClients.map(client=><option key={client.id} value={client.id}>{client.name}</option>)}</select></label></div><DocumentList documents={documents} loading={loading} notify={notify}/></ProjectModuleFrame>;
}

function ProjectModuleFrame({ label, summary, tools, action, onAction, children }: { label: string; summary?:React.ReactNode; tools?:React.ReactNode; action?: string; onAction?: () => void; children: React.ReactNode }) {
  return <section className="card detail-tab-card project-module-card" aria-label={label}>{(summary||tools||action)&&<div className="list-action-toolbar">{summary??<span/>}<span className="list-toolbar-actions">{tools}{action&&<button className="primary-button" onClick={onAction}><Plus size={16} /> {action}</button>}</span></div>}<div className="unit-table-wrap">{children}</div></section>;
}

function ClientsPage({ openUnit,openProject, selectedClientName, setSelectedClientName, notify, onEditClient,onClientArchived }: { openUnit: (unit: UnitRecord) => void;openProject:(project:ProjectRecord)=>void; selectedClientName: string | null; setSelectedClientName: (name: string | null) => void; notify: (message: string) => void; onEditClient?: (client: (typeof clients)[number]) => void;onClientArchived?:()=>void }) {
  const clientRouter=useRouter();const clientPathname=usePathname();const clientParams=useSearchParams();
  const columnState=useTableColumns("clients-table",clientTableColumns);
  const [query, setQuery] = useState(clientParams.get("cq")??"");
  const [quickProject, setQuickProject] = useState(clientParams.get("cp")??"Všichni");
  const [typeFilter, setTypeFilter] = useState<string[]>(listParam(clientParams,"ct"));
  const [projectFilter, setProjectFilter] = useState<string[]>(listParam(clientParams,"cproj"));
  const [unitFilter, setUnitFilter] = useState(clientParams.get("cu")??"");
  const [relationFilter, setRelationFilter] = useState<string[]>(listParam(clientParams,"cr"));
  const [contractFilter, setContractFilter] = useState<string[]>(listParam(clientParams,"cc"));
  const [phoneFilter, setPhoneFilter] = useState(clientParams.get("cph")??"");
  const [emailFilter, setEmailFilter] = useState(clientParams.get("cem")??"");
  const [selected, setSelected] = useState<Set<string>>(new Set());
  useEffect(()=>{
    // URL parametry jsou sdílitelný stav seznamu a při Back/Forward se musí znovu propsat do ovládacích prvků.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setQuery(clientParams.get("cq")??"");setQuickProject(clientParams.get("cp")??"Všichni");setTypeFilter(listParam(clientParams,"ct"));setProjectFilter(listParam(clientParams,"cproj"));setUnitFilter(clientParams.get("cu")??"");setRelationFilter(listParam(clientParams,"cr"));setContractFilter(listParam(clientParams,"cc"));setPhoneFilter(clientParams.get("cph")??"");setEmailFilter(clientParams.get("cem")??"");
  },[clientParams]);
  const writeClientFilter=(key:string,value:string|string[])=>clientRouter.replace(updateSearch(clientPathname,clientParams.toString(),{[key]:value,clientPage:""}),{scroll:false});
  const writeClientText=(key:string,value:string,setter:React.Dispatch<React.SetStateAction<string>>)=>{setter(value);writeClientFilter(key,value);};
  const writeClientList=(key:string,value:string[],setter:React.Dispatch<React.SetStateAction<string[]>>)=>{setter(value);writeClientFilter(key,value);};
  let selectedClient = selectedClientName ? clients.find((client) => client.name === selectedClientName) : undefined;
  const filtered = useMemo(() => clients.filter((client) => {
    const searchMatch = client.name.toLowerCase().includes(query.toLowerCase());
    const quickProjectRecord=projects.find(project=>project.name===quickProject);
    const quickMatch = quickProject === "Všichni" || client.projectNames.some(name=>quickProjectRecord?projectMatchesName(quickProjectRecord,name):name===quickProject);
    const typeMatch = typeFilter.length === 0 || typeFilter.includes(client.kind);
    const projectMatch = projectFilter.length === 0 || projectFilter.some((name) => {const project=projects.find(item=>item.name===name);return client.projectNames.some(clientProject=>project?projectMatchesName(project,clientProject):clientProject===name);});
    const unitMatch = client.units.join(" ").toLowerCase().includes(unitFilter.toLowerCase());
    const relationMatch = relationFilter.length === 0 || relationFilter.includes(client.lifecycleStatus==="archived"?"Archivovaný":client.state);
    const contractMatch = contractFilter.length === 0 || contractFilter.some(status=>client.contractStatus.startsWith(status));
    const phoneMatch = client.phone.toLowerCase().includes(phoneFilter.toLowerCase());
    const emailMatch = client.email.toLowerCase().includes(emailFilter.toLowerCase());
    return searchMatch && quickMatch && typeMatch && projectMatch && unitMatch && relationMatch && contractMatch && phoneMatch && emailMatch;
  }), [query, quickProject, typeFilter, projectFilter, unitFilter, relationFilter, contractFilter, phoneFilter, emailFilter]);
  const clientSort=clientParams.get("sort")??"name";const clientDirection=(clientParams.get("dir")==="desc"?"desc":"asc") as SortDirection;
  const sortedClients=useMemo(
    ()=>stableSort(filtered,client=>clientSort==="updated"?client.updatedAt??"":clientSort==="relation"?client.state:clientSort==="contract"?client.contractStatus:clientSort==="project"?client.projectNames.join(" "):clientSort==="unit"?client.units.join(" "):client.name,clientDirection,client=>client.id),
    [filtered,clientSort,clientDirection],
  );
  const pageSize=25;const [serverPage,setServerPage]=useState<{clients:(typeof clients)[number][];total:number;page:number;loading:boolean}>({clients:[],total:0,page:0,loading:true});const clientSentinelRef=useRef<HTMLDivElement>(null);
  const pageInput=useMemo(()=>({pageSize,query,quickProject,types:typeFilter,projects:projectFilter,unit:unitFilter,relations:relationFilter,contracts:contractFilter,phone:phoneFilter,email:emailFilter,sort:clientSort,direction:clientDirection,includeArchived:relationFilter.includes("Archivovaný")}),[query,quickProject,typeFilter,projectFilter,unitFilter,relationFilter,contractFilter,phoneFilter,emailFilter,clientSort,clientDirection]);
  const filterKey=JSON.stringify(pageInput);
  useEffect(()=>{const controller=new AbortController();const fallback=()=>setServerPage({clients:sortedClients.slice(0,pageSize),total:sortedClients.length,page:1,loading:false});const timeout=window.setTimeout(()=>{controller.abort();fallback();},5000);queueMicrotask(()=>{if(controller.signal.aborted)return;setServerPage({clients:sortedClients.slice(0,pageSize),total:sortedClients.length,page:0,loading:true});clientRepository.getPage({...pageInput,page:1},controller.signal).then(result=>{window.clearTimeout(timeout);setServerPage({clients:result.clients,total:result.total,page:1,loading:false});requestAnimationFrame(()=>{const saved=Number(sessionStorage.getItem(`develocrm.clients.scroll:${filterKey}`)||0);window.scrollTo({top:saved});});}).catch(()=>{window.clearTimeout(timeout);fallback();});});return()=>{window.clearTimeout(timeout);controller.abort();};},[filterKey,pageInput,sortedClients]);
  useEffect(()=>{const remember=()=>sessionStorage.setItem(`develocrm.clients.scroll:${filterKey}`,String(window.scrollY));window.addEventListener("scroll",remember,{passive:true});return()=>window.removeEventListener("scroll",remember);},[filterKey]);
  useEffect(()=>{const sentinel=clientSentinelRef.current;if(!sentinel||serverPage.loading||serverPage.clients.length>=serverPage.total)return;const observer=new IntersectionObserver(entries=>{if(!entries[0]?.isIntersecting)return;setServerPage(current=>({...current,loading:true}));clientRepository.getPage({...pageInput,page:serverPage.page+1}).then(result=>setServerPage(current=>({clients:[...current.clients,...result.clients.filter(item=>!current.clients.some(existing=>existing.id===item.id))],total:result.total,page:result.page,loading:false}))).catch(()=>setServerPage(current=>({...current,loading:false})));},{root:null,rootMargin:"360px"});observer.observe(sentinel);return()=>observer.disconnect();},[filterKey,pageInput,serverPage.page,serverPage.loading,serverPage.clients.length,serverPage.total]);
  const pageRows=serverPage.clients;
  if(selectedClientName&&!selectedClient)selectedClient=pageRows.find(client=>client.name===selectedClientName);
  const allPageSelected = pageRows.length > 0 && pageRows.every((client) => selected.has(client.id));
  const selectedRows = clients.filter((client) => selected.has(client.id));
  const toggle = (id: string) => setSelected((current) => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  const togglePage = () => setSelected((current) => { const next = new Set(current); pageRows.forEach((client) => allPageSelected ? next.delete(client.id) : next.add(client.id)); return next; });
  const selectAllResults = () => setSelected(new Set(filtered.map((client) => client.id)));
  const copyEmails = async () => { try { const result=await clientRepository.exportContacts(selectedRows.map((client)=>client.id),"bcc"); await navigator.clipboard.writeText(result.value); notify(`${result.count} e-mailů bylo zkopírováno pro BCC`); } catch { notify("Export není v tomto rozsahu povolen"); } };
  const downloadCsv = async (onlyEmails = false) => {
    try {
      const result=await clientRepository.exportContacts(selectedRows.map((client)=>client.id),onlyEmails?"bcc":"csv");
      const csv=onlyEmails?`\ufeffE-mail\n${result.value.split("; ").map((email)=>`"${email}"`).join("\n")}`:result.value;
      const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = onlyEmails ? "develocrm-emaily.csv" : "develocrm-klienti.csv"; link.click(); URL.revokeObjectURL(url); notify("Export byl stažen");
    } catch { notify("Export není v tomto rozsahu povolen"); }
  };
  if (selectedClient) return <><ClientDetail client={selectedClient} onBack={() => setSelectedClientName(null)} openUnit={openUnit} openProject={openProject} onEdit={onEditClient?() => onEditClient(selectedClient):undefined} onArchived={onClientArchived} /><PaymentContextTable title={`Platby klienta ${selectedClient.name}`} description="Předpisy ze všech projektů a jednotek tohoto klienta." filters={{partyId:selectedClient.id}}/></>;
  return (
    <section className="card module-card">
      <div className="client-quick-views"><div className="client-view-title"><span><Building2 size={17} /></span><span><small>RYCHLÝ POHLED</small><strong>Klienti podle projektu</strong></span></div><div className="client-view-options" role="tablist" aria-label="Klienti podle projektu"><button role="tab" aria-selected={quickProject==="Všichni"} className={quickProject === "Všichni" ? "active" : ""} onClick={() => writeClientText("cp","Všichni",setQuickProject)}>Všichni <span>{clients.length}</span></button>{projects.map((project) => <button role="tab" aria-selected={quickProject===project.name} key={project.name} className={quickProject === project.name ? "active" : ""} onClick={() => writeClientText("cp",project.name,setQuickProject)}>{project.name}</button>)}</div></div>
      <div className="module-toolbar client-list-toolbar"><label className="inline-search"><Search size={17}/><input value={query} onChange={event=>writeClientText("cq",event.target.value,setQuery)} placeholder="Hledat jméno, telefon nebo e-mail…" aria-label="Vyhledat klienta"/></label><span className="result-count">{filtered.length} klientů</span><TableColumnMenu columns={clientTableColumns} state={columnState}/></div>
      {selected.size > 0 && <div className="bulk-action-bar"><span><CheckCircle2 size={18} /><strong>Vybráno {selected.size} klientů</strong></span><div><button onClick={copyEmails}><Mail size={15} /> Kopírovat e-maily pro BCC</button><button onClick={() => downloadCsv(false)}><Download size={15} /> Excel / CSV</button><button onClick={() => downloadCsv(true)}><FileText size={15} /> Pouze e-maily</button><button className="ghost-icon" onClick={() => setSelected(new Set())} aria-label="Zrušit výběr"><X size={17} /></button></div></div>}
      {allPageSelected && filtered.length > pageRows.length && selected.size < filtered.length && <div className="select-all-results"><Check size={15} /> Vybráno všech {pageRows.length} načtených klientů. <button onClick={selectAllResults}>Vybrat všech {filtered.length} výsledků aktuálního filtru</button></div>}
      <div className="unit-table-wrap client-infinite-table"><table className="data-table client-table filter-table configurable-table"><thead><tr><th className="checkbox-cell"><button className={`table-checkbox ${allPageSelected ? "checked" : ""}`} onClick={togglePage} aria-label="Vybrat načtené klienty">{allPageSelected && <Check size={13} />}</button></th><TableColumnFilter className="column-primary" label="Jméno / název" active={Boolean(query)}><input value={query} onChange={(event) => writeClientText("cq",event.target.value,setQuery)} placeholder="Hledat jméno…" aria-label="Filtrovat jméno nebo název" /></TableColumnFilter>{columnState.isVisible("type")&&<TableColumnFilter label="Typ" active={typeFilter.length > 0}><MultiSelectFilter options={["FO", "PO"]} selected={typeFilter} onChange={value=>writeClientList("ct",value,setTypeFilter)} allLabel="Všechny typy" ariaLabel="Filtrovat typ klienta" /></TableColumnFilter>}{columnState.isVisible("project")&&<TableColumnFilter label="Projekt" active={projectFilter.length > 0}><MultiSelectFilter options={projects.map((project) => project.name)} selected={projectFilter} onChange={value=>writeClientList("cproj",value,setProjectFilter)} allLabel="Všechny projekty" ariaLabel="Filtrovat projekt" /></TableColumnFilter>}{columnState.isVisible("units")&&<TableColumnFilter className="client-unit-column" label="Jednotka / jednotky" active={Boolean(unitFilter)}><input value={unitFilter} onChange={(event) => writeClientText("cu",event.target.value,setUnitFilter)} placeholder="A203…" aria-label="Filtrovat jednotku" /></TableColumnFilter>}{columnState.isVisible("relation")&&<TableColumnFilter label="Stav vztahu" active={relationFilter.length > 0}><MultiSelectFilter options={["Zájemce", "Aktivní klient", "Předání", "Předáno", "Archivovaný"]} selected={relationFilter} onChange={value=>writeClientList("cr",value,setRelationFilter)} allLabel="Všechny vztahy" ariaLabel="Filtrovat stav vztahu" /></TableColumnFilter>}{columnState.isVisible("contract")&&<TableColumnFilter label="Smluvní stav" active={contractFilter.length > 0}><MultiSelectFilter options={["KS", "SBK", "RS", "Bez smlouvy"]} selected={contractFilter} onChange={value=>writeClientList("cc",value,setContractFilter)} allLabel="Všechny smluvní stavy" ariaLabel="Filtrovat smluvní stav" /></TableColumnFilter>}{columnState.isVisible("phone")&&<TableColumnFilter label="Telefon" active={Boolean(phoneFilter)}><input value={phoneFilter} onChange={(event) => writeClientText("cph",event.target.value,setPhoneFilter)} placeholder="Telefon…" aria-label="Filtrovat telefon" /></TableColumnFilter>}{columnState.isVisible("email")&&<TableColumnFilter label="E-mail" active={Boolean(emailFilter)}><input value={emailFilter} onChange={(event) => writeClientText("cem",event.target.value,setEmailFilter)} placeholder="E-mail…" aria-label="Filtrovat e-mail" /></TableColumnFilter>}<th /></tr></thead><tbody>{pageRows.map((client) => <tr key={client.id} onClick={() => {sessionStorage.setItem(`develocrm.clients.scroll:${filterKey}`,String(window.scrollY));setSelectedClientName(client.name);}}><td className="checkbox-cell"><button className={`table-checkbox ${selected.has(client.id) ? "checked" : ""}`} onClick={(event) => { event.stopPropagation(); toggle(client.id); }} aria-label={`Vybrat ${client.name}`}>{selected.has(client.id) && <Check size={13} />}</button></td><td className="column-primary"><span className="client-name-cell"><Avatar initials={client.initials} small /><span><strong>{client.name}</strong></span></span></td>{columnState.isVisible("type")&&<td><Badge tone="neutral">{client.kind}</Badge></td>}{columnState.isVisible("project")&&<td><ClientRelationColumn client={client} mode="project" openUnit={openUnit}/></td>}{columnState.isVisible("units")&&<td className="client-unit-column"><ClientRelationColumn client={client} mode="unit" openUnit={openUnit}/></td>}{columnState.isVisible("relation")&&<td><Badge>{client.lifecycleStatus==="archived"?"Archivovaný":client.state}</Badge></td>}{columnState.isVisible("contract")&&<td>{client.contractStatus}</td>}{columnState.isVisible("phone")&&<td>{client.phone}</td>}{columnState.isVisible("email")&&<td><a href={`mailto:${client.email}`} onClick={(event) => event.stopPropagation()}>{client.email}</a></td>}<td><ChevronRight size={17} /></td></tr>)}</tbody></table><div ref={clientSentinelRef} className="client-load-sentinel">{serverPage.loading?"Načítám další klienty…":serverPage.clients.length<serverPage.total?"Další klienti se načtou automaticky":""}</div></div>
      {!filtered.length && <div className="empty-filter-state"><Search size={22} /><strong>Žádný klient neodpovídá filtrům</strong><small>Změňte projekt, stav vztahu nebo hledaný výraz.</small></div>}
    </section>
  );
}

function ClientUnitChips({client,project,openUnit}:{client:(typeof clients)[number];project?:ProjectRecord;openUnit:(unit:UnitRecord)=>void}){const relations=client.unitRelations?.length?client.unitRelations:client.units.map(code=>{const unit=units.find(item=>item.id===code);return{unitId:unit?.backendId??code,code,projectId:unit?.projectBackendId??"",project:unit?.project??""};});const visible=relations.filter(relation=>!project||projectMatchesName(project,relation.project));return <span className="client-unit-chips">{visible.map(relation=>{const unit=units.find(item=>item.backendId===relation.unitId)||(units.find(item=>item.id===relation.code&&(!project||unitBelongsToProject(item,project))));return <button className="unit-link client-unit-chip" key={`${relation.projectId}-${relation.unitId}`} onClick={event=>{event.stopPropagation();if(unit)openUnit(unit);}}>{relation.code}</button>})}</span>}
function clientContractStatus(client:(typeof clients)[number],project?:ProjectRecord){const rank:Record<string,number>={RS:1,SBK:2,KS:3};const relevant=(client.unitRelations??[]).filter(relation=>relation.contractType&&(!project||projectMatchesName(project,relation.project))).sort((left,right)=>(rank[right.contractType??""]??0)-(rank[left.contractType??""]??0));const best=relevant[0];return best?.contractType?`${best.contractType}${best.contractStatus?` · ${contractStatusLabel(best.contractStatus)}`:""}`:project?"Bez smlouvy":client.contractStatus;}
function ClientRelationColumn({client,mode,openUnit}:{client:(typeof clients)[number];mode:"project"|"unit";openUnit:(unit:UnitRecord)=>void}){if(mode==="unit")return <ClientUnitChips client={client} openUnit={openUnit}/>;return <span className="client-relation-map">{client.projectNames.map(project=><span key={project}><small>{project}</small></span>)}</span>}

function ClientDetail({ client, onBack, openUnit,openProject, onEdit,onArchived }: { client: (typeof clients)[number]; onBack: () => void; openUnit: (unit: UnitRecord) => void;openProject:(project:ProjectRecord)=>void; onEdit?: () => void;onArchived?:()=>void }) {
  const history=client.interestHistory?.length?client.interestHistory:[{date:"—",project:client.projectNames[0]??"—",unit:client.units[0]??"—",type:"Bez evidované události",result:client.state}];
  const [tab,setTab]=useState<"overview"|"payments"|"documents">("overview");const [archiveImpact,setArchiveImpact]=useState<Awaited<ReturnType<typeof clientRepository.getArchiveImpact>>|null>(null);const [archiveReason,setArchiveReason]=useState("Archivace klienta z administrace");const [activityOpen,setActivityOpen]=useState(false);const [activityRows,setActivityRows]=useState(client.activityHistory??[]);
  const activityLabel=(type:string)=>({note:"Poznámka",call:"Telefonát",email:"E-mail",meeting:"Schůzka",other:"Jiná aktivita"} as Record<string,string>)[type]??"Aktivita";
  return <><div className="client-detail"><div className="unit-breadcrumb"><button onClick={onBack}><ArrowLeft size={16} /> Klienti a zájemci</button><ChevronRight size={14} /><strong>{client.name}</strong></div><div className="client-detail-hero card"><Avatar initials={client.initials} /><div><span className="eyebrow">{client.type.toUpperCase()}</span><h1>{client.name} <Badge>{client.state}</Badge></h1><p><Mail size={14} /> {client.email} <span>·</span> <UserRound size={14} /> {client.phone}</p></div><div className="project-detail-actions">{onEdit&&<button className="secondary-button" onClick={onEdit}><MoreHorizontal size={16} /> Upravit klienta</button>}{onArchived&&client.lifecycleStatus!=="archived"&&<button className="secondary-button danger-button" onClick={()=>void clientRepository.getArchiveImpact(client.id).then(setArchiveImpact)}><X size={16}/> Smazat klienta</button>}<button className="primary-button" onClick={()=>setActivityOpen(true)}><MessageSquare size={16} /> Přidat aktivitu</button></div></div><nav className="unit-tabs unit-detail-tabs client-detail-tabs" aria-label="Navigace klienta"><button className={tab==="overview"?"active":""} onClick={()=>setTab("overview")}><LayoutDashboard size={17}/> Přehled</button><button className={tab==="documents"?"active":""} onClick={()=>setTab("documents")}><FolderOpen size={17}/> Dokumenty</button></nav>{tab==="documents"?<ClientDocuments client={client}/>:<div className="client-detail-grid"><section className="card client-relations"><SectionTitle title="Projekty a jednotky" /><p className="section-description">Všechny vztahy klienta napříč společnou firemní databází.</p><div className="client-project-links">{client.projectNames.map(name=>{const project=projects.find(item=>projectMatchesName(item,name));return project?<button className="unit-link" key={name} onClick={()=>openProject(project)}><Building2 size={14}/>{project.name}</button>:null;})}</div>{client.units.map((unitCode, index) => { const unit = units.find((item) => item.id === unitCode) || units[0]; return <button key={unitCode} onClick={() => openUnit(unit)}><span className="unit-symbol"><Home size={18} /></span><span><strong>{unit.id} · {unit.layout}</strong><small>{unit.project} · {unit.building}</small></span><Badge>{index === 0 ? client.state : "Zájemce"}</Badge><ChevronRight size={17} /></button>; })}</section><aside className="card client-contact-panel"><SectionTitle title="Kontaktní údaje" /><dl><div><dt>E-mail</dt><dd>{client.email}</dd></div><div><dt>Telefon</dt><dd>{client.phone}</dd></div><div><dt>Typ osoby</dt><dd>{client.kind}</dd></div><div><dt>Smluvní stav</dt><dd>{client.contractStatus}</dd></div></dl></aside><section className="card client-history"><SectionTitle title="Historie zájmu" /><div className="unit-table-wrap"><table className="data-table"><thead><tr><th>Datum</th><th>Projekt / jednotka</th><th>Typ zájmu</th><th>Výsledek</th></tr></thead><tbody>{history.map((row,index)=>{const result=salesHistoryLabel(row.result);return <tr key={`${row.unit}-${row.date}-${index}`}><td>{row.date}</td><td><strong>{row.project} · {row.unit}</strong></td><td>{salesHistoryLabel(row.type)}</td><td><Badge tone={result.includes("Pokračuje")||result.includes("Aktivní")?"success":"neutral"}>{result}</Badge></td></tr>})}</tbody></table></div></section><section className="card client-history"><SectionTitle title="Aktivity klienta" /><div className="timeline-mini">{activityRows.map(item=><div key={item.id}><span className="timeline-icon comment"><MessageSquare size={16}/></span><span><strong>{activityLabel(item.type)}</strong><small>{item.note} · {item.author}</small></span><time>{formatPragueDateTime(item.occurredAt)}</time></div>)}{!activityRows.length&&<div className="empty-filter-state"><MessageSquare size={20}/><strong>Zatím bez ručně přidané aktivity</strong></div>}</div></section></div>}</div>{activityOpen&&<ClientActivityModal client={client} close={()=>setActivityOpen(false)} save={async value=>{const result=await clientRepository.addActivity({partyId:client.id,...value});const item={id:result.id,type:value.activityType,note:value.note,occurredAt:new Date().toISOString(),author:"Vy"};setActivityRows(current=>[item,...current]);setActivityOpen(false);}}/>}{archiveImpact&&<FormModal title="Smazat klienta" close={()=>setArchiveImpact(null)} saveLabel={archiveImpact.removalMode==="delete"?"Smazat klienta":"Archivovat klienta"} onSave={async()=>{await clientRepository.archiveParty(client.id,archiveReason);setArchiveImpact(null);onArchived?.();}}><div className="archive-impact-warning"><AlertTriangle size={20}/><div><strong>{archiveImpact.removalMode==="delete"?"Klient bude trvale smazán.":"Klient bude bezpečně archivován."}</strong><small>{archiveImpact.removalMode==="delete"?"Klient nemá obchodní historii. Jeho profil a kontaktní údaje budou odstraněny, audit operace zůstane zachován.":"Obchodní a auditní historie zůstane zachována. Z běžného seznamu klient zmizí."}</small></div></div><dl className="archive-impact-grid">{Object.entries({Jednotky:archiveImpact.units,Zájmy:archiveImpact.interests,"Obchodní případy":archiveImpact.salesCases,Smlouvy:archiveImpact.contracts,Platby:archiveImpact.payments,Úkoly:archiveImpact.tasks,Předání:archiveImpact.handovers,Dokumenty:archiveImpact.documents,"Klientské změny":archiveImpact.clientChanges??0}).map(([label,count])=><div key={label}><dt>{label}</dt><dd>{count}</dd></div>)}</dl><label><span>Důvod {archiveImpact.removalMode==="delete"?"smazání":"archivace"}</span><textarea rows={3} value={archiveReason} onChange={event=>setArchiveReason(event.target.value)}/></label></FormModal>}</>;
}

function ContractsAndDocumentsPage(props:{
  view:string;setView:(view:"contracts"|"documents"|"templates")=>void;
  openUnit:(unit:UnitRecord)=>void;openClient:(identity:string)=>void;openContract:(contract:(typeof contracts)[number])=>void;closeContract:()=>void;selectedContractId:string|null;notify:(message:string)=>void;onWorkflow?:(contract:(typeof contracts)[number])=>void;openDocument:(document:DocumentRecord)=>void;
  onContractVersion?:(contract:(typeof contracts)[number])=>void;onSignContract?:(contract:(typeof contracts)[number])=>void;
  selectedDocumentId:string|null;closeDocument:()=>void;reloadKey:number;onEditDocument?:(document:DocumentRecord)=>void;onNewVersion?:(document:DocumentRecord)=>void;
}){
  const active=props.view==="documents"?"documents":props.view==="templates"?"templates":"contracts";
  return <div className="module-stack"><nav className="workspace-subnav" aria-label="Smlouvy a dokumenty"><button className={active==="contracts"?"active":""} onClick={()=>props.setView("contracts")}><FileCheck2 size={17}/> Smlouvy</button><button className={active==="documents"?"active":""} onClick={()=>props.setView("documents")}><FolderOpen size={17}/> Ostatní dokumenty</button><button className={active==="templates"?"active":""} onClick={()=>props.setView("templates")}><FileText size={17}/> Šablony</button></nav>
    {active==="contracts"?<ContractsPage {...props}/>:active==="documents"?<DocumentsPage selectedDocumentId={props.selectedDocumentId} openDocument={props.openDocument} closeDocument={props.closeDocument} openUnit={props.openUnit} openClient={props.openClient} openContract={props.openContract} notify={props.notify} reloadKey={props.reloadKey} onEdit={props.onEditDocument} onNewVersion={props.onNewVersion}/>:<section className="card module-card"><div className="tab-card-header"><div><h2>Šablony dokumentů</h2><p>Word šablony zůstávají samostatnou vrstvou pro budoucí generování.</p></div></div><div className="empty-filter-state"><FileCheck2 size={24}/><strong>Správa šablon je připravená</strong><small>Šablony nejsou smlouvy ani fyzické dokumenty a nevytvářejí duplicitní data.</small></div></section>}
  </div>;
}

function ContractsPage({ openUnit,openClient,openContract,closeContract,selectedContractId,onWorkflow,onContractVersion,onSignContract,openDocument }: { openUnit:(unit:UnitRecord)=>void;openClient:(identity:string)=>void;openContract:(contract:(typeof contracts)[number])=>void;closeContract:()=>void;selectedContractId:string|null;onWorkflow?:(contract:(typeof contracts)[number])=>void;onContractVersion?:(contract:(typeof contracts)[number])=>void;onSignContract?:(contract:(typeof contracts)[number])=>void;openDocument:(document:DocumentRecord)=>void }) {
  const selectedContract=selectedContractId?contracts.find(contract=>contract.id===selectedContractId||contract.reference===selectedContractId):undefined;
  if(selectedContract)return <><ContractDetail contract={selectedContract} close={closeContract} openUnit={openUnit} openClient={openClient} onWorkflow={onWorkflow} onNewVersion={onContractVersion} onSignContract={onSignContract} openDocument={openDocument}/><PaymentContextTable title={`Platby smlouvy ${selectedContract.reference??selectedContract.type}`} description="Předpisy a skutečné úhrady navázané přímo na smlouvu." filters={{contractId:selectedContract.id}}/></>;
  return <ContractWorkspace openUnit={openUnit} openClient={openClient} openContract={openContract} onWorkflow={onWorkflow}/>;
}

const contractWorkflow=CONTRACT_STATUS_ORDER.map(contractStatusLabel);
function contractStep(contract:(typeof contracts)[number]){return contractStepIndex(contract.statusCode??contract.state);}
function displayedContractStatus(contract:(typeof contracts)[number]){return contractStatusLabel(contract.statusCode??contract.state);}
function contractVersionStatusLabel(value:string){return ({working:"Rozpracovaná",approved_for_signing:"Schválená",signed:"Podepsaná",superseded:"Nahrazená",cancelled:"Zrušená"} as Record<string,string>)[value]??value;}
function recommendedContractAction(contract:(typeof contracts)[number]){return deriveContractAction({status:contract.statusCode??contract.state,type:contract.type,missingData:contract.missingData,missingAttachments:contract.missingAttachments});}
function ContractWorkspace({openUnit,openClient,openContract,onWorkflow}:{openUnit:(unit:UnitRecord)=>void;openClient:(identity:string)=>void;openContract:(contract:(typeof contracts)[number])=>void;onWorkflow?:(contract:(typeof contracts)[number])=>void}){
  const router=useRouter();const pathname=usePathname();const searchParams=useSearchParams();
  const columnState=useTableColumns("contracts-table",contractTableColumns);
  const query=searchParams.get("cq")??"";const [quick,setQuick]=useState("action");const typeFilter=listParam(searchParams,"ctype");const stateFilter=listParam(searchParams,"cstate");const projectFilter=listParam(searchParams,"cproject");const [expanded,setExpanded]=useState<string|null>(null);
  const sort=searchParams.get("sort")??"updated";const direction=(searchParams.get("dir")==="asc"?"asc":"desc") as SortDirection;
  const filtered=contracts.filter(contract=>{const action=recommendedContractAction(contract);const search=`${contract.type} ${contract.unit} ${contract.client} ${contract.project} ${contract.reference??""}`.toLowerCase();const normalized=normalizeContractStatus(contract.statusCode??contract.state);const quickMatch=quick==="all"||quick==="mine"&&contract.owner==="Iva"||quick==="action"&&action.tone!=="neutral"||quick==="signing"&&normalized==="approved"||quick==="negotiation"&&normalized==="negotiation"||quick==="signed"&&normalized==="signed";return search.includes(query.toLowerCase())&&quickMatch&&(!typeFilter.length||typeFilter.includes(contract.type))&&(!stateFilter.length||stateFilter.includes(displayedContractStatus(contract)))&&(!projectFilter.length||projectFilter.includes(contract.project));});
  const rows=stableSort(filtered,contract=>sort==="state"?displayedContractStatus(contract):sort==="type"?contract.type:sort==="client"?contract.client:sort==="unit"?contract.unit:sort==="project"?contract.project:new Date(contract.updatedAt??contract.updated),direction,contract=>contract.id??`${contract.unit}-${contract.type}`);
  const setSort=(value:string,nextDirection:SortDirection)=>router.replace(updateSearch(pathname,searchParams.toString(),{sort:value,dir:nextDirection}),{scroll:false});
  const change=(patch:Record<string,string|string[]>)=>router.replace(updateSearch(pathname,searchParams.toString(),patch),{scroll:false});
  const contractGridTemplate=["minmax(210px,1.4fr)",columnState.isVisible("client")&&"minmax(150px,1fr)",columnState.isVisible("unit")&&"100px",columnState.isVisible("project")&&"minmax(150px,1fr)",columnState.isVisible("type")&&"90px",columnState.isVisible("workflow")&&"minmax(280px,1.8fr)",columnState.isVisible("status")&&"140px",columnState.isVisible("updated")&&"150px",columnState.isVisible("owner")&&"150px","38px"].filter(Boolean).join(" ");
  return <div className="module-stack contract-workspace">
    <div className="contract-quick-stats"><button className={quick==="action"?"active":""} onClick={()=>setQuick("action")}><AlertTriangle size={17}/><span><strong>{contracts.filter(item=>recommendedContractAction(item).tone!=="neutral").length}</strong><small>Vyžadují akci</small></span></button><button className={quick==="signing"?"active":""} onClick={()=>setQuick("signing")}><FileCheck2 size={17}/><span><strong>{contracts.filter(item=>normalizeContractStatus(item.statusCode??item.state)==="approved").length}</strong><small>Schválené</small></span></button><button className={quick==="negotiation"?"active":""} onClick={()=>setQuick("negotiation")}><MessageSquare size={17}/><span><strong>{contracts.filter(item=>normalizeContractStatus(item.statusCode??item.state)==="negotiation").length}</strong><small>Vyjednávání</small></span></button><button className={quick==="signed"?"active":""} onClick={()=>setQuick("signed")}><CheckCircle2 size={17}/><span><strong>{contracts.filter(item=>normalizeContractStatus(item.statusCode??item.state)==="signed").length}</strong><small>Podepsané</small></span></button><button className={quick==="all"?"active":""} onClick={()=>setQuick("all")}><FileText size={17}/><span><strong>{contracts.length}</strong><small>Všechny</small></span></button></div>
    <section className="card module-card">
      <div className="module-toolbar contract-filter-bar"><div className="inline-search"><Search size={17}/><input value={query} onChange={event=>change({cq:event.target.value})} placeholder="Smlouva, klient, jednotka…"/></div><span className="result-count">{rows.length} smluv</span><TableColumnMenu columns={contractTableColumns} state={columnState}/></div>
      <div className="contract-table-head" style={{gridTemplateColumns:contractGridTemplate}}>
        <ListColumnFilter label="Smlouva a kontext" active={typeFilter.length>0||projectFilter.length>0} sortDirection={sort==="type"||sort==="client"||sort==="unit"||sort==="project"?direction:undefined} onSort={next=>setSort("type",next)}><span className="column-filter-subtitle">Typ smlouvy</span><MultiSelectFilter options={Array.from(new Set(contracts.map(item=>item.type)))} selected={typeFilter} onChange={values=>change({ctype:values})} allLabel="Všechny typy" ariaLabel="Filtrovat typ smlouvy"/><span className="column-filter-subtitle">Projekt</span><MultiSelectFilter options={Array.from(new Set(contracts.map(item=>item.project)))} selected={projectFilter} onChange={values=>change({cproject:values})} allLabel="Všechny projekty" ariaLabel="Filtrovat projekt smlouvy"/></ListColumnFilter>
        {columnState.isVisible("client")&&<ListColumnFilter label="Klient" sortDirection={sort==="client"?direction:undefined} onSort={next=>setSort("client",next)}/>} {columnState.isVisible("unit")&&<ListColumnFilter label="Jednotka" sortDirection={sort==="unit"?direction:undefined} onSort={next=>setSort("unit",next)}/>} {columnState.isVisible("project")&&<ListColumnFilter label="Projekt" sortDirection={sort==="project"?direction:undefined} onSort={next=>setSort("project",next)}/>} {columnState.isVisible("type")&&<ListColumnFilter label="Typ"/>} {columnState.isVisible("workflow")&&<ListColumnFilter label="Průběh"/>}
        {columnState.isVisible("status")&&<ListColumnFilter label="Aktuální stav" active={stateFilter.length>0} sortDirection={sort==="state"?direction:undefined} onSort={next=>setSort("state",next)}><MultiSelectFilter options={Array.from(new Set(contracts.map(displayedContractStatus)))} selected={stateFilter} onChange={values=>change({cstate:values})} allLabel="Všechny stavy" ariaLabel="Filtrovat stav smlouvy"/></ListColumnFilter>}
        {columnState.isVisible("updated")&&<ListColumnFilter label="Poslední změna" sortType="date" sortDirection={sort==="updated"?direction:undefined} onSort={next=>setSort("updated",next)}/>} {columnState.isVisible("owner")&&<ListColumnFilter label="Odpovědná osoba"/>}<span/>
      </div>
      <div className="contract-hybrid-list">{rows.map(contract=>{const id=contract.id??`${contract.unit}-${contract.type}`;const step=contractStep(contract);const isExpanded=expanded===id;return <article key={id} className={isExpanded?"expanded":""}>
        <div className="contract-hybrid-row" style={{gridTemplateColumns:contractGridTemplate}} role="button" tabIndex={0} onClick={()=>openContract(contract)} onKeyDown={event=>{if(event.key==="Enter")openContract(contract);}}>
          <span className="contract-identity"><i>{contract.type}</i><span><strong>{contract.title??`${contract.type} · ${contract.unit}`}</strong><small>{contract.reference??"Interní smluvní evidence"}</small></span></span>
          {columnState.isVisible("client")&&<span>{contract.client}</span>}{columnState.isVisible("unit")&&<span>{contract.unit}</span>}{columnState.isVisible("project")&&<span>{contract.project}</span>}{columnState.isVisible("type")&&<span><Badge tone="blue">{contract.type}</Badge></span>}
          {columnState.isVisible("workflow")&&<button className="contract-mini-flow" onClick={event=>{event.stopPropagation();setExpanded(isExpanded?null:id);}} aria-label={`Zobrazit průběh ${contract.type} ${contract.unit}`}>{contractWorkflow.map((stage,index)=><span key={stage} className={index<step?"done":index===step?"current":""}><i>{index<step?<Check size={10}/>:index+1}</i><small>{stage}</small></span>)}</button>}
          {columnState.isVisible("status")&&<span><Badge tone={statusClass(displayedContractStatus(contract))}>{displayedContractStatus(contract)}</Badge></span>}
          {columnState.isVisible("updated")&&<time className="row-updated">{contract.updatedAt?formatPragueDateTime(contract.updatedAt):contract.updated}</time>}{columnState.isVisible("owner")&&<span>{contract.owner}</span>}
          <details className="row-overflow" onClick={event=>event.stopPropagation()}><summary aria-label="Další akce"><MoreHorizontal size={18}/></summary><div><button onClick={()=>openClient(contract.client)}>Otevřít klienta</button><button onClick={()=>openUnit(units.find(unit=>unit.id===contract.unit)??units[0])}>Otevřít jednotku</button><button onClick={()=>openContract(contract)}>Detail smlouvy</button></div></details>
        </div>
        {isExpanded&&<div className="contract-expanded-flow"><div><strong>{contractWorkflow[step]}</strong><small>{contract.updatedAt?formatPragueDateTime(contract.updatedAt):contract.updated} · {contract.owner}</small></div><button className="secondary-button compact" onClick={()=>openContract(contract)}>Celý detail</button>{onWorkflow&&availableContractTransitions(contract.statusCode??contract.state).length>0&&<button className="primary-button compact" onClick={()=>onWorkflow(contract)}>Změnit stav</button>}</div>}
      </article>;})}</div>
      {!rows.length&&<div className="empty-filter-state"><Search size={21}/><strong>Žádná smlouva neodpovídá filtrům</strong><small>Změňte rychlý pohled nebo některý z filtrů.</small></div>}
    </section>
  </div>;
}

const contractWorkflowSemantics = "Samostatný workflow dokumentu, nikoli obchodní stav jednotky.";
function ContractDetail({contract,close,openUnit,openClient,onWorkflow,onNewVersion,onSignContract,openDocument}:{contract:(typeof contracts)[number];close:()=>void;openUnit:(unit:UnitRecord)=>void;openClient:(identity:string)=>void;onWorkflow?:(contract:(typeof contracts)[number])=>void;onNewVersion?:(contract:(typeof contracts)[number])=>void;onSignContract?:(contract:(typeof contracts)[number])=>void;openDocument:(document:DocumentRecord)=>void}){
  void contractWorkflowSemantics;
  const [tab,setTab]=useState<"overview"|"history"|"versions"|"documents"|"notes">("overview");const [documents,setDocuments]=useState<DocumentRecord[]>([]);const [loading,setLoading]=useState(false);const [selectedWorkflowStatus,setSelectedWorkflowStatus]=useState(normalizeContractStatus(contract.statusCode??contract.state));
  useEffect(()=>{if(tab!=="documents")return;const controller=new AbortController();Promise.resolve().then(()=>setLoading(true));documentRepository.listContract(contract.id??contract.reference??`${contract.unit}-${contract.type}`,controller.signal).then(result=>setDocuments(result.documents)).finally(()=>setLoading(false));return()=>controller.abort();},[tab,contract]);
  const step=contractStep(contract);const history=contract.history??[];const isAssignment=["assignment_rs","assignment_sbk"].includes(contract.typeCode??"");const assignors=(contract.parties??[]).filter(party=>party.role==="assignor");const assignees=(contract.parties??[]).filter(party=>party.role==="assignee");const currentParties=isAssignment?assignees:(contract.parties??[]).filter(party=>party.isCurrent!==false&&(party.role==="buyer"||party.role==="co_buyer"));const historicalParties=isAssignment?assignors:(contract.parties??[]).filter(party=>party.isCurrent===false&&(party.role==="buyer"||party.role==="co_buyer"));const selectedEvents=history.filter(event=>event.toStatus===selectedWorkflowStatus||event.fromStatus===selectedWorkflowStatus);const selectedStarted=history.find(event=>event.toStatus===selectedWorkflowStatus);const selectedCompleted=history.find(event=>event.fromStatus===selectedWorkflowStatus);const unit=units.find(item=>item.id===contract.unit)??units[0];const versions=contract.versions?.length?contract.versions:[{id:`${contract.id}-v1`,number:1,name:`${contract.type} ${contract.unit} · v1`,status:contract.state,basedOnVersionId:null,source:"CRM",createdAt:contract.updatedAt??contract.updated,signedAt:normalizeContractStatus(contract.statusCode??contract.state)==="signed"?(contract.updatedAt??contract.updated):null}];
  const canMarkSigned=["approved","signing"].includes(normalizeContractStatus(contract.statusCode??contract.state))&&Boolean(versions[0]);
  return <div className="contract-detail"><div className="unit-breadcrumb"><button onClick={close}><ArrowLeft size={16}/> Smlouvy</button><ChevronRight size={14}/><strong>{contract.reference??`${contract.type}-${contract.unit}`}</strong></div><section className="card contract-detail-hero"><span className="contract-type large">{contract.type}</span><div><span className="eyebrow">{contract.project} · {contract.unit}</span><h1>{contract.title??`${contract.type} · ${contract.client}`}</h1><p>{contract.reference??"Interní smluvní evidence"} · vlastník {contract.owner}</p></div><Badge tone={statusClass(displayedContractStatus(contract))}>{displayedContractStatus(contract)}</Badge><div className="project-detail-actions">{onSignContract&&canMarkSigned&&<button className="primary-button" onClick={()=>onSignContract(contract)}><FileCheck2 size={16}/> Označit jako podepsané</button>}{onWorkflow&&<button className={canMarkSigned?"secondary-button":"primary-button"} onClick={()=>onWorkflow(contract)}><SlidersHorizontal size={16}/> Změnit stav</button>}<details className="detail-overflow"><summary className="secondary-button"><MoreHorizontal size={16}/> Další</summary><div><button onClick={()=>openClient(contract.client)}>Otevřít klienta</button><button onClick={()=>openUnit(unit)}>Otevřít jednotku</button></div></details></div></section>
    <nav className="unit-tabs unit-detail-tabs contract-detail-tabs">{([["overview","Přehled",LayoutDashboard],["history","Historie",History],["versions","Verze",FileText],["documents","Dokumenty",FolderOpen],["notes","Poznámky",MessageSquare]] as const).map(([id,label,Icon])=><button key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}><Icon size={17}/>{label}{id==="versions"&&<span>{versions.length}</span>}{id==="documents"&&documents.length>0&&<span>{documents.length}</span>}</button>)}</nav>
    {tab==="overview"&&<div className="contract-detail-grid"><section className="card contract-workflow-card"><div className="tab-card-header"><div><h2>Průběh smlouvy</h2><p>Kliknutím na krok zobrazíte jeho skutečnou historii.</p></div></div><div className="contract-detail-flow">{contractWorkflow.map((stage,index)=>{const code=CONTRACT_STATUS_ORDER[index];return <button type="button" key={stage} className={`${index<step?"done":index===step?"current":""} ${selectedWorkflowStatus===code?"selected":""}`} onClick={()=>setSelectedWorkflowStatus(code)}><i>{index<step?<Check size={12}/>:index+1}</i><strong>{stage}</strong><small>{index<step?"Dokončeno":index===step?"Aktuální krok":"Čeká"}</small></button>;})}</div><div className="workflow-step-detail"><strong>{contractStatusLabel(selectedWorkflowStatus)}</strong><dl><div><dt>Zahájeno</dt><dd>{selectedStarted?formatPragueDateTime(selectedStarted.occurredAt):"Bez záznamu"}</dd></div><div><dt>Dokončeno</dt><dd>{selectedCompleted?formatPragueDateTime(selectedCompleted.occurredAt):"—"}</dd></div><div><dt>Změnil</dt><dd>{selectedStarted?.actor??"—"}</dd></div></dl>{selectedStarted&&<p>{selectedStarted.note}</p>}{selectedEvents.length>1&&<small>{selectedEvents.length} události tohoto kroku v historii</small>}</div></section><aside className="card contract-context-card"><SectionTitle title="Vazby smlouvy"/><button onClick={()=>openUnit(unit)}><Home size={17}/><span><small>Jednotka</small><strong>{contract.unit} · {unit.layout}</strong></span><ChevronRight size={16}/></button>{isAssignment&&<div className="contract-assignment-parent"><GitBranch size={17}/><span><small>Navazuje na smlouvu</small><strong>{contract.parentReference??"Původní RS / SBK"}</strong>{contract.assignmentEffectiveAt&&<em>účinnost {formatPragueDate(contract.assignmentEffectiveAt)}</em>}</span></div>}<div className="contract-party-summary"><UserRound size={17}/><span><small>{isAssignment?"Nové smluvní strany":"Aktuální smluvní strany"}</small><strong>{currentParties.map(party=>party.name).join(" · ")||"Bez aktuálního kupujícího"}</strong></span></div>{historicalParties.length>0&&<div className="contract-party-history"><History size={17}/><span><small>{isAssignment?"Postupitelé":"Historické smluvní strany"}</small>{historicalParties.map(party=><button key={party.id} onClick={()=>openClient(party.name)}><strong>{party.name}</strong><em>{isAssignment?"původní smluvní strana":`původní kupující${party.effectiveTo?` · postoupeno ${formatPragueDate(party.effectiveTo)}`:""}`}</em>{party.assignmentReason&&<small>{party.assignmentReason}</small>}</button>)}</span></div>}<div><Building2 size={17}/><span><small>Projekt</small><strong>{contract.project}</strong></span></div></aside></div>}
    {tab==="history"&&<ContractEventHistory history={history} versions={versions} historicalParties={historicalParties} emptyUpdated={contract.updatedAt??contract.updated} emptyOwner={contract.owner}/>}
    {tab==="versions"&&<section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Logické verze smlouvy</h2><p>Podepsaná verze je neměnná; nová verze navazuje na předchozí.</p></div>{onNewVersion&&normalizeContractStatus(contract.statusCode??contract.state)!=="signed"&&<button className="primary-button" onClick={()=>onNewVersion(contract)}><Plus size={15}/> Nová verze</button>}</div><div className="document-version-list">{versions.map(version=><article key={version.id}><span className="version-badge">v{version.number}</span><span><strong>{version.name}</strong><small>{version.source} · vytvořeno {formatPragueDateTime(version.createdAt)}{version.signedAt?` · podepsáno ${formatPragueDateTime(version.signedAt)}`:""}</small></span><Badge tone={statusClass(contractVersionStatusLabel(version.status))}>{contractVersionStatusLabel(version.status)}</Badge></article>)}</div></section>}
    {tab==="documents"&&<section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Související dokumenty</h2><p>Dokumenty jsou propojené konkrétní vazbou na tuto smlouvu.</p></div></div><DocumentList documents={documents} loading={loading} notify={()=>{}} openDocument={openDocument}/></section>}
    {tab==="notes"&&<section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Interní poznámky</h2><p>Poznámky nejsou fyzickou verzí smlouvy.</p></div><button className="secondary-button"><Plus size={15}/> Přidat poznámku</button></div><div className="empty-filter-state"><MessageSquare size={21}/><strong>Zatím bez poznámek</strong><small>Nová poznámka se zobrazí v historii smlouvy.</small></div></section>}
  </div>;
}

function ContractEventHistory({history,versions,historicalParties,emptyUpdated,emptyOwner}:{history:NonNullable<(typeof contracts)[number]["history"]>;versions:NonNullable<(typeof contracts)[number]["versions"]>;historicalParties:NonNullable<(typeof contracts)[number]["parties"]>;emptyUpdated:string;emptyOwner:string}){
  const events=[...history.map(event=>({id:event.id,at:event.occurredAt,title:event.fromStatus?`${contractStatusLabel(event.fromStatus)} → ${contractStatusLabel(event.toStatus)}`:`Vznikl stav ${contractStatusLabel(event.toStatus)}`,detail:event.note||"Bez poznámky",meta:`${event.actor} · ${event.source==="manual"?"ruční změna":event.source}`})),...versions.flatMap(version=>[{id:`version-${version.id}`,at:version.createdAt,title:`Vytvořena logická verze v${String(version.number).padStart(2,"0")}`,detail:version.name,meta:version.source},...(version.signedAt?[{id:`signature-${version.id}`,at:version.signedAt,title:`Podepsaná verze v${String(version.number).padStart(2,"0")}`,detail:version.name,meta:"evidence podpisu"}]:[])]),...historicalParties.filter(party=>party.effectiveTo).map(party=>({id:`assignment-${party.id}`,at:party.effectiveTo as string,title:"Postoupení smlouvy",detail:`Původní kupující: ${party.name}`,meta:party.assignmentReason||"Změna smluvní strany"}))].sort((a,b)=>new Date(b.at).getTime()-new Date(a.at).getTime());
  return <section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Historie smlouvy</h2><p>Stavy, logické verze, podpisy a relevantní auditní události v jednom přehledu.</p></div></div><div className="document-timeline">{events.length?events.map(event=><article key={event.id}><span><History size={15}/></span><div><strong>{event.title}</strong><p>{event.detail}</p><small>{formatPragueDateTime(event.at)} · {event.meta}</small></div></article>):<article><span><History size={15}/></span><div><strong>Dosud bez historické události</strong><p>První změna vytvoří auditovatelný historický záznam.</p><small>{emptyUpdated} · {emptyOwner}</small></div></article>}</div></section>;
}

function PaymentsPage({openUnit,notify,canRecord,canReverse,canImport}:{openUnit:(unit:UnitRecord)=>void;notify:(message:string)=>void;canRecord:boolean;canReverse:boolean;canImport:boolean}){
  const router=useRouter();const pathname=usePathname();const searchParams=useSearchParams();const now=useClock();const [rows,setRows]=useState<PaymentRecord[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [source,setSource]=useState("");const [selected,setSelected]=useState<PaymentRecord|null>(null);const [importRows,setImportRows]=useState<ImportPreviewRow[]|null>(null);
  const columnState=useTableColumns("payments-table",paymentTableColumns);
  const query=searchParams.get("pq")??"";const status=searchParams.get("ps")??"";const sort=searchParams.get("sort")??"dueAt";const direction=(searchParams.get("dir")==="desc"?"desc":"asc") as SortDirection;
  const reload=()=>{setLoading(true);setError("");paymentRepository.list({query,sort,direction}).then(result=>{setRows(result.payments);setSource(result.source);}).catch(err=>setError(err instanceof Error?err.message:"Platby nelze načíst")).finally(()=>setLoading(false));};
  useEffect(()=>{const controller=new AbortController();paymentRepository.list({query,sort,direction},controller.signal).then(result=>{setRows(result.payments);setSource(result.source);setError("");}).catch(err=>{if((err as Error).name!=="AbortError")setError(err instanceof Error?err.message:"Platby nelze načíst");}).finally(()=>setLoading(false));return()=>controller.abort();},[query,sort,direction]);const change=(patch:Record<string,string>)=>router.replace(updateSearch(pathname,searchParams.toString(),patch),{scroll:false});
  const visible=rows.filter(row=>!status||row.status===status);const paid=rows.reduce((sum,row)=>sum+row.paid,0);const soon=rows.filter(row=>row.status==="pending"&&new Date(row.dueAt).getTime()-(now?.getTime()??0)<14*86400000).reduce((sum,row)=>sum+(row.amount-row.paid),0);const overdue=rows.filter(row=>row.status==="overdue").reduce((sum,row)=>sum+(row.amount-row.paid),0);
  return <div className="module-stack"><div className="metric-row payments-metrics"><div className="metric-card wide"><span className="metric-icon green"><Banknote size={20}/></span><span><small>Uhrazeno</small><strong>{formatMoney(paid)}</strong><em>skutečné nereverzované úhrady</em></span></div><div className="metric-card wide"><span className="metric-icon sand"><Clock3 size={20}/></span><span><small>Splatné do 14 dní</small><strong>{formatMoney(soon)}</strong><em>odvozeno z předpisů</em></span></div><div className="metric-card wide danger-metric"><span className="metric-icon red"><AlertTriangle size={20}/></span><span><small>Po splatnosti</small><strong>{formatMoney(overdue)}</strong><em>{rows.filter(row=>row.status==="overdue").length} předpisů</em></span></div></div>
    <section className="card module-card"><div className="table-action-bar"><span><strong>{visible.length}</strong> plateb · {source==="preview-adapter"?"preview data přetrvají v tomto prohlížeči":"produkční databáze"}</span><span className="list-toolbar-actions"><TableColumnMenu columns={paymentTableColumns} state={columnState}/>{canImport&&<label className="secondary-button compact file-button"><Upload size={16}/> Import CSV · nejdřív náhled<input type="file" accept=".csv,text/csv" onChange={async event=>{const file=event.target.files?.[0];if(!file)return;try{setImportRows(await paymentRepository.previewCsv(await file.text()));}catch(err){notify(err instanceof Error?err.message:"Výpis nelze načíst");}event.target.value="";}}/></label>}</span></div>
      <div className="unit-table-wrap"><table className="data-table payment-table filter-table configurable-table"><thead><tr><TableColumnFilter className="column-primary" label="Jednotka / klient" active={Boolean(query)} sortDirection={sort==="unit"?direction:undefined} onSort={next=>change({sort:"unit",dir:next})}><input value={query} onChange={event=>change({pq:event.target.value})} placeholder="Jednotka, klient…" aria-label="Filtrovat platbu"/></TableColumnFilter>{columnState.isVisible("type")&&<TableColumnFilter label="Splátka" sortDirection={sort==="label"?direction:undefined} onSort={next=>change({sort:"label",dir:next})}/>} {columnState.isVisible("due")&&<TableColumnFilter label="Splatnost" sortType="date" sortDirection={sort==="dueAt"?direction:undefined} onSort={next=>change({sort:"dueAt",dir:next})}/>} {columnState.isVisible("amount")&&<TableColumnFilter label="Předpis" sortType="number" sortDirection={sort==="amount"?direction:undefined} onSort={next=>change({sort:"amount",dir:next})}/>} {columnState.isVisible("paid")&&<TableColumnFilter label="Uhrazeno" sortType="number" sortDirection={sort==="paid"?direction:undefined} onSort={next=>change({sort:"paid",dir:next})}/>} {columnState.isVisible("status")&&<TableColumnFilter label="Stav" active={Boolean(status)} sortDirection={sort==="status"?direction:undefined} onSort={next=>change({sort:"status",dir:next})}><MultiSelectFilter options={Object.values(paymentStatusLabel)} selected={status?[paymentStatusLabel[status as PaymentStatus]]:[]} onChange={values=>change({ps:Object.entries(paymentStatusLabel).find(([,label])=>label===values.at(-1))?.[0]??""})} allLabel="Všechny stavy" ariaLabel="Filtrovat stav platby"/></TableColumnFilter>}{columnState.isVisible("project")&&<th>Projekt</th>}<th/></tr></thead><tbody>{visible.map(row=><PaymentTableRow key={row.id} row={row} onClick={()=>setSelected(row)} columns={columnState}/>)}</tbody></table></div>
      {loading&&<div className="empty-filter-state"><Clock3 size={21}/><strong>Načítám platby…</strong></div>}{error&&<div className="empty-filter-state"><AlertTriangle size={21}/><strong>Platby nelze načíst</strong><small>{error}</small><button className="secondary-button compact" onClick={reload}>Zkusit znovu</button></div>}{!loading&&!error&&!visible.length&&<div className="empty-filter-state"><Banknote size={21}/><strong>Žádné platby neodpovídají filtrům</strong><small>Změňte filtr v hlavičce tabulky.</small></div>}</section>
    {selected&&<PaymentDetailModal payment={selected} close={()=>setSelected(null)} openUnit={()=>openUnit(units.find(unit=>unit.id===selected.unit)??units[0])} canRecord={canRecord} canReverse={canReverse} saved={()=>{setSelected(null);reload();notify("Platební historie byla aktualizována");}}/>}
    {importRows&&<BankImportModal rows={importRows} close={()=>setImportRows(null)} confirm={async()=>{const count=await paymentRepository.confirmImport(importRows);setImportRows(null);reload();notify(`Potvrzeno a spárováno ${count} transakcí`);}}/>}
  </div>;
}

function PaymentTableRow({row,onClick,columns}:{row:PaymentRecord;onClick:()=>void;columns:ReturnType<typeof useTableColumns>}){const percent=Math.min(100,Math.round(row.paid/row.amount*100));return <tr onClick={onClick} tabIndex={0} onKeyDown={event=>event.key==="Enter"&&onClick()}><td className="column-primary"><strong>{row.unit} · {row.client}</strong></td>{columns.isVisible("type")&&<td>{row.label}{row.type==="reservation_fee"&&row.status!=="paid"&&<small>Čeká na rezervační poplatek</small>}</td>}{columns.isVisible("due")&&<td>{formatPragueDate(row.dueAt)}</td>}{columns.isVisible("amount")&&<td><strong>{formatMoney(row.amount)}</strong></td>}{columns.isVisible("paid")&&<td><strong>{formatMoney(row.paid)}</strong><span className="payment-progress"><i style={{width:`${percent}%`}}/></span></td>}{columns.isVisible("status")&&<td><Badge tone={row.status==="overdue"?"danger":row.status==="paid"?"success":row.status==="overpaid"?"warning":"neutral"}>{paymentStatusLabel[row.status]}</Badge></td>}{columns.isVisible("project")&&<td>{row.project}</td>}<td><ChevronRight size={18}/></td></tr>}

function PaymentDetailModal({payment,close,openUnit,canRecord,canReverse,saved}:{payment:PaymentRecord;close:()=>void;openUnit:()=>void;canRecord:boolean;canReverse:boolean;saved:()=>void}){const [recording,setRecording]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState("");return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label="Zavřít detail platby"/><div className="modal payment-detail-modal"><div className="modal-head"><div><span className="eyebrow">{payment.project} · {payment.unit}</span><h2>{payment.label}</h2><p>{payment.contractReference??"Bez smlouvy"} · VS {payment.variableSymbol??"—"}</p></div><button className="icon-button" onClick={close}><X size={19}/></button></div><div className="payment-detail-summary"><span><small>PŘEDPIS</small><strong>{formatMoney(payment.amount)}</strong></span><span><small>UHRAZENO</small><strong>{formatMoney(payment.paid)}</strong></span><span><small>ZBÝVÁ</small><strong>{formatMoney(Math.max(0,payment.amount-payment.paid))}</strong></span><Badge tone={payment.status==="overdue"?"danger":payment.status==="paid"?"success":"neutral"}>{paymentStatusLabel[payment.status]}</Badge></div><div className="context-links"><button onClick={openUnit}><Home size={16}/><span><small>Jednotka</small><strong>{payment.unit}</strong></span><ChevronRight size={15}/></button><div><UserRound size={16}/><span><small>Klient</small><strong>{payment.client}</strong></span></div><div><FileText size={16}/><span><small>Smlouva / obchodní proces</small><strong>{payment.contractReference??payment.salesCaseId}</strong></span></div></div>{recording&&<PaymentRecordForm payment={payment} busy={busy} error={error} cancel={()=>setRecording(false)} save={async value=>{setBusy(true);setError("");try{await paymentRepository.record(payment.id,value);saved();}catch(err){setError(err instanceof Error?err.message:"Úhradu nelze uložit");setBusy(false);}}}/>}<section className="payment-history"><div className="tab-card-header"><div><h3>Historie úhrad</h3><p>Reverzace historii nemaže.</p></div>{canRecord&&!recording&&<button className="primary-button compact" onClick={()=>setRecording(true)}><Plus size={15}/> Zaznamenat úhradu</button>}</div>{payment.transactions.length?payment.transactions.map(tx=><article key={tx.id} className={tx.reversedAt?"reversed":""}><span><Banknote size={17}/></span><span><strong>{formatMoney(tx.amount)}</strong><small>{formatPragueDateTime(tx.paidAt)} · {tx.counterpartyAccount??"ruční úhrada"}{tx.reversedAt?` · REVERZOVÁNO: ${tx.reversalReason}`:""}</small></span>{canReverse&&!tx.reversedAt&&<button className="text-button" disabled={busy} onClick={async()=>{const reason=window.prompt("Důvod reverzace");if(!reason)return;setBusy(true);try{await paymentRepository.reverse(tx.id,reason);saved();}catch(err){setError(err instanceof Error?err.message:"Reverzaci nelze provést");setBusy(false);}}}>Reverzovat</button>}</article>):<div className="empty-filter-state"><Banknote size={20}/><strong>Zatím bez úhrady</strong></div>}</section>{error&&!recording&&<p className="form-error">{error}</p>}</div></div>}

function PaymentRecordForm({payment,busy,error,cancel,save}:{payment:PaymentRecord;busy:boolean;error:string;cancel:()=>void;save:(value:{amount:number;paidAt:string;variableSymbol?:string;counterpartyAccount?:string;bankTransactionId?:string;note?:string})=>void}){const [amount,setAmount]=useState(String(Math.max(0,payment.amount-payment.paid)));const [paidAt,setPaidAt]=useState(new Date().toISOString().slice(0,16));const [variableSymbol,setVariableSymbol]=useState(payment.variableSymbol??"");const [account,setAccount]=useState("");const [note,setNote]=useState("");return <form className="inline-payment-form" onSubmit={event=>{event.preventDefault();save({amount:Number(amount),paidAt:new Date(paidAt).toISOString(),variableSymbol:variableSymbol.trim()||undefined,counterpartyAccount:account.trim()||undefined,note:note.trim()||undefined});}}><label><span>Zaplacená částka</span><input required min="0.01" step="0.01" type="number" value={amount} onChange={event=>setAmount(event.target.value)}/></label><label><span>Datum úhrady</span><input required type="datetime-local" value={paidAt} onChange={event=>setPaidAt(event.target.value)}/></label><label><span>Variabilní symbol</span><input inputMode="numeric" value={variableSymbol} onChange={event=>setVariableSymbol(event.target.value)}/></label><label><span>Účet protistrany</span><input value={account} onChange={event=>setAccount(event.target.value)}/></label><label className="full"><span>Poznámka</span><input value={note} onChange={event=>setNote(event.target.value)}/></label>{error&&<p className="form-error full">{error}</p>}<div className="modal-actions full"><button type="button" className="secondary-button" onClick={cancel}>Zrušit</button><button className="primary-button" disabled={busy}>{busy?"Ukládám…":"Uložit úhradu"}</button></div></form>}

function BankImportModal({rows,close,confirm}:{rows:ImportPreviewRow[];close:()=>void;confirm:()=>Promise<void>}){const [busy,setBusy]=useState(false);const ready=rows.filter(row=>!row.duplicate&&row.proposedObligationId).length;return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label="Zavřít náhled importu"/><div className="modal bank-import-modal"><div className="modal-head"><div><h2>Náhled bankovního výpisu</h2><p>Žádná transakce nebude spárována bez vašeho potvrzení.</p></div><button className="icon-button" onClick={close}><X size={19}/></button></div><div className="unit-table-wrap"><table className="data-table"><thead><tr><th>Řádek</th><th>Datum</th><th>Částka</th><th>VS / účet</th><th>Návrh spárování</th><th>Kontrola</th></tr></thead><tbody>{rows.map(row=><tr key={row.row}><td>{row.row}</td><td>{formatPragueDate(row.paidAt)}</td><td><strong>{formatMoney(row.amount)}</strong></td><td>{row.variableSymbol||"—"}<small>{row.counterpartyAccount}</small></td><td>{row.proposedLabel??"Bez návrhu"}<small>{row.confidence?`${row.confidence} % shoda`:""}</small></td><td><Badge tone={row.duplicate?"danger":row.proposedObligationId?"success":"warning"}>{row.duplicate?"Duplicita":row.proposedObligationId?"Připraveno":"Vyžaduje ruční přiřazení"}</Badge></td></tr>)}</tbody></table></div><div className="modal-actions"><button className="secondary-button" onClick={close}>Zrušit</button><button className="primary-button" disabled={!ready||busy} onClick={async()=>{setBusy(true);await confirm();}}>{busy?"Potvrzuji…":`Potvrdit ${ready} transakcí`}</button></div></div></div>}

function HandoversPage({ openUnit, notify,reloadKey }: { openUnit: (unit: UnitRecord) => void; notify: (message: string) => void;reloadKey:number }) {
  const now=useClock();const router=useRouter();const pathname=usePathname();const searchParams=useSearchParams();const [rows,setRows]=useState<HandoverRecord[]>([]);const [loading,setLoading]=useState(true);const [loadError,setLoadError]=useState(false);const [weekOffset,setWeekOffset]=useState(Number(searchParams.get("week")??0));const projectFilters=listParam(searchParams,"project");const statusFilters=listParam(searchParams,"status");const ownerFilters=listParam(searchParams,"owner");const warningFilters=listParam(searchParams,"warning");const query=searchParams.get("query")??"";const readinessFrom=searchParams.get("readyFrom")??"";const readinessTo=searchParams.get("readyTo")??"";const dateFrom=searchParams.get("dateFrom")??"";const dateTo=searchParams.get("dateTo")??"";const sort=searchParams.get("sort")??"date";const direction=(searchParams.get("dir")==="desc"?"desc":"asc") as SortDirection;
  const columnState=useTableColumns("handovers-table",handoverTableColumns);
  const statusLabel=(value:string)=>({planned:"Naplánováno",ready:"Připraveno",in_progress:"Probíhá",completed:"Dokončeno",cancelled:"Zrušeno"} as Record<string,string>)[value]??value;
  useEffect(()=>{const controller=new AbortController();Promise.resolve().then(()=>{setLoading(true);setLoadError(false);});handoverRepository.list({},controller.signal).then(setRows).catch(error=>{if((error as Error).name!=="AbortError"){setRows([]);setLoadError(true);}}).finally(()=>setLoading(false));return()=>controller.abort();},[reloadKey]);
  const change=(patch:Record<string,string|string[]>)=>router.replace(updateSearch(pathname,searchParams.toString(),patch),{scroll:false});
  const filtered=rows.filter(row=>(!projectFilters.length||projectFilters.includes(row.project))&&(!statusFilters.length||statusFilters.includes(statusLabel(row.status)))&&(!ownerFilters.length||ownerFilters.includes(row.owner))&&(!query||`${row.unit} ${row.client}`.toLocaleLowerCase("cs-CZ").includes(query.toLocaleLowerCase("cs-CZ")))&&(!readinessFrom||row.readiness>=Number(readinessFrom))&&(!readinessTo||row.readiness<=Number(readinessTo))&&(!dateFrom||localDateKey(new Date(row.scheduledAt))>=dateFrom)&&(!dateTo||localDateKey(new Date(row.scheduledAt))<=dateTo)&&(!warningFilters.length||(warningFilters.includes("S upozorněním")&&Boolean(row.attention))||(warningFilters.includes("Bez upozornění")&&!row.attention)));
  const sorted=stableSort(filtered,row=>sort==="project"?row.project:sort==="unit"?`${row.unit} ${row.client}`:sort==="owner"?row.owner:sort==="readiness"?row.readiness:sort==="status"?Object.keys({planned:0,ready:1,in_progress:2,completed:3,cancelled:4}).indexOf(row.status):sort==="attention"?String(Boolean(row.attention)):new Date(row.scheduledAt),direction,row=>row.id);
  const calendarRows=stableSort(rows,row=>new Date(row.scheduledAt),"asc",row=>row.id);
  const start=addCalendarDays(now??new Date(),weekOffset*7);const days=Array.from({length:7},(_,index)=>addCalendarDays(start,index));const todayKey=now?localDateKey(now):"";
  const futureRows=sorted.filter(row=>localDateKey(new Date(row.scheduledAt))>=todayKey);
  const activeFilters=query||projectFilters.length||statusFilters.length||ownerFilters.length||warningFilters.length||readinessFrom||readinessTo||dateFrom||dateTo;
  const handoverGridTemplate=[columnState.isVisible("date")&&"110px","minmax(180px,1.4fr)",columnState.isVisible("client")&&"minmax(150px,1fr)",columnState.isVisible("place")&&"minmax(140px,1fr)",columnState.isVisible("owner")&&"minmax(140px,1fr)",columnState.isVisible("readiness")&&"150px",columnState.isVisible("status")&&"130px",columnState.isVisible("alerts")&&"minmax(170px,1.2fr)","28px"].filter(Boolean).join(" ");
  return (
    <div className="module-stack handover-workspace">
      <section className="card handover-week-card"><div className="handover-week-head"><div><span className="eyebrow">TÝDENNÍ KALENDÁŘ</span><h2>{formatPragueDate(start,{month:"long",year:"numeric"})}</h2><p>{formatPragueDate(start)} – {formatPragueDate(days[6])}</p></div><div><button className="secondary-button compact" onClick={()=>{setWeekOffset(value=>value-1);change({week:String(weekOffset-1)});}}><ChevronRight className="rotate-180" size={16}/> Předchozí</button><button className="secondary-button compact" onClick={()=>{setWeekOffset(0);change({week:""});notify("Zobrazen dnešní den");}}>Dnes</button><button className="secondary-button compact" onClick={()=>{setWeekOffset(value=>value+1);change({week:String(weekOffset+1)});}}>Další <ChevronRight size={16}/></button></div></div>
        <div className="handover-week-grid">{days.map(day=>{const key=localDateKey(day);const events=calendarRows.filter(row=>localDateKey(new Date(row.scheduledAt))===key);return <section key={key} className={key===todayKey?"today":""}><header><small>{new Intl.DateTimeFormat("cs-CZ",{weekday:"short",timeZone:"Europe/Prague"}).format(day)}</small><strong>{new Intl.DateTimeFormat("cs-CZ",{day:"numeric",month:"numeric",timeZone:"Europe/Prague"}).format(day)}</strong>{key===todayKey&&<Badge tone="success">Dnes</Badge>}</header><div>{events.map(event=><button key={event.id} className="handover-event" onClick={()=>openUnit(units.find(unit=>unit.id===event.unit)??units[0])}><strong>{formatPragueTime(event.scheduledAt)} · {event.unit}</strong><span>{event.client}</span><small>{event.project}</small><small>{event.owner}</small><Badge tone={event.status==="ready"?"success":event.attention?"warning":"neutral"}>{statusLabel(event.status)}</Badge></button>)}{!events.length&&<span className="handover-empty">Bez předání</span>}</div></section>;})}</div>
      </section>
      <section className="card module-card"><div className="tab-card-header"><div><h2>Budoucí předání</h2></div><span className="list-toolbar-actions">{activeFilters&&<button className="text-button" onClick={()=>change({project:"",status:"",owner:"",warning:"",query:"",readyFrom:"",readyTo:"",dateFrom:"",dateTo:""})}>Zrušit filtry</button>}<TableColumnMenu columns={handoverTableColumns} state={columnState}/></span></div>
        {loading?<div className="empty-filter-state"><Clock3 size={21}/><strong>Načítám předání…</strong></div>:loadError?<div className="empty-filter-state"><AlertTriangle size={21}/><strong>Předání se nepodařilo načíst</strong><small>Zkontrolujte oprávnění nebo připojení backendu.</small></div>:<div className="handover-future-list"><div className="handover-future-head" style={{gridTemplateColumns:handoverGridTemplate}}>
          {columnState.isVisible("date")&&<ListColumnFilter label="Termín" active={Boolean(dateFrom||dateTo)} sortType="date" sortDirection={sort==="date"?direction:undefined} onSort={next=>change({sort:"date",dir:next})}><span className="column-range date-range"><input type="date" value={dateFrom} onChange={event=>change({dateFrom:event.target.value})} aria-label="Předání od"/><i>–</i><input type="date" value={dateTo} onChange={event=>change({dateTo:event.target.value})} aria-label="Předání do"/></span></ListColumnFilter>}
          <ListColumnFilter label="Jednotka a klient" active={Boolean(query||projectFilters.length)} sortDirection={sort==="unit"?direction:undefined} onSort={next=>change({sort:"unit",dir:next})}><input value={query} onChange={event=>change({query:event.target.value})} placeholder="Jednotka nebo klient…" aria-label="Filtrovat jednotku nebo klienta"/><span className="column-filter-subtitle">Projekt</span><MultiSelectFilter options={Array.from(new Set(rows.map(row=>row.project)))} selected={projectFilters} onChange={values=>change({project:values})} allLabel="Všechny projekty" ariaLabel="Filtrovat projekt předání"/></ListColumnFilter>
          {columnState.isVisible("client")&&<ListColumnFilter label="Klient"/>}{columnState.isVisible("place")&&<ListColumnFilter label="Místo"/>}{columnState.isVisible("owner")&&<ListColumnFilter label="Odpovědná osoba" active={ownerFilters.length>0} sortDirection={sort==="owner"?direction:undefined} onSort={next=>change({sort:"owner",dir:next})}><MultiSelectFilter options={Array.from(new Set(rows.map(row=>row.owner)))} selected={ownerFilters} onChange={values=>change({owner:values})} allLabel="Všichni odpovědní" ariaLabel="Filtrovat odpovědnou osobu"/></ListColumnFilter>}
          {columnState.isVisible("readiness")&&<ListColumnFilter label="Připravenost" active={Boolean(readinessFrom||readinessTo)} sortType="number" sortDirection={sort==="readiness"?direction:undefined} onSort={next=>change({sort:"readiness",dir:next})}><span className="column-range"><input inputMode="numeric" value={readinessFrom} onChange={event=>change({readyFrom:event.target.value})} placeholder="Od %" aria-label="Připravenost od"/><i>–</i><input inputMode="numeric" value={readinessTo} onChange={event=>change({readyTo:event.target.value})} placeholder="Do %" aria-label="Připravenost do"/></span></ListColumnFilter>}
          {columnState.isVisible("status")&&<ListColumnFilter label="Stav" active={statusFilters.length>0} sortDirection={sort==="status"?direction:undefined} onSort={next=>change({sort:"status",dir:next})}><MultiSelectFilter options={Array.from(new Set(rows.map(row=>statusLabel(row.status))))} selected={statusFilters} onChange={values=>change({status:values})} allLabel="Všechny stavy" ariaLabel="Filtrovat stav předání"/></ListColumnFilter>}
          {columnState.isVisible("alerts")&&<ListColumnFilter label="Upozornění" active={warningFilters.length>0} sortDirection={sort==="attention"?direction:undefined} onSort={next=>change({sort:"attention",dir:next})}><MultiSelectFilter options={["S upozorněním","Bez upozornění"]} selected={warningFilters} onChange={values=>change({warning:values})} allLabel="Všechna předání" ariaLabel="Filtrovat upozornění předání"/></ListColumnFilter>}<span/>
        </div>{futureRows.map(event=><article key={event.id} style={{gridTemplateColumns:handoverGridTemplate}} onClick={()=>openUnit(units.find(unit=>unit.id===event.unit)??units[0])}>{columnState.isVisible("date")&&<div className="handover-future-date"><strong>{formatPragueDate(event.scheduledAt,{day:"numeric",month:"short"})}</strong><span>{formatPragueTime(event.scheduledAt)}</span></div>}<span className="handover-future-unit"><strong>{event.unit}</strong><small>{event.project}</small></span>{columnState.isVisible("client")&&<span>{event.client}</span>}{columnState.isVisible("place")&&<span>{event.place??"—"}</span>}{columnState.isVisible("owner")&&<span className="handover-future-owner"><small>Odpovědná osoba</small><strong>{event.owner}</strong></span>}{columnState.isVisible("readiness")&&<span className="readiness"><small>Připravenost {event.readiness} %</small><i><b style={{width:`${event.readiness}%`}}/></i></span>}{columnState.isVisible("status")&&<span className="handover-future-status"><Badge tone={event.status==="ready"?"success":event.attention?"warning":"neutral"}>{statusLabel(event.status)}</Badge></span>}{columnState.isVisible("alerts")&&<span className={`handover-warning-slot${event.attention?" has-warning":""}`}>{event.attention&&<><AlertTriangle size={15}/>{event.attention}</>}</span>}<ChevronRight className="handover-future-open" size={17}/></article>)}{!futureRows.length&&<div className="empty-filter-state"><CalendarDays size={22}/><strong>Žádné budoucí předání neodpovídá filtrům</strong><small>Změňte filtry nebo přejděte na jiné období.</small></div>}</div>}
      </section>
    </div>
  );
}

function TasksPage({ rows, toggleTask, openUnit,scope,onScope,loading }: { rows: TaskRecord[]; toggleTask: (id: string|number) => void; openUnit: (unit: UnitRecord) => void;scope:"mine"|"all"|"completed";onScope:(scope:"mine"|"all"|"completed")=>void;loading:boolean }) {
  const router=useRouter();const pathname=usePathname();const searchParams=useSearchParams();const sort=searchParams.get("sort")??"due";const direction=(searchParams.get("dir")==="desc"?"desc":"asc") as SortDirection;const query=searchParams.get("tq")??"";const priorityFilters=listParam(searchParams,"tpriority");const ownerFilters=listParam(searchParams,"towner");const projectFilters=listParam(searchParams,"tproject");const change=(patch:Record<string,string|string[]>)=>router.replace(updateSearch(pathname,searchParams.toString(),patch),{scroll:false});const filteredRows=rows.filter(row=>(!query||`${row.title} ${row.object}`.toLocaleLowerCase("cs-CZ").includes(query.toLocaleLowerCase("cs-CZ")))&&(!priorityFilters.length||priorityFilters.includes(row.priority))&&(!ownerFilters.length||ownerFilters.includes(row.owner))&&(!projectFilters.length||projectFilters.includes(row.project)));const sortedRows=stableSort(filteredRows,row=>sort==="updated"?row.updatedAt??"":sort==="priority"?({Vysoká:3,Střední:2,Nízká:1} as Record<string,number>)[row.priority]??0:sort==="state"?String(row.done):sort==="owner"?row.owner:row.dueAt??row.due,direction,row=>String(row.id));
  const columnState=useTableColumns("tasks-table",taskTableColumns);const taskGridTemplate=["38px","5px","minmax(220px,1.5fr)",columnState.isVisible("object")&&"minmax(150px,1fr)",columnState.isVisible("project")&&"minmax(140px,.9fr)",columnState.isVisible("priority")&&"110px",columnState.isVisible("due")&&"110px",columnState.isVisible("owner")&&"70px",columnState.isVisible("status")&&"100px","38px"].filter(Boolean).join(" ");
  return (
    <section className="card module-card tasks-module">
      <nav className="task-tabs" aria-label="Pohledy úkolů"><button className={scope==="mine"?"active":""} aria-current={scope==="mine"?"page":undefined} onClick={()=>onScope("mine")}><UserRound className="task-tab-icon" size={17} /> Moje úkoly {scope==="mine"&&<span>{rows.length}</span>}</button><button className={scope==="all"?"active":""} aria-current={scope==="all"?"page":undefined} onClick={()=>onScope("all")}><List className="task-tab-icon" size={17} /> Všechny {scope==="all"&&<span>{rows.length}</span>}</button><button className={scope==="completed"?"active":""} aria-current={scope==="completed"?"page":undefined} onClick={()=>onScope("completed")}><CheckCircle2 className="task-tab-icon" size={17} /> Dokončené {scope==="completed"&&<span>{rows.length}</span>}</button><span className="task-tabs-spacer"/><TableColumnMenu columns={taskTableColumns} state={columnState}/></nav>
      <div className="task-list-head" style={{gridTemplateColumns:taskGridTemplate}}>
        <span/>
        <span/><ListColumnFilter label="Úkol" active={Boolean(query)}><input value={query} onChange={event=>change({tq:event.target.value})} placeholder="Název nebo objekt…" aria-label="Filtrovat úkol"/></ListColumnFilter>{columnState.isVisible("object")&&<ListColumnFilter label="Vazba"/>}{columnState.isVisible("project")&&<ListColumnFilter label="Projekt" active={projectFilters.length>0}><MultiSelectFilter options={Array.from(new Set(rows.map(row=>row.project)))} selected={projectFilters} onChange={values=>change({tproject:values})} allLabel="Všechny projekty" ariaLabel="Filtrovat projekt úkolu"/></ListColumnFilter>}{columnState.isVisible("priority")&&<ListColumnFilter label="Priorita" active={priorityFilters.length>0} sortType="number" sortDirection={sort==="priority"?direction:undefined} onSort={next=>change({sort:"priority",dir:next})}><MultiSelectFilter options={Array.from(new Set(rows.map(row=>row.priority)))} selected={priorityFilters} onChange={values=>change({tpriority:values})} allLabel="Všechny priority" ariaLabel="Filtrovat prioritu"/></ListColumnFilter>}{columnState.isVisible("due")&&<ListColumnFilter label="Termín" sortType="date" sortDirection={sort==="due"?direction:undefined} onSort={next=>change({sort:"due",dir:next})}/>} {columnState.isVisible("owner")&&<ListColumnFilter label="Odpovědná osoba" active={ownerFilters.length>0} sortDirection={sort==="owner"?direction:undefined} onSort={next=>change({sort:"owner",dir:next})}><MultiSelectFilter options={Array.from(new Set(rows.map(row=>row.owner)))} selected={ownerFilters} onChange={values=>change({towner:values})} allLabel="Všichni odpovědní" ariaLabel="Filtrovat odpovědnou osobu"/></ListColumnFilter>}{columnState.isVisible("status")&&<ListColumnFilter label="Stav"/>}<span/>
      </div>
      <div className="task-section-label"><span>Dnes</span><i /></div>
      <div className="large-task-list">
        {loading?<div className="empty-next"><Clock3 size={20}/><span><strong>Načítám úkoly…</strong><small>Aktualizuji zvolený pohled.</small></span></div>:sortedRows.map((task) => <article key={task.id} style={{gridTemplateColumns:taskGridTemplate}} className={task.done ? "done" : ""}>
          <button onClick={() => toggleTask(task.id)} className="task-check large" aria-label={`Dokončit úkol ${task.title}`}>{task.done && <Check size={15} />}</button>
          <span className={`priority-bar ${task.priority.toLowerCase().replace("á", "a").replace("ř", "r")}`} />
          <button className="task-main-copy" onClick={() => openUnit(units.find((unit) => unit.id === task.object.split(" · ")[0]) || units[0])}><strong>{task.title}</strong></button>{columnState.isVisible("object")&&<span>{task.object}</span>}{columnState.isVisible("project")&&<span>{task.project}</span>}
          {columnState.isVisible("priority")&&<Badge tone={task.priority === "Vysoká" ? "danger" : task.priority === "Střední" ? "warning" : "neutral"}>{task.priority}</Badge>}
          {columnState.isVisible("due")&&<span className={`task-due ${task.due === "Dnes" ? "urgent" : ""}`}><Clock3 size={15} />{task.due}</span>}
          {columnState.isVisible("owner")&&<Avatar initials={initials(task.owner)} small />}{columnState.isVisible("status")&&<Badge tone={task.done?"success":"neutral"}>{task.done?"Dokončeno":"Otevřeno"}</Badge>}
          <button className="ghost-icon"><MoreHorizontal size={18} /></button>
        </article>)}
      </div>
      <div className="task-section-label muted-label"><span>Následující</span><i /></div>
      <div className="empty-next"><CheckCircle2 size={22} /><span><strong>Máte hotovo</strong><small>Další úkoly se zobrazí podle termínu a priority.</small></span></div>
    </section>
  );
}

function AdminUsersPage({notify}:{notify:(message:string)=>void}){
  const [snapshot,setSnapshot]=useState<AdminSnapshot|null>(null);const [loading,setLoading]=useState(true);const [tab,setTab]=useState<"users"|"roles">("users");const [editing,setEditing]=useState<AdminUser|"new"|null>(null);const [editingRole,setEditingRole]=useState<AdminRole|null>(null);
  const reload=()=>{setLoading(true);adminRepository.getSnapshot().then(setSnapshot).catch(()=>setSnapshot(null)).finally(()=>setLoading(false));};
  useEffect(()=>{adminRepository.getSnapshot().then(setSnapshot).catch(()=>setSnapshot(null)).finally(()=>setLoading(false));},[]);
  if(loading)return <section className="card module-card"><div className="empty-filter-state"><Clock3 size={22}/><strong>Načítám administraci…</strong></div></section>;
  if(!snapshot)return <section className="card module-card"><div className="empty-filter-state"><AlertTriangle size={22}/><strong>Administraci se nepodařilo načíst</strong><button className="secondary-button compact" onClick={reload}>Zkusit znovu</button></div></section>;
  const capability=(role:AdminRole,kind:string)=>role.permissionCodes.some(code=>{const operation=getPermissionDefinition(code).operation;return kind==="view"?operation==="view":kind==="create"?["create","import"].includes(operation):kind==="edit"?["update","manage","assign","record"].includes(operation):kind==="approve"?["review","approve"].includes(operation):kind==="archive"?operation==="archive":operation==="export";});
  return <div className="module-stack admin-page"><nav className="workspace-subnav"><button className={tab==="users"?"active":""} onClick={()=>setTab("users")}><Users size={17}/> Uživatelé</button><button className={tab==="roles"?"active":""} onClick={()=>setTab("roles")}><ShieldCheck size={17}/> Role a oprávnění</button></nav>
    {tab==="users"?<section className="card module-card"><div className="tab-card-header"><div><h2>Uživatelé workspace</h2><p>Přihlášení zajišťuje Microsoft Entra ID. CRM nespravuje hesla.</p></div><button className="primary-button" onClick={()=>setEditing("new")}><Plus size={16}/> Pozvat uživatele</button></div><div className="unit-table-wrap"><table className="data-table admin-users-table"><thead><tr><th>Uživatel</th><th>Pracovní role</th><th>Efektivní rozsah</th><th>Poslední přihlášení</th><th>Stav</th><th/></tr></thead><tbody>{snapshot.users.map(user=><tr key={user.membershipId} onClick={()=>setEditing(user)}><td><span className="person-cell"><Avatar initials={initials(user.name)} small/><span><strong>{user.name}</strong><small>{user.email}{user.jobTitle?` · ${user.jobTitle}`:""}</small></span></span></td><td><RoleChips items={user.roleIds.map(id=>{const role=snapshot.roles.find(item=>item.id===id);return{key:id,label:role?roleDisplayName(role.code,role.name):"Vlastní role"};})}/></td><td><strong>{user.projectIds.length?`${user.projectIds.length} projektů`:"Workspace"}</strong><small>{new Set(user.roleIds.flatMap(id=>snapshot.roles.find(role=>role.id===id)?.permissionCodes??[])).size} efektivních oprávnění</small></td><td><time>{user.lastLoginAt?formatPragueDateTime(user.lastLoginAt):"Dosud nepřihlášen"}</time></td><td><Badge tone={user.status==="active"?"success":user.status==="invited"?"warning":"neutral"}>{({active:"Aktivní",invited:"Pozván",suspended:"Deaktivován",archived:"Odebraný přístup"} as Record<string,string>)[user.status]}</Badge></td><td><ChevronRight size={17}/></td></tr>)}</tbody></table></div></section>:<section className="card module-card"><div className="tab-card-header"><div><h2>Matice oprávnění</h2><p>Efektivní práva jsou vynucena backendem a RLS; ozubené kolečko vždy otevře detail role.</p></div></div><div className="unit-table-wrap"><table className="data-table permission-matrix"><thead><tr><th>Role</th>{["Zobrazit","Vytvářet","Upravovat","Schvalovat","Archivovat","Exportovat"].map(label=><th key={label}>{label}</th>)}<th/></tr></thead><tbody>{snapshot.roles.map(role=><tr key={role.id}><td><strong>{roleDisplayName(role.code,role.name)} <Badge tone="neutral">{role.assignedUserCount??0} uživ.</Badge></strong><small>{role.description}</small></td>{["view","create","edit","approve","archive","export"].map(kind=><td key={kind}>{capability(role,kind)?<CheckCircle2 size={18} className="permission-yes"/>:<span className="permission-no">—</span>}</td>)}<td><button className="ghost-icon" onClick={()=>setEditingRole(role)} aria-label={`Otevřít detail role ${roleDisplayName(role.code,role.name)}`}><Settings size={17}/></button></td></tr>)}</tbody></table></div></section>}
    {editing&&<AdminUserModal value={editing==="new"?null:editing} snapshot={snapshot} close={()=>setEditing(null)} save={async value=>{if(editing==="new")await adminRepository.invite(value);else await adminRepository.update({...editing,...value,lastLoginAt:editing.lastLoginAt});setEditing(null);notify(editing==="new"?"Pozvánka byla vytvořena":"Uživatel byl uložen");reload();}}/>}
    {editingRole&&<RolePermissionsModal role={editingRole} permissions={snapshot.permissions} close={()=>setEditingRole(null)} save={async permissionCodes=>{await adminRepository.setRolePermissions(editingRole.id,permissionCodes);setEditingRole(null);notify("Oprávnění role byla uložena");reload();}}/>}
  </div>;
}

function AdminUserModal({value,snapshot,close,save}:{value:AdminUser|null;snapshot:AdminSnapshot;close:()=>void;save:(value:Omit<AdminUser,"membershipId"|"userId"|"lastLoginAt">)=>Promise<void>}){
  const [name,setName]=useState(value?.name??"");const [email,setEmail]=useState(value?.email??"");const [jobTitle,setJobTitle]=useState(value?.jobTitle??"");const [workPhone,setWorkPhone]=useState(value?.workPhone??"");const [status,setStatus]=useState<AdminUser["status"]>(value?.status??"invited");const [roleIds,setRoleIds]=useState(value?.roleIds??[]);const [projectIds,setProjectIds]=useState(value?.projectIds??[]);const [showTechnical,setShowTechnical]=useState(false);
  const effective=[...new Set(roleIds.flatMap(id=>snapshot.roles.find(role=>role.id===id)?.permissionCodes??[]))].map(code=>{const roles=snapshot.roles.filter(role=>roleIds.includes(role.id)&&role.permissionCodes.includes(code));const scopes=roles.map(role=>role.permissionGrants?.find(grant=>grant.code===code)?.scope??(projectIds.length?"project":"workspace"));const scope=scopes.includes("workspace")?"workspace":scopes[0]??(projectIds.length?"project":"workspace");return{definition:getPermissionDefinition(code),roles:roles.map(role=>roleDisplayName(role.code,role.name)),scope};}).sort((a,b)=>sortPermissionDefinitions(a.definition,b.definition));
  const grouped=permissionCategoryOrder.map(category=>({category,items:effective.filter(item=>item.definition.category===category)})).filter(group=>group.items.length);
  const entraManaged=Boolean(value&&value.status==="active");
  return <FormModal title={value?`Upravit ${value.name}`:"Pozvat uživatele"} close={close} saveLabel={value?"Uložit uživatele":"Odeslat pozvánku"} onSave={async()=>{if(!name.trim()||!email.includes("@"))throw new Error("Doplňte jméno a platný pracovní e-mail");if(!roleIds.length)throw new Error("Vyberte alespoň jednu roli");await save({name,email,jobTitle,workPhone,status,roleIds,projectIds});}}>
    <div className="form-row"><label><span>Jméno</span><input value={name} onChange={event=>setName(event.target.value)}/></label><label><span>Pracovní e-mail</span><input type="email" value={email} disabled={entraManaged} onChange={event=>setEmail(event.target.value)}/>{entraManaged&&<small>E-mail se synchronizuje z Microsoft Entra ID.</small>}</label></div>
    <div className="form-row"><label><span>Pracovní pozice</span><input value={jobTitle} onChange={event=>setJobTitle(event.target.value)}/></label><label><span>Pracovní telefon</span><input value={workPhone} onChange={event=>setWorkPhone(event.target.value)}/></label></div>
    {value&&<label><span>Stav přístupu</span><select value={status} onChange={event=>setStatus(event.target.value as AdminUser["status"])}><option value="active">Aktivní</option><option value="suspended">Deaktivovaný</option><option value="archived">Odebrat přístup</option><option value="invited">Pozván</option></select></label>}
    <fieldset className="admin-check-grid"><legend>Role</legend>{snapshot.roles.map(role=><label key={role.id}><input type="checkbox" checked={roleIds.includes(role.id)} onChange={()=>setRoleIds(current=>current.includes(role.id)?current.filter(id=>id!==role.id):[...current,role.id])}/><span>{roleDisplayName(role.code,role.name)}</span></label>)}</fieldset>
    <fieldset className="admin-check-grid"><legend>Projektový rozsah</legend><label><input type="checkbox" checked={!projectIds.length} onChange={()=>setProjectIds([])}/><span>Všechny projekty</span></label>{snapshot.projects.map(project=><label key={project.id}><input type="checkbox" checked={projectIds.includes(project.id)} onChange={()=>setProjectIds(current=>current.includes(project.id)?current.filter(id=>id!==project.id):[...current,project.id])}/><span>{project.name}</span></label>)}</fieldset>
    <section className="effective-permissions grouped"><div className="effective-permissions-head"><strong>Efektivní oprávnění ({effective.length})</strong><label className="technical-name-toggle"><input type="checkbox" checked={showTechnical} onChange={event=>setShowTechnical(event.target.checked)}/><span>Zobrazit technické názvy</span></label></div>{grouped.length?grouped.map(group=><section key={group.category}><h3>{group.category}</h3>{group.items.map(item=><article key={item.definition.key}><strong>{item.definition.name}</strong><small>Získáno z role: {item.roles.join(", ")}</small><em>Rozsah: {permissionScopeLabel(item.scope)}</em>{showTechnical&&<code>Technický klíč: {item.definition.key}</code>}</article>)}</section>):<p>Žádná oprávnění</p>}</section>
    <p className="form-help"><ShieldCheck size={14}/> Projektový rozsah i role jsou kontrolovány také na backendu.</p>
  </FormModal>;
}

function RolePermissionsModal({role,permissions,close,save}:{role:AdminRole;permissions:Array<{code:string;description:string}>;close:()=>void;save:(codes:string[])=>Promise<void>}){
  const [selected,setSelected]=useState(role.permissionCodes);const [showTechnical,setShowTechnical]=useState(false);const available=permissions.map(permission=>getPermissionDefinition(permission.code)).sort(sortPermissionDefinitions);const groups=permissionCategoryOrder.map(category=>({category,items:available.filter(permission=>permission.category===category)})).filter(group=>group.items.length);
  return <FormModal title={`Detail role · ${role.name}`} close={close} onSave={()=>save(selected)}><div className="role-detail-summary"><span><small>UŽIVATELÉ S ROLÍ</small><strong>{role.assignedUserCount??0}</strong></span><span><small>TYP ROLE</small><strong>{role.isSystem?"Systémová":"Vlastní"}</strong></span></div><p>{role.description}</p>{role.restrictions?.map(item=><div className="form-warning" key={item}><ShieldCheck size={15}/>{item}</div>)}<label className="technical-name-toggle"><input type="checkbox" checked={showTechnical} onChange={event=>setShowTechnical(event.target.checked)}/><span>Zobrazit technické názvy</span></label><div className="permission-editor grouped">{groups.map(group=><section key={group.category}><h3>{group.category}</h3>{group.items.sort((a,b)=>permissionOperationOrder.indexOf(a.operation)-permissionOperationOrder.indexOf(b.operation)||a.name.localeCompare(b.name,"cs")).map(permission=>{const scope=role.permissionGrants?.find(grant=>grant.code===permission.key)?.scope??"workspace";return <label key={permission.key}><input type="checkbox" checked={selected.includes(permission.key)} onChange={()=>setSelected(current=>current.includes(permission.key)?current.filter(code=>code!==permission.key):[...current,permission.key])}/><span><strong>{permission.name}</strong><small>{permission.description}</small><em>Rozsah: {permissionScopeLabel(scope)}</em>{permission.systemRestriction&&<em className="permission-restriction">Omezení: {permission.systemRestriction}</em>}{showTechnical&&<code>Technický klíč: {permission.key}</code>}</span></label>})}</section>)}</div>{role.history?.length?<div className="role-history"><strong>Poslední změny oprávnění</strong>{role.history.map((item,index)=><small key={`${item.occurredAt}-${index}`}>{formatPragueDateTime(item.occurredAt)} · {item.actor}</small>)}</div>:null}<p className="form-help"><History size={14}/> Každá změna se zapisuje do auditu a outboxu. Systémová omezení nelze obejít.</p></FormModal>;
}

function UnitPreview({ unit, close, open, previous, next, position, total }: { unit: UnitRecord; close: () => void; open: () => void; previous: () => void; next: () => void; position: number; total: number }) {
  const workflow=projectUnitSalesWorkflow({unit,context:unitCommercialContexts[unit.id],contracts});
  return (
    <aside className="preview-panel">
      <div className="preview-browser"><span>{position} z {total} jednotek ve výběru</span><div><button onClick={previous} aria-label="Předchozí jednotka"><ChevronRight className="rotate-180" size={17} /></button><button onClick={next} aria-label="Další jednotka"><ChevronRight size={17} /></button><button onClick={close} aria-label="Zavřít náhled"><X size={18} /></button></div></div>
      <div className="preview-header"><div><span className="preview-project">{unit.project} · {unit.building}</span><h2>{unit.id} <Badge>{workflow.commercialStatusLabel}</Badge></h2><p>{unit.layout} · {unit.area.toLocaleString("cs-CZ")} m² · {unit.floor}</p></div></div>
      <div className={`preview-attention ${unit.attention ? "" : "calm"}`}><AlertTriangle size={18} /><span><strong>{unit.attention ? "Nejbližší důležitý krok" : "Doporučený další krok"}</strong><small>{unit.attention || (unit.status === "Volný" ? "Jednotka je připravena k nabídnutí zájemci" : "Pokračovat podle obchodního workflow")}</small></span></div>
      <div className="mini-floorplan"><div className="room living"><span>Obývací pokoj + kk</span></div><div className="room bed"><span>Ložnice</span></div><div className="room bath"><span>Koupelna</span></div><div className="room hall"><span>Chodba</span></div><div className="room bed2"><span>Pokoj</span></div><div className="balcony">Lodžie 8,2 m²</div></div>
      <div className="preview-grid"><span><small>Aktuální cena</small><strong>{formatMoney(unit.price)}</strong></span><span><small>Obchodní stav</small><strong><Badge>{workflow.commercialStatusLabel}</Badge></strong></span><span><small>Stavební stav</small><strong>{unit.construction}</strong></span><span><small>Klient</small><strong>{unit.client || "Bez klienta"}</strong></span></div>
      <div className="preview-section"><h3>Příslušenství</h3><p>{unit.accessory}</p></div>
      <div className="preview-flow"><h3>Prodejní proces</h3><div>{unitSalesWorkflowSteps.map((stage,index)=><span className={index<=workflow.completedThrough?"complete":index===workflow.activeIndex?"current":""} key={stage}><i>{index+1}</i><small>{stage}</small></span>)}</div></div>
      <div className="preview-footer"><button className="secondary-button" onClick={close}>Zavřít</button><button className="primary-button" onClick={open}>Otevřít celý detail <ArrowRight size={17} /></button></div>
    </aside>
  );
}

function UnitDetail({ unit, tab, onTab, onBack,openProjects,openProject, notify, openTask, openClient,openContract,onNewContract,onNewHandover,handoverVersion,handoverMemberships,onHandoverChanged, onEdit, onEditPrice,priceProposals,onDecidePrice,onManageAccessories,onEditFloorplan,onSalesAction,onChangeBuyer,canCreateHold,canConfirmHold,canCancelHold,canRecordPayment,onPaymentChanged,onContractWorkflow,timelineVersion }: { unit: UnitRecord; tab: UnitTab; onTab: (tab: UnitTab) => void; onBack: () => void;openProjects:()=>void;openProject:()=>void; notify: (message: string) => void; openTask: () => void; openClient: (name: string) => void;openContract:(contract:(typeof contracts)[number])=>void;onNewContract?:(action:UnitNextContractAction)=>void;onNewHandover?:()=>void;handoverVersion:number;handoverMemberships:MembershipOption[];onHandoverChanged:()=>void; onEdit?: () => void; onEditPrice?: () => void;priceProposals:NonNullable<CommercialSnapshot["priceProposals"]>;onDecidePrice?:(proposalId:string,decision:"approved"|"rejected")=>Promise<void>;onManageAccessories?:()=>void;onEditFloorplan?:()=>void;onSalesAction?:(mode:"interest"|"pre_reservation"|"reservation"|"convert"|"cancel")=>void;onChangeBuyer?:()=>void;canCreateHold?:boolean;canConfirmHold?:boolean;canCancelHold?:boolean;canRecordPayment?:boolean;onPaymentChanged?:()=>void;onContractWorkflow?:(contract:(typeof contracts)[number])=>void;timelineVersion:number }) {
  const [timeline,setTimeline]=useState<TimelineRecord[]>([]);useEffect(()=>{const controller=new AbortController();activityRepository.unitTimeline(unit.backendId??unit.id,unit.id,controller.signal).then(setTimeline).catch(()=>setTimeline([]));return()=>controller.abort();},[unit.backendId,unit.id,tab,timelineVersion]);
  const [unitHandovers,setUnitHandovers]=useState<HandoverRecord[]>([]);useEffect(()=>{const unitId=backendEntityId(unit.backendId);if(!unitId){Promise.resolve().then(()=>setUnitHandovers([]));return;}const controller=new AbortController();handoverRepository.list({unitId},controller.signal).then(setUnitHandovers).catch(()=>setUnitHandovers([]));return()=>controller.abort();},[unit.backendId,handoverVersion]);
  const [loadedNextContractAction,setLoadedNextContractAction]=useState<{unitId:string;value:UnitNextContractAction}|null>(null);useEffect(()=>{const unitId=backendEntityId(unit.backendId);if(!unitId)return;const controller=new AbortController();commercialRepository.getNextContractAction(unitId,controller.signal).then(value=>setLoadedNextContractAction({unitId,value})).catch(()=>setLoadedNextContractAction(current=>current?.unitId===unitId?null:current));return()=>controller.abort();},[unit.backendId,unit.id,timelineVersion]);
  const nextContractAction=loadedNextContractAction?.unitId===unit.backendId?loadedNextContractAction.value:null;
  const salesProcess=nextContractAction?.salesProcess??projectUnitSalesWorkflow({unit,context:unitCommercialContexts[unit.id],contracts});
  const currentHandover=unitHandovers.find(record=>["planned","ready","in_progress"].includes(record.status))??unitHandovers.find(record=>record.status==="completed");
  const currentHandoverLabel=currentHandover?handoverStatusLabel(currentHandover.status):"Neplánováno";
  const tabs: { id: UnitTab; label: string; icon: typeof Home; count?: number }[] = [
    { id: "overview", label: "Přehled", icon: LayoutDashboard }, { id: "contracts", label: "Smlouvy", icon: FileText, count: contracts.filter(contract=>contract.unit===unit.id).length||undefined }, { id: "payments", label: "Platby", icon: CircleDollarSign }, { id: "changes", label: "Klientské změny", icon: SlidersHorizontal }, { id: "documents", label: "Dokumenty", icon: FolderOpen }, { id: "handover", label: "Předání", icon: KeyRound }, { id: "tasks", label: "Úkoly", icon: ClipboardCheck }, { id: "history", label: "Historie", icon: History },
  ];
  return (
    <div className="unit-detail">
      <div className="unit-breadcrumb"><button onClick={openProjects}>Všechny projekty</button><ChevronRight size={14}/><button onClick={openProject}>{unit.project}</button><ChevronRight size={14}/><button onClick={onBack}>Jednotky</button><ChevronRight size={14}/><strong>{unit.id}</strong></div>
      <div className="unit-hero">
        <div className="unit-identity"><span className="unit-symbol"><Home size={23} /></span><div><span>{unit.project} · {unit.building}</span><h1>{unit.id} <Badge>{salesProcess.commercialStatusLabel}</Badge></h1><p>{unit.layout} · {unit.area.toLocaleString("cs-CZ")} m² · {unit.floor} · orientace {unit.orientation}</p></div></div>
        <div className="unit-hero-actions">{onEdit&&<button className="secondary-button" onClick={onEdit}><MoreHorizontal size={17} /> Upravit jednotku</button>}<button className="secondary-button" onClick={() => notify("Odkaz na jednotku byl zkopírován")}><Link2 size={17} /> Sdílet odkaz</button>{nextContractAction?.kind==="create_contract"&&onNewContract&&<button className="primary-button" onClick={()=>onNewContract(nextContractAction)}><FileText size={17} /> {nextContractAction.label}</button>}{nextContractAction?.kind==="open_contracts"&&<button className="primary-button" onClick={()=>onTab("contracts")}><FileText size={17}/> Otevřít smlouvy</button>}</div>
      </div>
      <div className="unit-status-strip">
        <span><small>OBCHODNÍ STAV</small><strong><Badge>{salesProcess.commercialStatusLabel}</Badge></strong></span>
        <span><small>STAV VÝSTAVBY</small><strong><HardHat size={16} /> {unit.construction}</strong></span>
        <span><small>PŘEDÁNÍ</small><strong><KeyRound size={16} /> {currentHandoverLabel}</strong></span>
        <span className="attention-status"><small>VYŽADUJE POZORNOST</small><strong><AlertTriangle size={16} /> {unit.attention || "Bez otevřených bodů"}</strong></span>
      </div>
      <nav className="unit-tabs unit-detail-tabs" aria-label="Navigace jednotky">{tabs.map((item) => { const TabIcon = item.icon; return <button key={item.id} className={tab === item.id ? "active" : ""} aria-current={tab === item.id ? "page" : undefined} onClick={() => onTab(item.id)}><TabIcon className="unit-tab-icon" size={17} />{item.label}{item.count && <span aria-label={`${item.count} položek`}>{item.count}</span>}</button>; })}</nav>

      {tab === "overview" && <UnitOverview unit={unit} notify={notify} openClient={openClient} openTab={onTab} onEditPrice={onEditPrice} priceProposals={priceProposals} onDecidePrice={onDecidePrice} onManageAccessories={onManageAccessories} onEditFloorplan={onEditFloorplan} onSalesAction={onSalesAction} canCreateHold={canCreateHold} canConfirmHold={canConfirmHold} canCancelHold={canCancelHold} timeline={timeline} workflow={salesProcess} />}
      {tab === "contracts" && <UnitContracts unit={unit} openContract={openContract} onNewContract={nextContractAction?.kind==="create_contract"&&onNewContract?()=>onNewContract(nextContractAction):undefined} onWorkflow={onContractWorkflow} onChangeBuyer={onChangeBuyer} />}
      {tab === "payments" && <UnitPayments unit={unit} canRecord={Boolean(canRecordPayment)} onChanged={onPaymentChanged} />}
      {tab === "changes" && <UnitClientChanges unit={unit} notify={notify} />}
      {tab === "documents" && <UnitDocuments unit={unit} notify={notify} />}
      {tab === "handover" && <UnitHandover unit={unit} notify={notify} onNew={onNewHandover} version={handoverVersion} memberships={handoverMemberships} onChanged={onHandoverChanged} />}
      {tab === "tasks" && <UnitTasks unit={unit} openTask={openTask} />}
      {tab === "history" && <UnitHistory unit={unit} timeline={timeline} />}
    </div>
  );
}

function UnitOverview({ unit, notify, openClient,openTab, onEditPrice,priceProposals,onDecidePrice,onManageAccessories,onEditFloorplan,onSalesAction,canCreateHold,canConfirmHold,canCancelHold,timeline,workflow }: { unit: UnitRecord; notify: (message: string) => void; openClient: (name: string) => void;openTab:(tab:UnitTab)=>void; onEditPrice?: () => void;priceProposals:NonNullable<CommercialSnapshot["priceProposals"]>;onDecidePrice?:(proposalId:string,decision:"approved"|"rejected")=>Promise<void>;onManageAccessories?:()=>void;onEditFloorplan?:()=>void;onSalesAction?:(mode:"interest"|"pre_reservation"|"reservation"|"convert"|"cancel")=>void;canCreateHold?:boolean;canConfirmHold?:boolean;canCancelHold?:boolean;timeline:TimelineRecord[];workflow:ReturnType<typeof projectUnitSalesWorkflow> }) {
  const [floorplanOpen, setFloorplanOpen] = useState(false);
  const [loadedFloorplan,setLoadedFloorplan]=useState<MediaLink|null>(null);const floorplanMedia=unit.floorplanImageUrl?{id:unit.floorplanImageUrl,entityType:"unit" as const,entityId:unit.backendId??unit.id,kind:"floorplan" as const,fileName:unit.floorplanFileName??"Půdorys",mimeType:unit.floorplanMimeType??"image/jpeg",url:unit.floorplanImageUrl,uploadedAt:unit.floorplanUploadedAt??undefined,uploadedBy:unit.floorplanUploadedBy??undefined}:loadedFloorplan;const floorplanUrl=floorplanMedia?.url??null;const floorplanIsPdf=floorplanMedia?.mimeType==="application/pdf";const floorplanDownloadUrl=floorplanUrl?`${floorplanUrl}${floorplanUrl.includes("?")?"&":"?"}download=1`:null;useEffect(()=>{const unitId=backendEntityId(unit.backendId);if(unit.floorplanImageUrl||!unitId)return;const controller=new AbortController();mediaRepository.get("unit",unitId,controller.signal).then(media=>setLoadedFloorplan(media)).catch(()=>undefined);return()=>controller.abort();},[unit.backendId,unit.floorplanImageUrl]);
  const [priceHistoryOpen, setPriceHistoryOpen] = useState(false);
  const commercial=unitCommercialContexts[unit.id];
  const buyers=commercial?.buyers ?? [];
  const interestRows=commercial?.interests ?? [];
  const isDejvice=isDejviceUnit(unit);
  const accessoryItems=unit.accessories??[];
  return (
    <>
    <div className="unit-overview-grid">
      <div className="unit-main-column">
        <section className="card sales-process-card">
          <SectionTitle title="Prodejní proces" />
          <div className="sales-progress">{unitSalesWorkflowSteps.map((stage,index)=>{const complete=index<=workflow.completedThrough;const current=index===workflow.activeIndex&&!complete;return <div key={stage} className={complete?"complete":current?"current":""}><span>{complete?<Check size={14}/>:index+1}</span><strong>{stage}</strong><small>{current?(stage==="Předrezervace"&&commercial?.hold?`Platí do ${new Date(commercial.hold.expiresAt).toLocaleDateString("cs-CZ")}`:"Aktuální etapa"):complete?"Hotovo":"Čeká"}</small></div>;})}</div>
          {onSalesAction&&<div className="sales-action-strip"><span><small>OBCHODNÍ AKCE</small><strong>Stav se mění pouze řízenou operací</strong></span><div>{!commercial?.hold&&isUnitCommerciallyAvailable(unit.status)&&<>{canCreateHold&&<button className="secondary-button compact" onClick={()=>onSalesAction("pre_reservation")}>Předrezervace</button>}{canConfirmHold&&<button className="secondary-button compact" onClick={()=>onSalesAction("reservation")}>Rezervace</button>}</>}{commercial?.hold?.type==="pre_reservation"&&canConfirmHold&&<button className="primary-button compact" onClick={()=>onSalesAction("convert")}>Převést na rezervaci</button>}{commercial?.hold&&canCancelHold&&<button className="secondary-button compact danger-text" onClick={()=>onSalesAction("cancel")}>Zrušit / uvolnit</button>}</div></div>}
        </section>
        <section className="card client-detail-card">
          <SectionTitle title="Aktuální kupující" action="Otevřít kartu klienta" onAction={() => buyers[0] ? openClient(buyers[0].name) : notify("Jednotka zatím nemá přiřazeného kupujícího")} />
          <div className="buyers">{buyers.length?buyers.map((buyer)=><div key={buyer.partyId}><Avatar initials={initials(buyer.name)} /><span><strong>{buyer.name}</strong><small>{buyer.role==="co_buyer"?"Spolukupující":"Kupující"}{buyer.share?` · podíl ${Math.round(buyer.share*100)} %`:""}</small><em><Mail size={14} /> {buyer.email}</em></span></div>):<div className="empty-client-row"><span><strong>Bez přiřazeného klienta</strong><small>Vyhledejte existujícího klienta a zaznamenejte zájem.</small></span>{onSalesAction&&<button className="secondary-button compact" onClick={()=>onSalesAction("interest")}><Plus size={15}/> Přidat zájemce</button>}</div>}</div>
          {(commercial?.buyerHistory?.length??0)>0&&<div className="buyer-history"><strong>Historie kupujících</strong>{commercial?.buyerHistory?.map(event=><article key={event.id}><History size={15}/><span><b>{event.previousBuyers.map(item=>item.name).join(" · ")||"Bez kupujícího"} → {event.currentBuyers.map(item=>item.name).join(" · ")||"Bez kupujícího"}</b><small>{formatPragueDateTime(event.occurredAt)} · {event.actor}</small>{event.sourceContractReference&&<small>Dokument: {event.sourceContractReference}</small>}<em>{event.reason}</em></span></article>)}</div>}
          {!isDejvice&&<div className="client-note"><MessageSquare size={16} /><span><small>INTERNÍ POZNÁMKA</small><p>Preferují komunikaci e-mailem. Financování z vlastních zdrojů.</p></span></div>}
        </section>
        <section className="card accessories-card">
          <SectionTitle title="Příslušenství" action={onManageAccessories?"Spravovat":undefined} onAction={onManageAccessories} />
          <div className="accessory-list">{accessoryItems.length?accessoryItems.map(item=><button type="button" key={item.assignmentId??item.id} onClick={onManageAccessories} aria-label={`Otevřít ${item.type.toLocaleLowerCase("cs-CZ")} ${item.code}`}><i className="accessory-icon">{item.category==="cellar"?<Home size={17}/>:item.category==="wallbox"?<Activity size={17}/>:<KeyRound size={17}/>}</i><span><strong>{item.type} {item.code}{item.areaM2?` (${item.areaM2} m²)`:""}</strong><small>Přiřazeno přes časově platnou vazbu{item.relation?` · navázáno na ${item.relation}`:""}</small></span><Badge tone="success">{formatMoney(item.amount??0)}</Badge><ChevronRight size={16}/></button>):<div className="empty-inline"><strong>Bez příslušenství</strong><small>Vyberte dostupný sklep, parking nebo wallbox projektu.</small></div>}</div>
        </section>
        <section className="card price-card">
          <SectionTitle title="Cena" action="Otevřít historii cen" onAction={() => setPriceHistoryOpen(true)} />
          <div className="price-summary"><span><small>AKTUÁLNÍ CENA CELKEM</small><strong>{formatMoney(unit.price)}</strong><em>včetně DPH</em></span>{onEditPrice&&<button className="secondary-button compact" onClick={onEditPrice}><CreditCard size={16} /> Upravit cenu</button>}</div>
          {priceProposals.map(proposal=><div className="price-proposal" key={proposal.id}><span><Badge tone="warning">Čeká na schválení</Badge><strong>{formatMoney(proposal.proposedAmount)}</strong><small>{proposal.reason} · navrhl/a {proposal.proposer} · účinnost {new Date(proposal.validFrom).toLocaleDateString("cs-CZ")}</small></span>{onDecidePrice&&<div><button className="secondary-button compact danger-text" onClick={()=>void onDecidePrice(proposal.id,"rejected")}>Zamítnout</button><button className="primary-button compact" onClick={()=>void onDecidePrice(proposal.id,"approved")}><Check size={15}/> Schválit</button></div>}</div>)}
          <div className="price-breakdown"><span><i className="price-dot apartment" /><span><strong>Cena jednotky</strong><small>{unit.layout} · {unit.area.toLocaleString("cs-CZ")} m²</small></span><b>{formatMoney(unit.basePrice??unit.price)}</b></span><span><i className="price-dot storage" /><span><strong>Příslušenství</strong><small>{accessoryItems.length?accessoryItems.map(item=>`${item.type} ${item.code}`).join(", "):"Bez placeného příslušenství"}</small></span><b>{formatMoney(unit.accessoryPrice??0)}</b></span><span className="price-breakdown-total"><i className="price-dot total"/><span><strong>Celková cena</strong><small>Aktuální obchodní cenový základ</small></span><b>{formatMoney(unit.price)}</b></span></div>
        </section>
        <section className="card interest-history-card">
          <SectionTitle title="Historie zájmu" />
          <p className="section-description">Záznam zůstává uložený i po ukončení zájmu nebo opětovném uvolnění jednotky.</p>
          <div className="unit-table-wrap"><table className="data-table"><thead><tr><th>Datum</th><th>Zájemce</th><th>Typ / stupeň zájmu</th><th>Výsledek</th></tr></thead><tbody>{interestRows.map((interest)=>{const result=salesHistoryLabel(interest.result);return <tr key={`${interest.partyId}-${interest.date}`}><td>{interest.date}</td><td><strong>{interest.name}</strong></td><td>{salesHistoryLabel(interest.type)}</td><td><Badge tone={result.includes("Aktivní")?"success":"neutral"}>{result}</Badge></td></tr>})}</tbody></table></div>
        </section>
        <section className="card recent-card">
          <SectionTitle title="Poslední aktivita" action="Celá historie" onAction={() => openTab("history")} />
          <div className="timeline-mini">{timeline.slice(0,4).map((item) => <div key={item.id}><span className={`timeline-icon ${item.icon}`}>{item.icon === "contract" ? <FileText size={16} /> : item.icon === "payment" ? <Banknote size={16} /> : item.icon === "build" ? <HardHat size={16} /> : <History size={16} />}</span><span><strong>{item.title}</strong><small>{item.detail}</small></span><time>{formatPragueDateTime(item.date)}</time></div>)}</div>
        </section>
      </div>
      <aside className="unit-side-column">
        {unit.floorplanAvailable===false&&!floorplanUrl?<section className="card floorplan-card"><SectionTitle title="Půdorys" action={onEditFloorplan?"Nahrát půdorys":undefined} onAction={onEditFloorplan}/><div className="empty-filter-state"><FileText size={22}/><strong>Půdorys není nahraný</strong><small>Nahrajte obrázek nebo PDF půdorysu jednotky.</small></div></section>:<section className="card floorplan-card"><div className="section-title"><h2>Půdorys</h2><span className="floorplan-actions">{onEditFloorplan&&<button className="text-button" onClick={onEditFloorplan}><ImagePlus size={15}/> Změnit</button>}<button className="ghost-icon" onClick={() => setFloorplanOpen(true)} aria-label={floorplanIsPdf?"Otevřít PDF":"Otevřít velký půdorys"}><ExternalLink size={17} /></button></span></div>{floorplanIsPdf&&floorplanUrl?<div className="floorplan-pdf-preview"><iframe src={`${floorplanUrl}#page=1&toolbar=0&navpanes=0`} title={`Náhled PDF půdorysu jednotky ${unit.id}`}/><button onClick={()=>setFloorplanOpen(true)} aria-label="Otevřít PDF půdorysu"><span><FileText size={22}/><strong>{floorplanMedia?.fileName||"Půdorys.pdf"}</strong><small>PDF · otevřít náhled</small></span></button></div>:<button className="floorplan-preview-button" onClick={() => setFloorplanOpen(true)} aria-label="Zvětšit půdorys">{floorplanUrl?<img className="floorplan-image" src={floorplanUrl} alt={`Půdorys jednotky ${unit.id}`}/>:<div className="large-floorplan"><div className="room living"><span>OBÝVACÍ POKOJ + KK<small>32,1 m²</small></span></div><div className="room bed"><span>LOŽNICE<small>14,8 m²</small></span></div><div className="room bath"><span>KOUPELNA<small>5,4 m²</small></span></div><div className="room hall"><span>CHODBA<small>8,3 m²</small></span></div><div className="room bed2"><span>POKOJ<small>12,4 m²</small></span></div><div className="room wc"><span>WC</span></div><div className="balcony">LODŽIE · 8,2 m²</div></div>}<span className="enlarge-hint"><Eye size={15} /> Otevřít větší náhled</span></button>}{floorplanMedia?.uploadedAt&&<p className="floorplan-meta">Nahráno {formatPragueDateTime(floorplanMedia.uploadedAt)}{floorplanMedia.uploadedBy?` · ${floorplanMedia.uploadedBy}`:""}</p>}{floorplanDownloadUrl?<a className="secondary-button full" href={floorplanDownloadUrl} download={floorplanMedia?.fileName||undefined}><Download size={16} /> Stáhnout půdorys</a>:<button className="secondary-button full" onClick={() => notify("Půdorys zatím není k dispozici ke stažení")}><Download size={16} /> Stáhnout půdorys</button>}</section>}
        <section className="card parameters-card"><SectionTitle title="Základní parametry" /><dl><div><dt>Dispozice</dt><dd>{unit.layout}</dd></div><div><dt>Podlahová plocha</dt><dd>{unit.area.toLocaleString("cs-CZ")} m²</dd></div>{unit.usableArea&&<div><dt>Užitná plocha</dt><dd>{unit.usableArea.toLocaleString("cs-CZ")} m²</dd></div>}<div><dt>Podlaží</dt><dd>{unit.floor}</dd></div>{unit.balcony!=null&&<div><dt>Balkon</dt><dd>{unit.balcony.toLocaleString("cs-CZ")} m²</dd></div>}{unit.terrace!=null&&<div><dt>Terasa</dt><dd>{unit.terrace.toLocaleString("cs-CZ")} m²</dd></div>}{unit.garden!=null&&<div><dt>Zahrada</dt><dd>{unit.garden.toLocaleString("cs-CZ")} m²</dd></div>}{!isDejvice&&<><div><dt>Orientace</dt><dd>{unit.orientation}</dd></div><div><dt>Standard</dt><dd>Premium</dd></div><div><dt>Vlastnictví</dt><dd>Osobní</dd></div></>}</dl></section>
      </aside>
    </div>
    {floorplanOpen && <div className="modal-layer"><button className="modal-scrim" onClick={() => setFloorplanOpen(false)} aria-label="Zavřít půdorys" /><div className="modal floorplan-modal"><div className="modal-head"><div><h2>Půdorys jednotky {unit.id}</h2><p>{floorplanMedia?.fileName??`${unit.layout} · ${unit.area.toLocaleString("cs-CZ")} m² · ${unit.floor}`}</p></div><button className="icon-button" onClick={() => setFloorplanOpen(false)}><X size={19} /></button></div><div className={`modal-floorplan ${floorplanIsPdf?"pdf":""}`}>{floorplanIsPdf&&floorplanUrl?<iframe src={`${floorplanUrl}#page=1&toolbar=1&navpanes=0`} title={`PDF půdorysu jednotky ${unit.id}`}/>:<>{floorplanUrl&&<img className="floorplan-image" src={floorplanUrl} alt={`Půdorys jednotky ${unit.id}`}/>}<div className="large-floorplan"><div className="room living"><span>OBÝVACÍ POKOJ + KK<small>32,1 m²</small></span></div><div className="room bed"><span>LOŽNICE<small>14,8 m²</small></span></div><div className="room bath"><span>KOUPELNA<small>5,4 m²</small></span></div><div className="room hall"><span>CHODBA<small>8,3 m²</small></span></div><div className="room bed2"><span>POKOJ<small>12,4 m²</small></span></div><div className="room wc"><span>WC</span></div><div className="balcony">LODŽIE · 8,2 m²</div></div></>}</div>{floorplanDownloadUrl&&<div className="modal-media-actions"><a className="secondary-button" href={floorplanDownloadUrl} download={floorplanMedia?.fileName||undefined}><Download size={16}/> Stáhnout originál</a></div>}</div></div>}
    {priceHistoryOpen && <div className="modal-layer"><button className="modal-scrim" onClick={() => setPriceHistoryOpen(false)} aria-label="Zavřít historii cen" /><div className="modal price-history-modal"><div className="modal-head"><div><h2>Historie ceny · {unit.id}</h2><p>Každá změna je samostatný auditovatelný záznam.</p></div><button className="icon-button" onClick={() => setPriceHistoryOpen(false)}><X size={19} /></button></div><table className="data-table"><thead><tr><th>Platnost od</th><th>Typ ceny</th><th>Cena / sleva</th><th>Důvod</th><th>Autor / schválil</th></tr></thead><tbody>{(unitPriceHistories[unit.id]??[]).map(row=><tr key={row.id}><td>{new Date(row.validFrom).toLocaleDateString("cs-CZ")}</td><td><Badge tone="neutral">{({list_price:"Ceníková",individual_discount:"Individuální sleva",sale_price:"Prodejní",contract_price:"Smluvní"} as Record<string,string>)[row.type]??row.type}</Badge></td><td><strong>{formatMoney(row.amount)}</strong></td><td>{row.reason}</td><td>{row.author}{row.approver?` · ${row.approver}`:""}</td></tr>)}</tbody></table></div></div>}
    </>
  );
}

function UnitContracts({ unit,openContract,onNewContract,onWorkflow,onChangeBuyer }: { unit:UnitRecord;openContract:(contract:(typeof contracts)[number])=>void;onNewContract?:()=>void;onWorkflow?: (contract:(typeof contracts)[number])=>void;onChangeBuyer?:()=>void }) {
  const rows=contracts.filter(contract=>contract.unit===unit.id);
  const baseRows=rows.filter(row=>!row.parentContractId);
  const orderedRows=baseRows.flatMap(parent=>[parent,...rows.filter(row=>row.parentContractId===parent.id)]);
  const signedCore=rows.filter(row=>["rs","sbk"].includes(row.typeCode??"")&&normalizeContractStatus(row.statusCode??row.state)==="signed");
  const hasSignedKs=rows.some(row=>row.typeCode==="ks"&&normalizeContractStatus(row.statusCode??row.state)==="signed");
  const hasOpenAssignment=rows.some(row=>["assignment_rs","assignment_sbk"].includes(row.typeCode??"")&&!['signed','cancelled','terminated'].includes(normalizeContractStatus(row.statusCode??row.state)));
  const canAssign=Boolean(onChangeBuyer)&&signedCore.length>0&&!hasSignedKs&&!hasOpenAssignment;
  return <section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Smlouvy jednotky {unit.id}</h2><p>Právní dokumenty a jejich návaznosti v jednom obchodním případu.</p></div><div className="tab-card-actions">{canAssign&&<button className="secondary-button" onClick={onChangeBuyer}><UserRound size={16}/> Postoupit smlouvu</button>}{onNewContract&&<button className="primary-button" onClick={onNewContract}><Plus size={17} /> Nová smlouva</button>}</div></div><div className="document-list contract-legal-chain">{orderedRows.map(row=>{const latest=row.versions?.[0];const canChange=availableContractTransitions(row.statusCode??row.state).length>0;const isAssignment=["assignment_rs","assignment_sbk"].includes(row.typeCode??"");const assignors=(row.parties??[]).filter(party=>party.role==="assignor").map(party=>party.name);const assignees=(row.parties??[]).filter(party=>party.role==="assignee").map(party=>party.name);return <article className={isAssignment?"assignment-document":""} key={row.id??`${row.unit}-${row.type}`}><span className="document-icon">{isAssignment?<GitBranch size={21}/>:<FileText size={21} />}</span><button className="document-link-copy" onClick={()=>openContract(row)}><strong>{row.title??row.type}</strong><small>{row.reference?`${row.reference} · `:""}{latest?`verze v${String(latest.number).padStart(2,"0")} · ${latest.name}`:"Bez verze"}</small>{isAssignment&&<small className="legal-chain-copy">Navazuje na {row.parentReference??"původní smlouvu"} · {assignors.join(" a ")||"původní kupující"} → {assignees.join(" a ")||"nový kupující"}</small>}</button><Badge>{displayedContractStatus(row)}</Badge>{onWorkflow&&row.id&&canChange?<button className="secondary-button compact" onClick={()=>onWorkflow(row)}>Změnit stav <ChevronRight size={15}/></button>:<button className="secondary-button compact" onClick={()=>openContract(row)}>Otevřít smlouvu</button>}</article>})}{!rows.length&&<div className="empty-filter-state"><FileText size={22}/><strong>Jednotka zatím nemá smlouvu</strong><small>Nová smlouva bude navázána na existující obchodní proces.</small></div>}</div><div className="sharepoint-banner"><FolderOpen size={21}/><span><strong>Repository je připravené pro budoucí dokumenty</strong><small>DOCX ani SharePoint synchronizace v této etapě nejsou aktivní.</small></span></div></section>;
}

function UnitPayments({unit,canRecord,onChanged}:{unit:UnitRecord;canRecord:boolean;onChanged?:()=>void}) {
  const unitId=backendEntityId(unit.backendId);return <PaymentContextTable title={`Splátkový kalendář jednotky ${unit.id}`} description="Předpisy, částečné úhrady a historie používají stejný zdroj jako globální Platby." filters={unitId?{unitId}:{unit:unit.id}} canRecord={canRecord} onChanged={onChanged}/>;
}

function PaymentContextTable({title,description,filters,openUnit,project,canRecord=false,onChanged}:{title:string;description:string;filters:{project?:string;unit?:string;unitId?:string;partyId?:string;contractId?:string;salesCaseId?:string};openUnit?:(unit:UnitRecord)=>void;project?:ProjectRecord;canRecord?:boolean;onChanged?:()=>void}){
  const [rows,setRows]=useState<PaymentRecord[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [selected,setSelected]=useState<PaymentRecord|null>(null);const [reload,setReload]=useState(0);
  useEffect(()=>{const controller=new AbortController();paymentRepository.list(filters,controller.signal).then(result=>{setRows(result.payments);setError("");}).catch(err=>{if((err as Error).name!=="AbortError")setError(err instanceof Error?err.message:"Platby nelze načíst");}).finally(()=>setLoading(false));return()=>controller.abort();},[filters.project,filters.unit,filters.unitId,filters.partyId,filters.contractId,filters.salesCaseId,reload]);
  const total=rows.reduce((sum,row)=>sum+row.amount,0);const paid=rows.reduce((sum,row)=>sum+row.paid,0);
  const content=<><div className="metric-row payments-metrics"><div className="metric-card"><span className="metric-icon green"><Banknote size={20}/></span><span><small>Uhrazeno</small><strong>{formatMoney(paid)}</strong><em>nereverzované úhrady</em></span></div><div className="metric-card"><span className="metric-icon blue"><CircleDollarSign size={20}/></span><span><small>Předepsáno</small><strong>{formatMoney(total)}</strong><em>{rows.length} předpisů</em></span></div><div className="metric-card danger-metric"><span className="metric-icon red"><AlertTriangle size={20}/></span><span><small>Po splatnosti</small><strong>{rows.filter(row=>row.status==="overdue").length}</strong><em>vyžaduje pozornost</em></span></div></div><section className="card detail-tab-card">{!project&&<div className="tab-card-header"><div><h2>{title}</h2><p>{description}</p></div></div>}<div className="unit-table-wrap"><table className="data-table"><thead><tr><th>Jednotka</th><th>Klient</th><th>Splátka</th><th>Splatnost</th><th>Předpis</th><th>Uhrazeno</th><th>Stav</th><th/></tr></thead><tbody>{rows.map(row=><tr key={row.id} onClick={()=>setSelected(row)}><td><strong>{row.unit}</strong></td><td>{row.client}</td><td>{row.label}</td><td>{formatPragueDate(row.dueAt)}</td><td><strong>{formatMoney(row.amount)}</strong></td><td>{formatMoney(row.paid)}</td><td><Badge tone={row.status==="overdue"?"danger":row.status==="paid"?"success":"neutral"}>{paymentStatusLabel[row.status]}</Badge></td><td><ChevronRight size={17}/></td></tr>)}</tbody></table></div>{loading&&<div className="empty-filter-state"><Clock3 size={20}/><strong>Načítám platby…</strong></div>}{error&&<div className="empty-filter-state"><AlertTriangle size={20}/><strong>Platby nelze načíst</strong><small>{error}</small></div>}{!loading&&!error&&!rows.length&&<div className="empty-filter-state"><Banknote size={20}/><strong>Bez platebních předpisů</strong><small>V tomto kontextu zatím není žádná platební povinnost.</small></div>}</section>{selected&&<PaymentDetailModal payment={selected} close={()=>setSelected(null)} openUnit={()=>{const unit=units.find(item=>item.id===selected.unit);if(unit&&openUnit)openUnit(unit);}} canRecord={canRecord} canReverse={false} saved={()=>{setSelected(null);setReload(value=>value+1);onChanged?.();}}/>}</>;
  return <div className={project?"project-module-stack":"detail-tab-stack"}>{content}</div>;
}

const clientChangeStatusLabels:Record<string,string>={requested:"Požadováno",pricing:"K nacenění",pending_approval:"Ke schválení",approved:"Schváleno",in_progress:"V realizaci",completed:"Dokončeno",cancelled:"Zrušeno"};
const clientChangeStatusTones:Record<string,string>={requested:"neutral",pricing:"warning",pending_approval:"warning",approved:"success",in_progress:"blue",completed:"success",cancelled:"danger"};

function ClientChangesWorkspace({project,unit,openUnit,notify}:{project:ProjectRecord;unit?:UnitRecord;openUnit:(unit:UnitRecord)=>void;notify:(message:string)=>void}){
  const [rows,setRows]=useState<ClientChangeRecord[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [creating,setCreating]=useState(false);const [archiveTarget,setArchiveTarget]=useState<ClientChangeRecord|null>(null);const [reload,setReload]=useState(0);
  const projectId=backendEntityId(project.backendId);const unitId=unit?backendEntityId(unit.backendId):null;const projectUnits=units.filter(item=>unitBelongsToProject(item,project));
  useEffect(()=>{const controller=new AbortController();if(!projectId||(unit&&!unitId)){Promise.resolve().then(()=>{setRows([]);setLoading(false);setError("Klientské změny vyžadují skutečné ID projektu a jednotky.");});return()=>controller.abort();}clientChangeRepository.list({projectId,unitId:unitId??undefined},controller.signal).then(value=>{setRows(value);setError("");}).catch(problem=>{if((problem as Error).name!=="AbortError")setError(problem instanceof Error?problem.message:"Klientské změny nelze načíst");}).finally(()=>setLoading(false));return()=>controller.abort();},[projectId,unitId,reload,unit]);
  const total=rows.reduce((sum,row)=>sum+(row.surchargeAmount??0),0);
  const table=<><div className="unit-table-wrap"><table className="data-table unit-changes-table"><thead><tr><th>Změna</th>{!unit&&<th>Jednotka</th>}<th>Klient</th><th>Kategorie</th><th>Stav</th><th>Cena / doplatek</th><th>Termín</th><th>Datum požadavku</th><th/></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td><strong>{row.title}</strong><small className="change-source">{row.sourceType==="catalog"?`Ceník · ${row.catalogItemCode}`:"Individuální změna"}</small></td>{!unit&&<td><button className="unit-link" onClick={()=>{const target=projectUnits.find(item=>item.backendId===row.unitId);if(target)openUnit(target);}}>{row.unitCode}</button></td>}<td>{row.partyName}</td><td>{row.category}</td><td><Badge tone={clientChangeStatusTones[row.status]??"neutral"}>{clientChangeStatusLabels[row.status]??row.status}</Badge></td><td><strong>{row.surchargeAmount===null?"K nacenění":formatMoney(row.surchargeAmount)}</strong></td><td>{row.dueAt?formatPragueDate(row.dueAt):"—"}</td><td>{formatPragueDate(row.requestedAt)}</td><td><button className="ghost-icon" aria-label={`Archivovat ${row.title}`} onClick={()=>setArchiveTarget(row)}><X size={16}/></button></td></tr>)}</tbody></table></div>{loading&&<div className="empty-filter-state"><Clock3 size={20}/><strong>Načítám klientské změny…</strong></div>}{error&&<div className="empty-filter-state"><AlertTriangle size={20}/><strong>Klientské změny nelze načíst</strong><small>{error}</small></div>}{!loading&&!error&&!rows.length&&<div className="empty-filter-state"><SlidersHorizontal size={22}/><strong>Zatím bez klientských změn</strong><small>Nový požadavek bude bezpečně provázán s jednotkou a klientem.</small></div>}</>;
  const content=unit?<div className="detail-tab-stack"><section className="card unit-change-context"><div className="change-context-copy"><span className="change-context-icon"><Link2 size={19}/></span><span><strong>Provázané údaje bez duplikace</strong><small>Jednotka, klient a aktivní obchodní případ zůstávají canonical zdrojem dat.</small></span></div><div className="change-context-grid"><span><small>JEDNOTKA</small><strong>{unit.id}</strong><em>{unit.project}</em></span><span><small>KLIENT</small><strong>{unit.client||"Bez přiřazeného klienta"}</strong><em>z karty klienta</em></span><span><small>DOPLATKY CELKEM</small><strong>{formatMoney(total)}</strong><em>{rows.length} změn</em></span><span><small>DOKUMENTY</small><strong>Vazby bez kopií</strong><em>v dokumentech jednotky</em></span></div></section><section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Klientské změny jednotky {unit.id}</h2><p>Individuální požadavky i položky z budoucího ceníku.</p></div><button className="primary-button" onClick={()=>setCreating(true)}><Plus size={17}/> Nová změna</button></div>{table}</section></div>:<ProjectModuleFrame label="Klientské změny" action="Nový požadavek" onAction={()=>setCreating(true)}>{table}</ProjectModuleFrame>;
  return <>{content}{creating&&<NewClientChangeModal project={project} fixedUnit={unit} close={()=>setCreating(false)} save={async input=>{await clientChangeRepository.create(input);setCreating(false);setReload(value=>value+1);notify("Klientská změna byla vytvořena");}}/>}{archiveTarget&&<FormModal title="Archivovat klientskou změnu" close={()=>setArchiveTarget(null)} saveLabel="Archivovat" onSave={async()=>{await clientChangeRepository.archive(archiveTarget.id,"Archivováno uživatelem z přehledu");setArchiveTarget(null);setReload(value=>value+1);notify("Klientská změna byla archivována");}}><p className="form-help"><AlertTriangle size={16}/> Opravdu chcete archivovat změnu „{archiveTarget.title}“? Záznam zůstane zachovaný v auditní historii.</p></FormModal>}</>;
}

function NewClientChangeModal({project,fixedUnit,close,save}:{project:ProjectRecord;fixedUnit?:UnitRecord;close:()=>void;save:(input:NewClientChangeInput)=>Promise<void>}){
  const projectUnits=units.filter(item=>unitBelongsToProject(item,project));const [unitKey,setUnitKey]=useState(fixedUnit?.id??projectUnits.find(item=>unitCommercialContexts[item.id]?.buyers.length)?.id??projectUnits[0]?.id??"");const selectedUnit=projectUnits.find(item=>item.id===unitKey);const buyerIds=new Set((unitCommercialContexts[unitKey]?.buyers??[]).map(item=>item.partyId));const candidates=clients.filter(client=>buyerIds.has(client.id)||client.units.includes(unitKey));
  const [partyId,setPartyId]=useState("");const [title,setTitle]=useState("");const [description,setDescription]=useState("");const [sourceType,setSourceType]=useState<"individual"|"catalog">("individual");const [catalogItemCode,setCatalogItemCode]=useState("");const [category,setCategory]=useState("");const [surcharge,setSurcharge]=useState("");const [requestedAt,setRequestedAt]=useState(localDateKey(new Date()));const [dueAt,setDueAt]=useState("");const effectivePartyId=candidates.some(item=>item.id===partyId)?partyId:candidates[0]?.id??"";
  return <FormModal title="Nová klientská změna" close={close} saveLabel="Vytvořit změnu" onSave={async()=>{const projectId=backendEntityId(project.backendId);const unitId=backendEntityId(selectedUnit?.backendId);if(!projectId||!unitId)throw new Error("Projekt nebo jednotka nemá skutečný databázový identifikátor");if(!effectivePartyId)throw new Error("Vybraná jednotka nemá přiřazeného klienta");if(title.trim().length<2||category.trim().length<2)throw new Error("Doplňte název a kategorii změny");if(sourceType==="catalog"&&!catalogItemCode.trim())throw new Error("Doplňte kód položky ceníku");await save({projectId,unitId,partyId:effectivePartyId,title:title.trim(),description:description.trim(),sourceType,catalogItemCode:catalogItemCode.trim()||undefined,category:category.trim(),surchargeAmount:surcharge?numberValue(surcharge):null,currency:"CZK",requestedAt,dueAt:dueAt||null});}}><label><span>Jednotka</span><select value={unitKey} disabled={Boolean(fixedUnit)} onChange={event=>{setUnitKey(event.target.value);setPartyId("");}}>{projectUnits.map(item=><option key={item.id} value={item.id}>{item.id} · {item.layout} · {item.status}</option>)}</select></label><label><span>Klient</span><select value={effectivePartyId} onChange={event=>setPartyId(event.target.value)}><option value="">Vyberte klienta</option>{candidates.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select>{!candidates.length&&<small>Nejdříve přiřaďte klienta k obchodnímu případu jednotky.</small>}</label><label><span>Název / popis změny</span><input autoFocus value={title} onChange={event=>setTitle(event.target.value)} placeholder="Např. změna podlahy"/></label><div className="form-row"><label><span>Kategorie</span><input value={category} onChange={event=>setCategory(event.target.value)} placeholder="Povrchy, elektro…"/></label><label><span>Zdroj</span><select value={sourceType} onChange={event=>setSourceType(event.target.value as "individual"|"catalog")}><option value="individual">Individuální změna</option><option value="catalog">Položka z ceníku</option></select></label></div>{sourceType==="catalog"&&<label><span>Kód položky ceníku</span><input value={catalogItemCode} onChange={event=>setCatalogItemCode(event.target.value)}/></label>}<div className="form-row"><label><span>Cena / doplatek</span><input inputMode="decimal" value={surcharge} onChange={event=>setSurcharge(event.target.value)} placeholder="K nacenění"/></label><label><span>Datum požadavku</span><input type="date" value={requestedAt} onChange={event=>setRequestedAt(event.target.value)}/></label></div><label><span>Termín</span><input type="date" value={dueAt} onChange={event=>setDueAt(event.target.value)}/></label><label><span>Poznámka</span><textarea rows={3} value={description} onChange={event=>setDescription(event.target.value)}/></label></FormModal>;
}

function UnitClientChanges({unit,notify}:{unit:UnitRecord;notify:(message:string)=>void}){const project=projects.find(item=>unitBelongsToProject(unit,item));if(!project)return <PilotEmptyState title="Klientské změny" detail="Projekt jednotky se nepodařilo určit."/>;return <ClientChangesWorkspace project={project} unit={unit} openUnit={()=>undefined} notify={notify}/>;}

function LegacyUnitClientChanges({ unit, notify }: { unit: UnitRecord; notify: (message: string) => void }) {
  if(isDejviceUnit(unit))return <PilotEmptyState title="Klientské změny" detail="Pilotní zdroj neobsahuje klientské změny."/>;
  const changes = [
    { name: "Změna podlahy v obytných místnostech", category: "Povrchy", source: "Individuální změna", state: "Ke schválení", tone: "warning", price: null, deadline: "24. 7. 2026", requested: "11. 7. 2026", documents: ["Specifikace_podlahy.pdf", "Nabídka_dodavatele.xlsx"] },
    { name: "Doplnění elektro vývodů", category: "Elektro", source: "Ceník standardních změn", state: "Schváleno", tone: "success", price: 18500, deadline: "29. 7. 2026", requested: "4. 7. 2026", documents: ["Objednávka_KZ-0142.pdf", "Výkres_elektro_rev02.pdf"] },
    { name: "Příprava pro venkovní žaluzie", category: "Stínění", source: "Ceník standardních změn", state: "V realizaci", tone: "blue", price: 42000, deadline: "15. 8. 2026", requested: "28. 6. 2026", documents: ["Potvrzení_KZ-0138.pdf"] },
  ];
  const totalSurcharge = changes.reduce((sum, change) => sum + (change.price || 0), 0);
  const documentCount = changes.reduce((sum, change) => sum + change.documents.length, 0);

  return (
    <div className="detail-tab-stack">
      <section className="card unit-change-context">
        <div className="change-context-copy">
          <span className="change-context-icon"><Link2 size={19} /></span>
          <span><strong>Provázané údaje bez duplikace</strong><small>Změny používají existující vazby na jednotku, klienta, platební předpisy a dokumenty.</small></span>
        </div>
        <div className="change-context-grid">
          <span><small>JEDNOTKA</small><strong>{unit.id}</strong><em>{unit.project}</em></span>
          <span><small>KLIENT</small><strong>{unit.client || "Bez přiřazeného klienta"}</strong><em>z karty klienta</em></span>
          <span><small>DOPLATKY CELKEM</small><strong>{formatMoney(totalSurcharge)}</strong><em>navázáno na platby</em></span>
          <span><small>DOKUMENTY</small><strong>{documentCount} souborů</strong><em>v dokumentech jednotky</em></span>
        </div>
      </section>
      <section className="card detail-tab-card">
        <div className="tab-card-header"><div><h2>Klientské změny jednotky {unit.id}</h2><p>Individuální požadavky i položky z ceníku standardních klientských změn.</p></div><button className="primary-button" onClick={() => notify(`Nová klientská změna pro ${unit.id}`)}><Plus size={17} /> Nová změna</button></div>
        <div className="unit-table-wrap"><table className="data-table unit-changes-table"><thead><tr><th>Změna</th><th>Kategorie</th><th>Stav</th><th>Cena / doplatek</th><th>Termín</th><th>Datum požadavku</th><th>Související dokumenty</th><th /></tr></thead><tbody>{changes.map((change) => <tr key={change.name} className="clickable-row" onClick={() => notify(`Otevírám detail změny: ${change.name}`)}><td><strong>{change.name}</strong><small className="change-source">{change.source}</small></td><td>{change.category}</td><td><Badge tone={change.tone}>{change.state}</Badge></td><td><strong>{change.price ? formatMoney(change.price) : "K nacenění"}</strong></td><td>{change.deadline}</td><td>{change.requested}</td><td><span className="change-documents">{change.documents.map((document) => <button key={document} onClick={(event) => { event.stopPropagation(); notify(`Otevírám ${document}`); }}><FileText size={14} /> {document}</button>)}</span></td><td><ChevronRight size={17} /></td></tr>)}</tbody></table></div>
      </section>
    </div>
  );
}

function UnitDocuments({ unit,notify }: { unit:UnitRecord;notify: (message: string) => void }) {
  const [documents,setDocuments]=useState<DocumentRecord[]>([]);const [connection,setConnection]=useState<DocumentConnectionState>(previewConnection);const [loading,setLoading]=useState(true);const [category,setCategory]=useState("");
  useEffect(()=>{const controller=new AbortController();documentRepository.listUnit(unit.backendId??unit.id,{category:category||undefined},controller.signal).then(result=>{setDocuments(result.documents);setConnection(result.connection);}).catch(()=>{setDocuments([]);setConnection(previewConnection);}).finally(()=>setLoading(false));return()=>controller.abort();},[unit.backendId,unit.id,category]);
  return <section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Dokumenty jednotky {unit.id}</h2><p>Jeden přehled metadat, vazeb a fyzických verzí souborů.</p></div></div><DocumentConnectionBanner connection={connection}/><div className="module-toolbar document-toolbar"><div className="inline-search"><Search size={17}/><span>{loading?"Načítám dokumenty…":`${documents.length} dokumentů`}</span></div><label><span>Kategorie</span><select value={category} onChange={event=>{setLoading(true);setCategory(event.target.value);}}><option value="">Všechny kategorie</option>{documentCategoryOptions.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label></div><DocumentList documents={documents} loading={loading} notify={notify}/></section>;
}

const documentCategoryOptions=[
  {value:"contract",label:"Smlouva"},{value:"floor_plan",label:"Půdorys"},{value:"project_documentation",label:"Projektová dokumentace"},
  {value:"client_document",label:"Klientský dokument"},{value:"price_document",label:"Cenový dokument"},{value:"reservation",label:"Rezervace"},{value:"other",label:"Ostatní"},
];
function DocumentConnectionBanner({connection}:{connection:DocumentConnectionState}){if(connection.status==="connected")return <div className="sharepoint-banner"><CheckCircle2 size={19}/><span><strong>SharePoint je připojen</strong><small>{connection.lastSuccessfulSyncAt?`Poslední úspěšná synchronizace ${new Date(connection.lastSuccessfulSyncAt).toLocaleString("cs-CZ")}`:"Připojení je připravené k synchronizaci."}</small></span></div>;return <div className="unassigned-doc document-connection-note"><AlertTriangle size={19}/><span><strong>SharePoint zatím není připojen</strong><small>Preview bezpečně zobrazuje pouze CRM metadata a existující preview média. Žádný soubor se nevydává za nahraný na SharePoint.</small></span></div>;}
function DocumentList({documents,loading,notify:_notify,openDocument}:{documents:DocumentRecord[];loading:boolean;notify:(message:string)=>void;openDocument?:(document:DocumentRecord)=>void}){if(loading)return <div className="empty-filter-state"><Clock3 size={21}/><strong>Načítám dokumenty</strong></div>;if(!documents.length)return <div className="empty-filter-state"><FolderOpen size={22}/><strong>Žádné dokumenty v tomto rozsahu</strong><small>Zdroj zatím neobsahuje odpovídající dokumentová metadata.</small></div>;return <div className="document-list document-metadata-list">{documents.map(document=>{const related=[...document.units,...document.parties,...document.contracts];return <article key={document.id} className="clickable-document" onClick={()=>openDocument?.(document)}><span className="document-icon"><FileText size={21}/></span><span><strong>{document.name}</strong><small>{document.typeName} · {related.length?related.join(" · "):document.projectName}</small></span><span className="document-meta"><small>Poslední změna</small><strong>{document.updatedAt?new Date(document.updatedAt).toLocaleDateString("cs-CZ"):"—"}</strong></span><span className="document-meta"><small>Autor</small><strong>{document.author??"—"}</strong></span><Badge tone={documentStatusTone(document.status)}>{documentStatusLabel(document.status)}</Badge>{openDocument?<button className="ghost-icon" onClick={event=>{event.stopPropagation();openDocument(document);}} aria-label={`Detail ${document.name}`}><ChevronRight size={18}/></button>:document.webUrl?<Link className="ghost-icon" href={document.webUrl} target="_blank" rel="noreferrer" aria-label={`Otevřít ${document.name}`}><ExternalLink size={18}/></Link>:<Link className="ghost-icon" href={documentRoute(document.id)} aria-label={`Detail ${document.name}`}><ChevronRight size={18}/></Link>}</article>;})}</div>;}

const documentStatusOptions:{code:DocumentStatus;label:string}[]=[{code:"draft",label:"Koncept"},{code:"ready",label:"Připraveno"},{code:"sent",label:"Odesláno"},{code:"negotiation",label:"Ve vyjednávání"},{code:"signed",label:"Podepsáno"},{code:"archived",label:"Archiv"}];
function documentStatusLabel(value:string){return documentStatusOptions.find(option=>option.code===value)?.label??value;}
function documentStatusTone(value:string){return value==="signed"?"success":value==="negotiation"?"purple":value==="sent"?"warning":value==="ready"?"blue":"neutral";}
function documentDate(value:string|null|undefined){return value?formatPragueDate(value):"—";}

function DocumentsPage({selectedDocumentId,openDocument,closeDocument,openUnit,openClient,openContract,notify,reloadKey,onEdit,onNewVersion}:{selectedDocumentId:string|null;openDocument:(document:DocumentRecord)=>void;closeDocument:()=>void;openUnit:(unit:UnitRecord)=>void;openClient:(identity:string)=>void;openContract:(contract:(typeof contracts)[number])=>void;notify:(message:string)=>void;reloadKey:number;onEdit?:(document:DocumentRecord)=>void;onNewVersion?:(document:DocumentRecord)=>void}){
  const columnState=useTableColumns("documents-table",documentTableColumns);
  const router=useRouter();const pathname=usePathname();const params=useSearchParams();const [documents,setDocuments]=useState<DocumentRecord[]>([]);const [loading,setLoading]=useState(true);const query=params.get("q")??"";const contextQuery=params.get("dcontext")??"";const typeFilters=listParam(params,"dtype");const statusFilters=listParam(params,"dstatus");const projectFilters=listParam(params,"dproject");const sort=params.get("dsort")??"updated";const direction=(params.get("ddir")==="asc"?"asc":"desc") as SortDirection;
  useEffect(()=>{if(selectedDocumentId)return;const controller=new AbortController();documentRepository.listAll({},controller.signal).then(result=>setDocuments(result.documents)).catch(()=>setDocuments([])).finally(()=>setLoading(false));return()=>controller.abort();},[reloadKey,selectedDocumentId]);
  if(selectedDocumentId)return <DocumentDetail documentId={selectedDocumentId} close={closeDocument} openUnit={openUnit} openClient={openClient} openContract={openContract} reloadKey={reloadKey} onEdit={onEdit} onNewVersion={onNewVersion}/>;
  const change=(patch:Record<string,string|string[]>)=>router.replace(updateSearch(pathname,params.toString(),patch),{scroll:false});
  const filteredDocuments=documents.filter(document=>(!query||document.name.toLocaleLowerCase("cs-CZ").includes(query.toLocaleLowerCase("cs-CZ")))&&(!contextQuery||[document.projectName,...document.units,...document.parties].join(" ").toLocaleLowerCase("cs-CZ").includes(contextQuery.toLocaleLowerCase("cs-CZ")))&&(!typeFilters.length||typeFilters.includes(document.typeName))&&(!statusFilters.length||statusFilters.includes(documentStatusLabel(document.status)))&&(!projectFilters.length||projectFilters.includes(document.projectName)));
  const sortedDocuments=stableSort(filteredDocuments,document=>sort==="created"?document.createdAt:sort==="type"?document.typeName:sort==="status"?documentStatusOptions.findIndex(item=>item.code===document.status):sort==="name"?document.name:sort==="project"?document.projectName:sort==="context"?[...document.parties,...document.units].join(" "):document.updatedAt,direction,document=>document.id);
  const signed=documents.filter(document=>document.status==="signed").length;const action=documents.filter(document=>["draft","negotiation"].includes(document.status)).length;
  const documentGridTemplate=["minmax(230px,1.8fr)",columnState.isVisible("type")&&"minmax(145px,.9fr)",columnState.isVisible("project")&&"minmax(150px,1fr)",columnState.isVisible("context")&&"minmax(190px,1.2fr)",columnState.isVisible("status")&&"minmax(140px,.8fr)",columnState.isVisible("version")&&"80px",columnState.isVisible("updated")&&"minmax(135px,.8fr)","32px"].filter(Boolean).join(" ");
  return <div className="module-stack document-workspace">
    <div className="document-summary-strip"><span><FolderOpen size={18}/><small>Všechny dokumenty</small><strong>{documents.length}</strong></span><span><AlertTriangle size={18}/><small>Vyžadují pozornost</small><strong>{action}</strong></span><span><CheckCircle2 size={18}/><small>Podepsané</small><strong>{signed}</strong></span><span><History size={18}/><small>Poslední změna</small><strong>{documents[0]?documentDate(documents[0].updatedAt):"—"}</strong></span></div>
    <section className="card module-card">
      <div className="document-quick-filter"><button className={!statusFilters.length?"active":""} onClick={()=>change({dstatus:""})}>Všechny</button>{documentStatusOptions.filter(item=>item.code!=="archived").map(item=><button key={item.code} className={statusFilters.length===1&&statusFilters[0]===item.label?"active":""} onClick={()=>change({dstatus:item.label})}>{item.label}<span>{documents.filter(document=>document.status===item.code).length}</span></button>)}</div>
      <div className="document-result-bar"><span><strong>{filteredDocuments.length}</strong> dokumentů</span><span className="list-toolbar-actions">{(query||contextQuery||typeFilters.length||statusFilters.length||projectFilters.length)>0&&<button className="text-button" onClick={()=>change({q:"",dcontext:"",dtype:"",dstatus:"",dproject:""})}>Zrušit filtry</button>}<TableColumnMenu columns={documentTableColumns} state={columnState}/></span></div>
      <div className="document-table-head" style={{gridTemplateColumns:documentGridTemplate}}>
        <ListColumnFilter label="Dokument" active={Boolean(query)} sortDirection={sort==="name"?direction:undefined} onSort={next=>change({dsort:"name",ddir:next})}><input value={query} onChange={event=>change({q:event.target.value})} placeholder="Název dokumentu…" aria-label="Filtrovat název dokumentu"/></ListColumnFilter>
        {columnState.isVisible("type")&&<ListColumnFilter label="Typ" active={typeFilters.length>0} sortDirection={sort==="type"?direction:undefined} onSort={next=>change({dsort:"type",ddir:next})}><MultiSelectFilter options={documentTypeOptions.map(option=>option.name)} selected={typeFilters} onChange={values=>change({dtype:values})} allLabel="Všechny typy" ariaLabel="Filtrovat typ dokumentu"/></ListColumnFilter>}
        {columnState.isVisible("project")&&<ListColumnFilter label="Projekt" active={projectFilters.length>0} sortDirection={sort==="project"?direction:undefined} onSort={next=>change({dsort:"project",ddir:next})}><MultiSelectFilter options={projects.map(item=>item.name)} selected={projectFilters} onChange={values=>change({dproject:values})} allLabel="Všechny projekty" ariaLabel="Filtrovat projekt dokumentu"/></ListColumnFilter>}
        {columnState.isVisible("context")&&<ListColumnFilter label="Klient / jednotka" active={Boolean(contextQuery)} sortDirection={sort==="context"?direction:undefined} onSort={next=>change({dsort:"context",ddir:next})}><input value={contextQuery} onChange={event=>change({dcontext:event.target.value})} placeholder="Klient nebo jednotka…" aria-label="Filtrovat klienta nebo jednotku"/></ListColumnFilter>}
        {columnState.isVisible("status")&&<ListColumnFilter label="Aktuální stav" active={statusFilters.length>0} sortDirection={sort==="status"?direction:undefined} onSort={next=>change({dsort:"status",ddir:next})}><MultiSelectFilter options={documentStatusOptions.map(option=>option.label)} selected={statusFilters} onChange={values=>change({dstatus:values})} allLabel="Všechny stavy" ariaLabel="Filtrovat stav dokumentu"/></ListColumnFilter>}
        {columnState.isVisible("version")&&<ListColumnFilter label="Verze"/>}
        {columnState.isVisible("updated")&&<ListColumnFilter label="Poslední změna" sortType="date" sortDirection={sort==="updated"?direction:undefined} onSort={next=>change({dsort:"updated",ddir:next})}/>} 
        <span/>
      </div>
      <div className="document-central-list">{loading?<div className="empty-filter-state"><Clock3 size={21}/><strong>Načítám dokumenty</strong></div>:sortedDocuments.map(document=><button key={document.id} style={{gridTemplateColumns:documentGridTemplate}} onClick={()=>openDocument(document)}><span className="document-name-cell"><i><FileText size={19}/></i><span><strong>{document.name}</strong><small>{document.author??"Bez autora"}</small></span></span>{columnState.isVisible("type")&&<span>{document.typeName}</span>}{columnState.isVisible("project")&&<span><strong>{document.projectName}</strong></span>}{columnState.isVisible("context")&&<span className="document-relations"><strong>{document.parties.slice(0,2).join(" · ")||"—"}</strong><small>{document.units.slice(0,3).join(" · ")||"Bez jednotky"}</small></span>}{columnState.isVisible("status")&&<span><Badge tone={documentStatusTone(document.status)}>{documentStatusLabel(document.status)}</Badge></span>}{columnState.isVisible("version")&&<strong className="document-version-cell">{document.version??"—"}</strong>}{columnState.isVisible("updated")&&<span>{documentDate(document.updatedAt)}</span>}<ChevronRight size={17}/></button>)}</div>
      {!loading&&!filteredDocuments.length&&<div className="empty-filter-state"><Search size={22}/><strong>Žádný dokument neodpovídá filtrům</strong><small>Změňte filtry v hlavičkách sloupců.</small></div>}
    </section>
  </div>;
}

function DocumentDetail({documentId,close,openUnit,openClient,openContract,reloadKey,onEdit,onNewVersion}:{documentId:string;close:()=>void;openUnit:(unit:UnitRecord)=>void;openClient:(identity:string)=>void;openContract:(contract:(typeof contracts)[number])=>void;reloadKey:number;onEdit?:(document:DocumentRecord)=>void;onNewVersion?:(document:DocumentRecord)=>void}){
  const [document,setDocument]=useState<DocumentRecord|null>(null);const [loading,setLoading]=useState(true);const [tab,setTab]=useState<"overview"|"history"|"versions"|"links"|"notes">("overview");
  useEffect(()=>{const controller=new AbortController();documentRepository.get(documentId,controller.signal).then(setDocument).finally(()=>setLoading(false));return()=>controller.abort();},[documentId,reloadKey]);
  if(loading)return <section className="card detail-tab-card"><div className="empty-filter-state"><Clock3 size={22}/><strong>Načítám detail dokumentu</strong></div></section>;
  if(!document)return <section className="card detail-tab-card"><div className="empty-filter-state"><AlertTriangle size={22}/><strong>Dokument nebyl nalezen</strong><button className="secondary-button" onClick={close}>Zpět na dokumenty</button></div></section>;
  const links=[...document.units.map(value=>({kind:"Jednotka",value,icon:Home})),...document.parties.map(value=>({kind:"Klient",value,icon:UserRound})),...document.contracts.map(value=>({kind:"Smlouva",value,icon:FileCheck2})),...document.salesCases.map(value=>({kind:"Obchodní vazba",value,icon:Link2}))];
  const activate=(kind:string,value:string)=>{if(kind==="Jednotka"){const unit=units.find(item=>item.id===value);if(unit)openUnit(unit);}else if(kind==="Klient")openClient(value);else if(kind==="Smlouva"){const contract=contracts.find(item=>item.id===value||item.reference===value||value.includes(item.unit)&&value.includes(item.type));if(contract)openContract(contract);}};
  return <div className="document-detail"><div className="unit-breadcrumb"><button onClick={close}><ArrowLeft size={16}/> Dokumenty</button><ChevronRight size={14}/><strong>{document.name}</strong></div><section className="card document-detail-hero"><span className="document-hero-icon"><FileText size={25}/></span><div><span className="eyebrow">{document.typeName}</span><h1>{document.name}</h1><p>{document.projectName} · {document.version??"bez verze"} · upraveno {documentDate(document.updatedAt)}</p></div><Badge tone={documentStatusTone(document.status)}>{documentStatusLabel(document.status)}</Badge><div className="project-detail-actions">{onNewVersion&&<button className="primary-button" onClick={()=>onNewVersion(document)}><Upload size={16}/> Nová verze</button>}{onEdit&&<button className="secondary-button" onClick={()=>onEdit(document)}><SlidersHorizontal size={16}/> Upravit metadata</button>}</div></section>
    <nav className="unit-tabs unit-detail-tabs document-detail-tabs">{([["overview","Přehled",LayoutDashboard],["history","Historie",History],["versions","Verze",FileText],["links","Vazby",Link2],["notes","Poznámky",MessageSquare]] as const).map(([id,label,Icon])=><button key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}><Icon size={17}/>{label}{id==="versions"&&<span>{document.versions?.length??0}</span>}{id==="links"&&<span>{links.length}</span>}</button>)}</nav>
    {tab==="overview"&&<div className="document-detail-grid"><section className="card document-metadata-card"><SectionTitle title="Metadata dokumentu"/><dl><div><dt>Název</dt><dd>{document.name}</dd></div><div><dt>Typ</dt><dd>{document.typeName}</dd></div><div><dt>Stav</dt><dd><Badge tone={documentStatusTone(document.status)}>{documentStatusLabel(document.status)}</Badge></dd></div><div><dt>Aktuální verze</dt><dd>{document.version??"—"}</dd></div><div><dt>Vytvořeno</dt><dd>{documentDate(document.createdAt)}</dd></div><div><dt>Autor poslední změny</dt><dd>{document.author??"—"}</dd></div></dl>{document.note&&<div className="document-note"><MessageSquare size={16}/><span><small>POZNÁMKA</small><p>{document.note}</p></span></div>}</section><aside className="card document-links-card"><SectionTitle title="Související záznamy"/>{links.slice(0,6).map(({kind,value,icon:Icon})=><button key={`${kind}-${value}`} onClick={()=>activate(kind,value)}><Icon size={17}/><span><small>{kind}</small><strong>{value}</strong></span><ChevronRight size={16}/></button>)}</aside></div>}
    {tab==="history"&&<section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Historie dokumentu</h2><p>Auditovatelná časová osa verzí, stavů a metadat.</p></div></div><div className="document-timeline">{(document.events??[]).map(event=><article key={event.id}><span><History size={15}/></span><div><strong>{event.title}</strong>{event.note&&<p>{event.note}</p>}<small>{documentDate(event.occurredAt)} · {event.actor}{event.versionLabel?` · ${event.versionLabel}`:""}</small></div>{event.newStatus&&<Badge tone={documentStatusTone(event.newStatus)}>{documentStatusLabel(event.newStatus)}</Badge>}</article>)}</div></section>}
    {tab==="versions"&&<section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Fyzické verze</h2><p>Každá verze je samostatný neměnný záznam s vlastním stavem a autorem.</p></div>{onNewVersion&&<button className="primary-button" onClick={()=>onNewVersion(document)}><Plus size={15}/> Nová verze</button>}</div><div className="document-version-list">{(document.versions??[]).map(version=><article key={version.id}><span className="version-badge">{version.label}</span><span><strong>{document.name}</strong><small>{version.note??"Bez poznámky"} · {documentDate(version.createdAt)} · {version.author??"—"}</small></span><Badge tone={documentStatusTone(version.status)}>{documentStatusLabel(version.status)}</Badge></article>)}</div></section>}
    {tab==="links"&&<section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Vazby dokumentu</h2><p>Jeden dokument může být současně propojený s více záznamy bez duplikace.</p></div></div><div className="document-link-grid">{links.map(({kind,value,icon:Icon})=><button key={`${kind}-${value}`} onClick={()=>activate(kind,value)}><Icon size={19}/><span><small>{kind}</small><strong>{value}</strong></span><ChevronRight size={17}/></button>)}</div></section>}
    {tab==="notes"&&<section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Poznámky</h2><p>Interní kontext oddělený od fyzického souboru.</p></div>{onEdit&&<button className="secondary-button" onClick={()=>onEdit(document)}>Upravit poznámku</button>}</div>{document.note?<div className="document-note large"><MessageSquare size={18}/><p>{document.note}</p></div>:<div className="empty-filter-state"><MessageSquare size={21}/><strong>Dokument nemá poznámku</strong></div>}</section>}
  </div>;
}

function ClientDocuments({client}:{client:(typeof clients)[number]}){const router=useRouter();const [documents,setDocuments]=useState<DocumentRecord[]>([]);const [loading,setLoading]=useState(true);useEffect(()=>{const controller=new AbortController();documentRepository.listParty(client.id,controller.signal).then(result=>setDocuments(result.documents)).finally(()=>setLoading(false));return()=>controller.abort();},[client.id]);return <section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Dokumenty klienta</h2><p>Dokumenty navázané na canonical záznam {client.name}.</p></div></div><DocumentList documents={documents} loading={loading} notify={()=>{}} openDocument={document=>router.push(documentRoute(document.id))}/></section>;}

const handoverStatusLabel=(status:string)=>({planned:"Naplánováno",ready:"Připraveno",in_progress:"Probíhá",completed:"Dokončeno",cancelled:"Zrušeno"} as Record<string,string>)[status]??"Neznámý stav";
const localDateTimeInput=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}T${String(date.getHours()).padStart(2,"0")}:${String(date.getMinutes()).padStart(2,"0")}`;

function UnitHandover({unit,notify,onNew,version,memberships,onChanged}:{unit:UnitRecord;notify:(message:string)=>void;onNew?:()=>void;version:number;memberships:MembershipOption[];onChanged:()=>void}){
  const [rows,setRows]=useState<HandoverRecord[]>([]);const [loading,setLoading]=useState(true);const [editing,setEditing]=useState<HandoverRecord|null>(null);
  useEffect(()=>{const unitId=backendEntityId(unit.backendId);if(!unitId){Promise.resolve().then(()=>{setRows([]);setLoading(false);});return;}const controller=new AbortController();Promise.resolve().then(()=>setLoading(true));handoverRepository.list({unitId},controller.signal).then(setRows).catch(()=>setRows([])).finally(()=>setLoading(false));return()=>controller.abort();},[unit.backendId,version]);
  const current=rows.find(row=>["planned","ready","in_progress"].includes(row.status))??rows.find(row=>row.status==="completed")??null;
  if(loading)return <section className="card detail-tab-card"><div className="empty-filter-state"><Clock3 size={21}/><strong>Načítám předání…</strong></div></section>;
  if(!current)return <section className="card detail-tab-card"><div className="list-action-toolbar"><span className="compact-result-count"><strong>Předání není naplánováno</strong></span>{onNew&&<button className="primary-button" onClick={onNew}><Plus size={16}/> Naplánovat předání</button>}</div><div className="empty-filter-state"><KeyRound size={22}/><strong>Bez aktivního termínu</strong><small>Naplánování samo o sobě nezmění jednotku na předanou.</small></div></section>;
  return <><section className="card detail-tab-card"><div className="tab-card-header"><div><h2>{current.status==="completed"?"Dokončené předání":"Naplánované předání"}</h2><p>{formatPragueDateTime(current.scheduledAt)} · {current.place??"Místo bude upřesněno"}</p></div><Badge tone={current.status==="completed"?"success":current.status==="ready"?"success":"warning"}>{handoverStatusLabel(current.status)}</Badge></div><div className="handover-detail-summary"><span><small>JEDNOTKA</small><strong>{unit.id}</strong></span><span><small>KLIENT</small><strong>{current.client}</strong></span><span><small>ODPOVĚDNÁ OSOBA</small><strong>{current.owner}</strong></span><span><small>PŘIPRAVENOST</small><strong>{current.readiness} %</strong></span></div>{current.participants.length>0&&<div className="handover-participants"><strong>Účastníci</strong>{current.participants.map(participant=><Badge key={`${participant.partyId}-${participant.role}`} tone="neutral">{participant.name}</Badge>)}</div>}{current.note&&<p className="handover-note">{current.note}</p>}<div className="modal-actions inline-actions">{current.status!=="completed"&&<button className="secondary-button" onClick={()=>setEditing(current)}>Upravit termín</button>}{current.status!=="completed"&&<button className="primary-button" onClick={()=>setEditing(current)}><KeyRound size={16}/> Otevřít předání</button>}</div></section>{editing&&<HandoverEditModal record={editing} memberships={memberships} close={()=>setEditing(null)} save={async value=>{await handoverRepository.update({handoverId:editing.id,...value});setEditing(null);notify(value.status==="completed"?"Předání bylo dokončeno":value.status==="cancelled"?"Předání bylo zrušeno":"Předání bylo upraveno");onChanged();}}/>}</>;
}

function UnitTasks({ unit,openTask }: { unit:UnitRecord;openTask: () => void }) {
  if(isDejviceUnit(unit))return <PilotEmptyState title="Úkoly" detail="K jednotce zatím nejsou importovány žádné úkoly."/>;
  return <section className="card detail-tab-card"><div className="tab-card-header"><div><h2>Úkoly jednotky</h2><p>Ruční i automatické úkoly navázané na A203.</p></div><button className="primary-button" onClick={openTask}><Plus size={17} /> Nový úkol</button></div><div className="large-task-list"><article><button className="task-check large" /><span className="priority-bar vysoka" /><span className="task-main-copy"><strong>Doplnit číslo účtu klienta</strong><small>Automaticky vytvořeno · blokuje generování SBK</small></span><Badge tone="danger">Vysoká</Badge><span className="task-due urgent"><Clock3 size={15} />Dnes</span><Avatar initials="IN" small /></article><article><button className="task-check large" /><span className="priority-bar stredni" /><span className="task-main-copy"><strong>Zapracovat připomínky klienta</strong><small>Smlouva SBK · verze v04</small></span><Badge tone="warning">Střední</Badge><span className="task-due"><Clock3 size={15} />Zítra</span><Avatar initials="PS" small /></article></div></section>;
}

function UnitHistory({unit,timeline}:{unit:UnitRecord;timeline:TimelineRecord[]}) {
  return <section className="card detail-tab-card history-tab"><div className="tab-card-header"><div><h2>Kompletní historie jednotky</h2><p>Jednotná auditní stopa obchodních, cenových, dokumentových a datových změn.</p></div><Badge tone="neutral">{unit.id}</Badge></div><div className="full-timeline">{timeline.map((item) => <article key={item.id}><div className={`timeline-icon ${item.icon}`}>{item.icon === "contract" ? <FileText size={17} /> : item.icon === "payment" ? <Banknote size={17} /> : item.icon === "build" ? <HardHat size={17} /> : <History size={17} />}</div><div><time>{formatPragueDateTime(item.date)}</time><strong>{item.title}</strong><p>{item.detail}</p></div></article>)}{!timeline.length&&<div className="empty-filter-state"><History size={22}/><strong>Zatím bez auditních událostí</strong><small>První uložená změna se zobrazí zde i v poslední aktivitě.</small></div>}</div></section>;
}

function PilotEmptyState({title,detail}:{title:string;detail:string}){
  return <section className="card detail-tab-card"><div className="tab-card-header"><div><h2>{title}</h2><p>{detail}</p></div></div><div className="empty-filter-state"><FileText size={22}/><strong>Bez zdrojových dat</strong><small>Do CRM nebyla doplněna žádná zástupná data.</small></div></section>;
}

function DocumentCreateModal({close,save}:{close:()=>void;save:(value:NewDocumentInput)=>Promise<void>}){const [projectCode,setProjectCode]=useState(projects[0]?.backendId??projects[0]?.code??"");const project=projects.find(item=>(item.backendId??item.code)===projectCode)??projects[0];const relevantUnits=units.filter(unit=>project&&unitBelongsToProject(unit,project));const relevantClients=clients.filter(client=>project&&client.projectNames.some(name=>projectMatchesName(project,name)));const relevantContracts=contracts.filter(contract=>project&&projectMatchesName(project,contract.project));const [name,setName]=useState("");const [typeCode,setTypeCode]=useState(documentTypeOptions[0].code);const [status,setStatus]=useState<DocumentStatus>("draft");const [unit,setUnit]=useState("");const [party,setParty]=useState("");const [contract,setContract]=useState("");const [salesCase,setSalesCase]=useState("");const [note,setNote]=useState("");return <FormModal title="Nový dokument" close={close} onSave={async()=>{if(!name.trim())throw new Error("Doplňte název dokumentu");const type=documentTypeOptions.find(item=>item.code===typeCode)!;await save({projectId:projectCode,projectName:project.name,name:name.trim(),typeCode,typeName:type.name,status,note,unit:unit||undefined,party:party||undefined,contract:contract||undefined,salesCase:salesCase||undefined});}} saveLabel="Vytvořit dokument"><div className="form-row"><label><span>Projekt</span><select value={projectCode} onChange={event=>{setProjectCode(event.target.value);setUnit("");setParty("");setContract("");}}>{projects.map(item=><option key={item.code} value={item.backendId??item.code}>{item.name}</option>)}</select></label><label><span>Typ dokumentu</span><select value={typeCode} onChange={event=>setTypeCode(event.target.value)}>{documentTypeOptions.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label></div><label><span>Název dokumentu</span><input value={name} onChange={event=>setName(event.target.value)} placeholder="Např. SBK A203 – Novákovi"/></label><div className="form-row"><label><span>Výchozí stav</span><select value={status} onChange={event=>setStatus(event.target.value as DocumentStatus)}>{documentStatusOptions.filter(item=>["draft","ready"].includes(item.code)).map(item=><option key={item.code} value={item.code}>{item.label}</option>)}</select></label><label><span>Jednotka</span><select value={unit} onChange={event=>setUnit(event.target.value)}><option value="">Bez vazby na jednotku</option>{relevantUnits.map(item=><option key={item.id} value={item.id}>{item.id} · {item.layout}</option>)}</select></label></div><div className="form-row"><label><span>Klient</span><select value={party} onChange={event=>setParty(event.target.value)}><option value="">Bez vazby na klienta</option>{relevantClients.map(item=><option key={item.id} value={item.name}>{item.name}</option>)}</select></label><label><span>Smlouva</span><select value={contract} onChange={event=>setContract(event.target.value)}><option value="">Bez vazby na smlouvu</option>{relevantContracts.map(item=><option key={item.id??item.reference} value={item.id??item.reference}>{item.type} · {item.unit}</option>)}</select></label></div><label><span>Technická vazba na sales case</span><input value={salesCase} onChange={event=>setSalesCase(event.target.value)} placeholder="Volitelné – interní identifikátor obchodní vazby"/></label><label><span>Poznámka</span><textarea value={note} onChange={event=>setNote(event.target.value)} rows={3} placeholder="Interní kontext dokumentu"/></label><p className="form-help"><Link2 size={14}/> Vazby se ukládají samostatně; dokument nevytváří kopii klienta, jednotky ani smlouvy.</p></FormModal>;}
function DocumentEditModal({document,close,save}:{document:DocumentRecord;close:()=>void;save:(value:{name:string;typeCode:string;typeName:string;status:DocumentStatus;note:string})=>Promise<void>}){const [name,setName]=useState(document.name);const [typeCode,setTypeCode]=useState(document.typeCode);const [status,setStatus]=useState<DocumentStatus>(document.status);const [note,setNote]=useState(document.note??"");return <FormModal title="Upravit metadata dokumentu" close={close} onSave={async()=>{if(!name.trim())throw new Error("Název dokumentu nesmí být prázdný");const type=documentTypeOptions.find(item=>item.code===typeCode)??{name:document.typeName};await save({name:name.trim(),typeCode,typeName:type.name,status,note});}}><label><span>Název</span><input value={name} onChange={event=>setName(event.target.value)}/></label><div className="form-row"><label><span>Typ</span><select value={typeCode} onChange={event=>setTypeCode(event.target.value)}>{documentTypeOptions.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><label><span>Stav</span><select value={status} onChange={event=>setStatus(event.target.value as DocumentStatus)}>{documentStatusOptions.map(item=><option key={item.code} value={item.code}>{item.label}</option>)}</select></label></div><label><span>Interní poznámka</span><textarea rows={4} value={note} onChange={event=>setNote(event.target.value)}/></label><p className="form-help"><History size={14}/> Změna metadat nebo stavu vytvoří auditní událost; fyzická verze se nepřepisuje.</p></FormModal>;}
function DocumentVersionModal({document,close,save}:{document:DocumentRecord;close:()=>void;save:(value:{label:string;status:DocumentStatus;note:string})=>Promise<void>}){const highest=Math.max(0,...(document.versions??[]).map(version=>Number(version.label.replace(/\D/g,""))||0));const [label,setLabel]=useState(`v${highest+1}`);const [status,setStatus]=useState<DocumentStatus>(document.status==="signed"?"ready":document.status);const [note,setNote]=useState("");return <FormModal title={`Nová verze · ${document.name}`} close={close} onSave={async()=>{if(!label.trim())throw new Error("Doplňte označení verze");if(!note.trim())throw new Error("Doplňte popis změny verze");await save({label:label.trim(),status,note});}} saveLabel="Vytvořit verzi"><div className="form-row"><label><span>Označení verze</span><input value={label} onChange={event=>setLabel(event.target.value)}/></label><label><span>Stav verze</span><select value={status} onChange={event=>setStatus(event.target.value as DocumentStatus)}>{documentStatusOptions.filter(item=>item.code!=="archived").map(item=><option key={item.code} value={item.code}>{item.label}</option>)}</select></label></div><label><span>Popis změn</span><textarea rows={4} value={note} onChange={event=>setNote(event.target.value)} placeholder="Co se oproti předchozí verzi změnilo?"/></label><p className="form-help"><FileCheck2 size={14}/> Vznikne nová fyzická verze pod stejným logickým dokumentem; předchozí verze zůstává zachována.</p></FormModal>;}
function EditProjectModal({project,memberships,canChangeManager,canChangeStatus,close,save}:{project:ProjectRecord;memberships:MembershipOption[];canChangeManager:boolean;canChangeStatus:boolean;close:()=>void;save:(value:{name:string;location:string;lifecycleStatus:string;managerMembershipId:string|null;plannedCompletion:string|null;stageCode:string;stageReason:string})=>Promise<void>}){
  const initialCompletion=projectCompletionMonthValue(project.plannedCompletionFrom??project.plannedCompletionTo);const [initialYear="",initialMonth=""]=initialCompletion.split("-");
  const [name,setName]=useState(project.name);const [location,setLocation]=useState(project.location);const [lifecycleStatus,setLifecycleStatus]=useState(project.lifecycleStatus??"active");const [manager,setManager]=useState(project.managerMembershipId??"");const [completionMonth,setCompletionMonth]=useState(initialMonth);const [completionYear,setCompletionYear]=useState(initialYear);const [stage,setStage]=useState(project.stageCode??projectConstructionCode(project.stage)??"preparation");const [reason,setReason]=useState("");
  return <FormModal title="Upravit projekt" close={close} onSave={async()=>{if(Boolean(completionMonth)!==Boolean(completionYear))throw new Error("Vyberte měsíc i rok plánovaného dokončení");await save({name,location,lifecycleStatus,managerMembershipId:manager||null,plannedCompletion:projectCompletionStorageDate(completionMonth&&completionYear?`${completionYear}-${completionMonth}`:""),stageCode:stage,stageReason:reason});}}><div className="form-row"><label><span>Název projektu</span><input value={name} onChange={e=>setName(e.target.value)} /></label><label><span>Lokalita</span><input value={location} onChange={e=>setLocation(e.target.value)} /></label></div><div className="form-row"><label><span>Životní cyklus projektu</span><select value={lifecycleStatus} onChange={e=>setLifecycleStatus(e.target.value)}><option value="preparation">Příprava</option><option value="active">Aktivní</option><option value="completed">Dokončený</option><option value="archived">Archivovaný</option></select></label><label><span>Vedoucí projektu</span><select value={manager} disabled={!canChangeManager} onChange={e=>setManager(e.target.value)}><option value="">Bez vedoucího</option>{memberships.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><MonthYearPicker month={completionMonth} year={completionYear} onMonth={setCompletionMonth} onYear={setCompletionYear}/><label><span>Aktuální fáze projektu</span><select value={stage} disabled={!canChangeStatus} onChange={e=>setStage(e.target.value)}>{PROJECT_CONSTRUCTION_PHASES.map(item=><option key={item.code} value={item.code}>{item.label}</option>)}</select></label>{stage!==(project.stageCode??projectConstructionCode(project.stage))&&<label><span>Důvod změny fáze</span><textarea value={reason} onChange={e=>setReason(e.target.value)} rows={2} placeholder="Krátké vysvětlení pro historii projektu" /></label>}</FormModal>;
}

const czechMonths=["leden","únor","březen","duben","květen","červen","červenec","srpen","září","říjen","listopad","prosinec"];
function MonthYearPicker({month,year,onMonth,onYear}:{month:string;year:string;onMonth:(value:string)=>void;onYear:(value:string)=>void}){const currentYear=new Date().getFullYear();const years=Array.from(new Set([...(year?[Number(year)]:[]),...Array.from({length:18},(_,index)=>currentYear-1+index)])).filter(Number.isFinite).sort((a,b)=>a-b);return <fieldset className="month-year-picker"><legend>Plánované dokončení</legend><label><span>Měsíc</span><select aria-label="Měsíc plánovaného dokončení" value={month} onChange={event=>onMonth(event.target.value)}><option value="">Vyberte měsíc</option>{czechMonths.map((label,index)=><option key={label} value={String(index+1).padStart(2,"0")}>{label}</option>)}</select></label><label><span>Rok</span><select aria-label="Rok plánovaného dokončení" value={year} onChange={event=>onYear(event.target.value)}><option value="">Vyberte rok</option>{years.map(item=><option key={item} value={item}>{item}</option>)}</select></label></fieldset>}
function EditUnitModal({unit,structures,close,save}:{unit:UnitRecord;structures:ProjectStructureOption[];close:()=>void;save:(value:{structureId:string|null;layout:string;areaM2:number;floorLabel:string;floorNumber?:number;orientation:string;usableAreaM2?:number;balconyM2?:number;terraceM2?:number;gardenM2?:number})=>Promise<void>}){const [layout,setLayout]=useState(unit.layout);const [area,setArea]=useState(String(unit.area));const [usable,setUsable]=useState(unit.usableArea?.toString()??"");const [floor,setFloor]=useState(unit.floor);const [floorNumber,setFloorNumber]=useState(unit.floor.match(/-?\d+(?:[.,]\d+)?/)?.[0]??"");const [orientation,setOrientation]=useState(unit.orientation);const [structure,setStructure]=useState(unit.structureId??"");const [balcony,setBalcony]=useState(unit.balcony?.toString()??"");const [terrace,setTerrace]=useState(unit.terrace?.toString()??"");const [garden,setGarden]=useState(unit.garden?.toString()??"");return <FormModal title={`Upravit jednotku ${unit.id}`} close={close} onSave={()=>save({structureId:structure||null,layout,areaM2:numberValue(area)!,usableAreaM2:numberValue(usable),floorLabel:floor,floorNumber:numberValue(floorNumber),orientation,balconyM2:numberValue(balcony),terraceM2:numberValue(terrace),gardenM2:numberValue(garden)})}><div className="form-row"><label><span>Dispozice</span><input value={layout} onChange={e=>setLayout(e.target.value)} /></label><label><span>Budova / etapa / sekce</span><select value={structure} onChange={e=>setStructure(e.target.value)}><option value="">Bez zařazení</option>{structures.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><div className="form-row"><label><span>Podlahová plocha m²</span><input inputMode="decimal" value={area} onChange={e=>setArea(e.target.value)} /></label><label><span>Užitná plocha m²</span><input inputMode="decimal" value={usable} onChange={e=>setUsable(e.target.value)} /></label></div><div className="form-row"><label><span>Podlaží</span><input value={floor} onChange={e=>setFloor(e.target.value)} /></label><label><span>Číslo podlaží</span><input inputMode="decimal" value={floorNumber} onChange={e=>setFloorNumber(e.target.value)} /></label><label><span>Orientace</span><input value={orientation} onChange={e=>setOrientation(e.target.value)} /></label></div><div className="form-row"><label><span>Balkon m²</span><input inputMode="decimal" value={balcony} onChange={e=>setBalcony(e.target.value)} /></label><label><span>Terasa m²</span><input inputMode="decimal" value={terrace} onChange={e=>setTerrace(e.target.value)} /></label><label><span>Zahrada m²</span><input inputMode="decimal" value={garden} onChange={e=>setGarden(e.target.value)} /></label></div></FormModal>}
function EditPriceModal({unit,close,save}:{unit:UnitRecord;close:()=>void;save:(value:{priceType:string;amount:number;validFrom:string;reason:string})=>Promise<void>}){const [priceType,setPriceType]=useState("sale_price");const [amount,setAmount]=useState(String(unit.basePrice??unit.price));const [validFrom,setValidFrom]=useState(new Date().toISOString().slice(0,10));const [reason,setReason]=useState("");return <FormModal title={`Nový záznam ceny · ${unit.id}`} close={close} onSave={async()=>{if(!reason.trim())throw new Error("Doplňte důvod změny ceny");await save({priceType,amount:Number(amount.replace(/\s/g,"").replace(",",".")),validFrom,reason});}}><label><span>Typ cenového záznamu</span><select value={priceType} onChange={e=>setPriceType(e.target.value)}><option value="list_price">Ceníková cena</option><option value="sale_price">Aktuální prodejní cena</option><option value="individual_discount">Individuální sleva</option><option value="contract_price">Finální smluvní cena</option></select></label><label><span>{priceType==="individual_discount"?"Výše slevy v Kč":"Nová cena v Kč"}</span><input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)} /></label><label><span>Datum účinnosti</span><input type="date" value={validFrom} onChange={e=>setValidFrom(e.target.value)} /></label><label><span>Důvod změny</span><textarea required value={reason} onChange={e=>setReason(e.target.value)} rows={3} placeholder="Např. schválená individuální nabídka" /></label><p className="form-help"><History size={14}/> Stávající cena zůstane v append-only historii; nevzniká její přepis.</p></FormModal>}
function EditClientModal({client,close,save}:{client:(typeof clients)[number];close:()=>void;save:(value:{firstName:string;lastName:string;legalName:string;registrationNumber:string;vatNumber:string;contactPerson:string;email:string;phone:string;line1:string;line2:string;city:string;postalCode:string;countryCode:string})=>Promise<void>}){const parts=client.name.split(" ");const [firstName,setFirstName]=useState(client.firstName??parts[0]??"");const [lastName,setLastName]=useState(client.lastName??parts.slice(1).join(" "));const [legalName,setLegalName]=useState(client.legalName??client.name);const [registrationNumber,setRegistrationNumber]=useState(client.registrationNumber??"");const [vatNumber,setVatNumber]=useState(client.vatNumber??"");const [contactPerson,setContactPerson]=useState(client.contactPerson??"");const [email,setEmail]=useState(client.email);const [phone,setPhone]=useState(client.phone);const [line1,setLine1]=useState(client.address?.line1??"");const [line2,setLine2]=useState(client.address?.line2??"");const [city,setCity]=useState(client.address?.city??"");const [postalCode,setPostalCode]=useState(client.address?.postalCode??"");const [countryCode,setCountryCode]=useState(client.address?.countryCode??"CZ");return <FormModal title="Upravit klienta" close={close} onSave={()=>save({firstName,lastName,legalName,registrationNumber,vatNumber,contactPerson,email,phone,line1,line2,city,postalCode,countryCode})}>{client.kind==="FO"?<div className="form-row"><label><span>Jméno</span><input value={firstName} onChange={e=>setFirstName(e.target.value)}/></label><label><span>Příjmení</span><input value={lastName} onChange={e=>setLastName(e.target.value)}/></label></div>:<><label><span>Obchodní název</span><input value={legalName} onChange={e=>setLegalName(e.target.value)}/></label><div className="form-row"><label><span>IČO</span><input value={registrationNumber} onChange={e=>setRegistrationNumber(e.target.value)}/></label><label><span>DIČ</span><input value={vatNumber} onChange={e=>setVatNumber(e.target.value)}/></label><label><span>Kontaktní osoba</span><input value={contactPerson} onChange={e=>setContactPerson(e.target.value)}/></label></div></>}<div className="form-row"><label><span>E-mail</span><input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label><span>Telefon</span><input value={phone} onChange={e=>setPhone(e.target.value)}/></label></div><label><span>{client.kind==="FO"?"Adresa bydliště":"Sídlo společnosti"}</span><input value={line1} onChange={e=>setLine1(e.target.value)} placeholder="Ulice a číslo"/></label><label><span>Doplnění adresy</span><input value={line2} onChange={e=>setLine2(e.target.value)} placeholder="Budova, patro…"/></label><div className="form-row"><label><span>Město</span><input value={city} onChange={e=>setCity(e.target.value)}/></label><label><span>PSČ</span><input value={postalCode} onChange={e=>setPostalCode(e.target.value)}/></label><label><span>Země</span><input maxLength={2} value={countryCode} onChange={e=>setCountryCode(e.target.value.toUpperCase())}/></label></div></FormModal>}
function AccessoryModal({unit,inventory,close,assign,remove,create}:{unit:UnitRecord;inventory:CatalogAccessoryRecord[];close:()=>void;assign:(item:CatalogAccessoryRecord)=>Promise<void>;remove:(item:NonNullable<UnitRecord["accessories"]>[number])=>Promise<void>;create:(value:{category:"parking"|"cellar"|"wallbox";code:string;areaM2?:number|null;amount:number;amountNet?:number|null;relatedAccessoryId?:string|null})=>Promise<void>}){
  const [category,setCategory]=useState("all");const [creating,setCreating]=useState(false);const [newCategory,setNewCategory]=useState<"parking"|"cellar"|"wallbox">("parking");const [code,setCode]=useState("");const [area,setArea]=useState("");const [amount,setAmount]=useState("");const [related,setRelated]=useState("");const [error,setError]=useState("");const [saving,setSaving]=useState(false);const [busyItem,setBusyItem]=useState<string|null>(null);
  const assigned=unit.accessories??[];const available=inventory.filter(item=>item.available&&(category==="all"||item.category===category));const parking=inventory.filter(item=>item.category==="parking");
  const submitCreate=async()=>{const parsed=Number(amount.replace(/\s/g,"").replace(",","."));if(!code.trim())return setError("Doplňte označení příslušenství.");if(!Number.isFinite(parsed)||parsed<0)return setError("Doplňte platnou cenu.");setSaving(true);setError("");try{await create({category:newCategory,code:code.trim(),areaM2:area?Number(area.replace(",",".")):null,amount:parsed,relatedAccessoryId:newCategory==="wallbox"&&related?related:null});}catch(reason){setError(reason instanceof Error?reason.message:"Příslušenství se nepodařilo vytvořit.");setSaving(false);}};
  const removeItem=async(item:NonNullable<UnitRecord["accessories"]>[number])=>{if(!window.confirm(`Opravdu uvolnit ${item.type.toLocaleLowerCase("cs-CZ")} ${item.code}? Historie přiřazení zůstane zachována.`))return;setBusyItem(item.assignmentId??item.id);setError("");try{await remove(item);}catch(reason){setError(reason instanceof Error?reason.message:"Příslušenství se nepodařilo uvolnit.");setBusyItem(null);}};
  const assignItem=async(item:CatalogAccessoryRecord)=>{setBusyItem(item.id);setError("");try{await assign(item);}catch(reason){setError(reason instanceof Error?reason.message:"Příslušenství se nepodařilo přiřadit.");setBusyItem(null);}};
  return <FormModal title={`Příslušenství · ${unit.id}`} close={close} onSave={async()=>close()} saveLabel="Hotovo"><div className="accessory-manager">{error&&<div className="form-error"><AlertTriangle size={15}/>{error}</div>}<section><div className="modal-section-head"><strong>Aktuálně přiřazeno</strong><small>{assigned.length} položek</small></div>{assigned.length?assigned.map(item=><div className="accessory-choice assigned" key={item.assignmentId??item.id}><span><strong>{item.type} {item.code}</strong><small>{item.areaM2?`${item.areaM2} m² · `:""}{formatMoney(item.amount??0)}{item.relation?` · navázáno na ${item.relation}`:""}</small></span><button type="button" className="text-button danger-text" disabled={busyItem===(item.assignmentId??item.id)} onClick={()=>void removeItem(item)}>{busyItem===(item.assignmentId??item.id)?"Uvolňuji…":"Uvolnit"}</button></div>):<p className="empty-copy">Jednotka nemá přiřazené příslušenství.</p>}</section><section><div className="modal-section-head"><strong>Dostupné v projektu</strong><span className="accessory-toolbar"><select value={category} onChange={e=>setCategory(e.target.value)}><option value="all">Všechny typy</option><option value="parking">Parkovací stání</option><option value="cellar">Sklepy</option><option value="wallbox">Wallboxy</option></select><button type="button" className="secondary-button compact" onClick={()=>setCreating(value=>!value)}><Plus size={15}/> Nové příslušenství</button></span></div>{creating&&<div className="accessory-create-form"><div className="form-row"><label><span>Typ</span><select value={newCategory} onChange={event=>setNewCategory(event.target.value as typeof newCategory)}><option value="parking">Parkovací stání</option><option value="cellar">Sklep</option><option value="wallbox">Wallbox</option></select></label><label><span>Označení</span><input value={code} onChange={event=>setCode(event.target.value)} placeholder={newCategory==="wallbox"?"W9":newCategory==="cellar"?"S20":"P30"}/></label></div><div className="form-row">{newCategory==="cellar"&&<label><span>Plocha m²</span><input inputMode="decimal" value={area} onChange={event=>setArea(event.target.value)}/></label>}<label><span>Cena včetně DPH</span><input inputMode="decimal" value={amount} onChange={event=>setAmount(event.target.value)}/></label>{newCategory==="wallbox"&&<label><span>Navázané parkovací stání</span><select value={related} onChange={event=>setRelated(event.target.value)}><option value="">Bez vazby</option>{parking.map(item=><option key={item.id} value={item.id}>{item.code}</option>)}</select></label>}</div><button type="button" className="primary-button compact" disabled={saving} onClick={()=>void submitCreate()}>{saving?"Ukládám…":"Vytvořit položku"}</button></div>}{available.length?available.map(item=><button type="button" className="accessory-choice" key={item.id} disabled={busyItem===item.id} onClick={()=>void assignItem(item)}><span><strong>{item.type} {item.code}</strong><small>{item.areaM2?`${item.areaM2} m² · `:""}{formatMoney(item.amount??0)}{item.relation?` · vazba na ${item.relation}`:" · volné k přiřazení"}</small></span>{busyItem===item.id?<Clock3 size={16}/>:<Plus size={16}/>}</button>):<p className="empty-copy">V této kategorii není volné příslušenství.</p>}</section></div></FormModal>
}
type NewPartyDraft={kind:"individual"|"organization";salutation?:string;firstName?:string;lastName?:string;legalName?:string;registrationNumber?:string;email?:string;phone?:string};
function SalesActionModal({action,clientRows,close,save}:{action:{unit:UnitRecord;mode:"interest"|"pre_reservation"|"reservation"|"convert"|"cancel"};clientRows:typeof clients;close:()=>void;save:(value:{partyId:string;newParty?:NewPartyDraft;expiresAt:string;reason:string})=>Promise<void>}){
  const context=unitCommercialContexts[action.unit.id];
  const defaultParty=context?.buyers[0]?.partyId??context?.interests[0]?.partyId??clientRows[0]?.id??"";
  const [partyId,setPartyId]=useState(defaultParty);const [query,setQuery]=useState("");const [creatingNew,setCreatingNew]=useState(false);
  const [partyKind,setPartyKind]=useState<"individual"|"organization">("individual");const [salutation,setSalutation]=useState("");const [firstName,setFirstName]=useState("");const [lastName,setLastName]=useState("");const [legalName,setLegalName]=useState("");const [registrationNumber,setRegistrationNumber]=useState("");const [email,setEmail]=useState("");const [phone,setPhone]=useState("");
  const [startedAt]=useState(()=>new Date());const [duration,setDuration]=useState(action.mode==="pre_reservation"?"48":"168");const [customExpiresAt,setCustomExpiresAt]=useState(()=>new Date(Date.now()+7*86400000).toISOString().slice(0,16));const [reason,setReason]=useState("");
  const expiresAt=duration==="custom"?new Date(customExpiresAt):new Date(startedAt.getTime()+Number(duration)*3600000);
  const candidates=clientRows.filter(item=>item.name.toLowerCase().includes(query.toLowerCase())||item.email.toLowerCase().includes(query.toLowerCase())).slice(0,8);
  const titles={interest:"Přidat zájemce",pre_reservation:"Vytvořit předrezervaci",reservation:"Vytvořit rezervaci",convert:"Převést na rezervaci",cancel:"Zrušit a uvolnit jednotku"};const destructive=action.mode==="cancel";
  return <FormModal title={`${titles[action.mode]} · ${action.unit.id}`} close={close} onSave={async()=>{
    let selectedPartyId=partyId;let newParty:NewPartyDraft|undefined;
    if(creatingNew){if(partyKind==="individual"&&(!firstName.trim()||!lastName.trim()))throw new Error("Doplňte jméno a příjmení");if(partyKind==="organization"&&!legalName.trim())throw new Error("Doplňte název společnosti");if(email&&!/^\S+@\S+\.\S+$/.test(email))throw new Error("Zadejte platnou e-mailovou adresu");newParty={kind:partyKind,salutation:salutation||undefined,firstName:firstName.trim()||undefined,lastName:lastName.trim()||undefined,legalName:legalName.trim()||undefined,registrationNumber:registrationNumber.trim()||undefined,email:email.trim()||undefined,phone:phone.trim()||undefined};if(action.mode==="interest"){const projectId=action.unit.projectBackendId??projects.find(item=>item.name===action.unit.project)?.backendId??"";if(!projectId)throw new Error("Projekt jednotky není dostupný");const created=await clientRepository.createParty({projectId,...newParty});selectedPartyId=created.id;}}
    if(!destructive&&!creatingNew&&!selectedPartyId)throw new Error("Vyberte klienta nebo zájemce");if(action.mode!=="interest"&&!destructive&&(Number.isNaN(expiresAt.getTime())||expiresAt<=new Date()))throw new Error("Vyberte platný budoucí termín");if(destructive&&!reason.trim())throw new Error("Doplňte důvod zrušení");if(destructive&&!window.confirm("Tato akce uvolní jednotku. Opravdu pokračovat?"))return;await save({partyId:selectedPartyId,newParty:action.mode==="interest"?undefined:newParty,expiresAt:expiresAt.toISOString(),reason:reason.trim()});
  }} saveLabel={destructive?"Potvrdit uvolnění":"Pokračovat"}>
    {!destructive&&action.mode!=="convert"&&<>{!creatingNew?<><label><span>Vyhledat v jednotné databázi klientů</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Jméno, e-mail…"/></label><div className="party-picker">{candidates.map(item=><label key={item.id} className={partyId===item.id?"selected":""}><input type="radio" name="party" checked={partyId===item.id} onChange={()=>setPartyId(item.id)}/><Avatar initials={item.initials} small/><span><strong>{item.name}</strong><small>{item.email||item.phone} · {item.projects}</small></span></label>)}</div><button type="button" className="text-button new-party-toggle" onClick={()=>setCreatingNew(true)}><Plus size={14}/> Klient v databázi není – založit nový</button></>:<div className="new-party-fields"><div className="modal-section-head"><strong>Nový klient</strong><button type="button" className="text-button" onClick={()=>setCreatingNew(false)}>Vybrat existujícího</button></div><label><span>Typ</span><select value={partyKind} onChange={event=>setPartyKind(event.target.value as "individual"|"organization")}><option value="individual">Fyzická osoba</option><option value="organization">Právnická osoba</option></select></label>{partyKind==="individual"?<div className="form-row"><label><span>Oslovení (volitelné)</span><select value={salutation} onChange={event=>setSalutation(event.target.value)}><option value="">Bez oslovení</option><option value="pan">pan</option><option value="paní">paní</option></select></label><label><span>Jméno</span><input autoFocus value={firstName} onChange={event=>setFirstName(event.target.value)}/></label><label><span>Příjmení</span><input value={lastName} onChange={event=>setLastName(event.target.value)}/></label></div>:<div className="form-row"><label><span>Obchodní název</span><input value={legalName} onChange={event=>setLegalName(event.target.value)}/></label><label><span>IČO</span><input value={registrationNumber} onChange={event=>setRegistrationNumber(event.target.value)}/></label></div>}<div className="form-row"><label><span>E-mail</span><input type="email" value={email} onChange={event=>setEmail(event.target.value)}/></label><label><span>Telefon</span><input value={phone} onChange={event=>setPhone(event.target.value)}/></label></div></div>}</>}
    {action.mode!=="interest"&&action.mode!=="cancel"&&<><label><span>Platnost</span><select value={duration} onChange={event=>setDuration(event.target.value)}><option value="24">24 hodin</option><option value="48">48 hodin</option><option value="72">3 dny</option><option value="120">5 dní</option><option value="168">7 dní</option><option value="336">14 dní</option><option value="custom">Vlastní termín</option></select></label>{duration==="custom"&&<label><span>Vlastní termín</span><input type="datetime-local" value={customExpiresAt} onChange={event=>setCustomExpiresAt(event.target.value)}/></label>}<div className="hold-expiration-preview"><Clock3 size={15}/><span><small>Platnost skončí</small><strong>{Number.isNaN(expiresAt.getTime())?"Vyberte termín":formatPragueDateTime(expiresAt.toISOString())}</strong></span></div></>}<label><span>{destructive?"Důvod zrušení":"Poznámka (volitelné)"}</span><textarea rows={3} value={reason} onChange={event=>setReason(event.target.value)} placeholder={destructive?"Proč se jednotka uvolňuje?":"Volitelný obchodní kontext"}/></label>
  </FormModal>
}
function NewClientModal({projects:projectRows,close,save,useExisting,openExisting}:{projects:ProjectRecord[];close:()=>void;save:(value:{projectId:string;kind:"individual"|"organization";firstName?:string;lastName?:string;legalName?:string;registrationNumber?:string;email?:string;phone?:string;duplicateOverride?:boolean})=>Promise<void>;useExisting:(partyId:string,projectId:string)=>Promise<void>;openExisting:(partyId:string)=>void}){
  const [kind,setKind]=useState<"individual"|"organization">("individual");const [projectId,setProjectId]=useState(projectRows[0]?.backendId??"");const [firstName,setFirstName]=useState("");const [lastName,setLastName]=useState("");const [legalName,setLegalName]=useState("");const [registrationNumber,setRegistrationNumber]=useState("");const [email,setEmail]=useState("");const [phone,setPhone]=useState("");const [matches,setMatches]=useState<Awaited<ReturnType<typeof clientRepository.findDuplicates>>>([]);const [duplicateOverride,setDuplicateOverride]=useState(false);
  const draft=()=>({kind,firstName:firstName.trim()||undefined,lastName:lastName.trim()||undefined,legalName:legalName.trim()||undefined,registrationNumber:registrationNumber.trim()||undefined,email:email.trim()||undefined,phone:phone.trim()||undefined});
  // `useExisting` je callback z vlastnosti komponenty, nikoli React hook.
  // eslint-disable-next-line react-hooks/rules-of-hooks
  return <FormModal title="Nový klient nebo zájemce" close={close} saveLabel={matches.length&&!duplicateOverride?"Zkontrolovat výběr":"Vytvořit klienta"} onSave={async()=>{if(!projectId)throw new Error("Vyberte projekt");if(kind==="individual"&&(!firstName.trim()||!lastName.trim()))throw new Error("Doplňte jméno a příjmení");if(kind==="organization"&&!legalName.trim())throw new Error("Doplňte název společnosti");if(email&&!/^\S+@\S+\.\S+$/.test(email))throw new Error("Zadejte platnou e-mailovou adresu");if(!matches.length&&!duplicateOverride){const found=await clientRepository.findDuplicates({projectId,...draft()});if(found.length){setMatches(found);return;}}if(matches.length&&!duplicateOverride)return;await save({projectId,...draft(),duplicateOverride});}}><div className="form-row"><label><span>Typ klienta</span><select value={kind} onChange={event=>{setKind(event.target.value as "individual"|"organization");setMatches([]);setDuplicateOverride(false);}}><option value="individual">Fyzická osoba</option><option value="organization">Právnická osoba</option></select></label><label><span>Projekt</span><select value={projectId} onChange={event=>{setProjectId(event.target.value);setMatches([]);setDuplicateOverride(false);}}>{projectRows.map(project=><option key={project.backendId} value={project.backendId}>{project.name}</option>)}</select></label></div>{kind==="individual"?<div className="form-row"><label><span>Jméno</span><input autoFocus value={firstName} onChange={event=>{setFirstName(event.target.value);setMatches([]);}}/></label><label><span>Příjmení</span><input value={lastName} onChange={event=>{setLastName(event.target.value);setMatches([]);}}/></label></div>:<div className="form-row"><label><span>Název společnosti</span><input autoFocus value={legalName} onChange={event=>{setLegalName(event.target.value);setMatches([]);}}/></label><label><span>IČO</span><input value={registrationNumber} onChange={event=>{setRegistrationNumber(event.target.value);setMatches([]);}}/></label></div>}<div className="form-row"><label><span>E-mail</span><input type="email" value={email} onChange={event=>{setEmail(event.target.value);setMatches([]);}}/></label><label><span>Telefon</span><input type="tel" value={phone} onChange={event=>{setPhone(event.target.value);setMatches([]);}}/></label></div>{matches.length>0&&<div className="duplicate-review"><div className="duplicate-warning"><AlertTriangle size={18}/><span><strong>{matches.some(match=>match.strength==="strong")?"Klient s těmito údaji už pravděpodobně existuje.":"Našli jsme podobného klienta. Ověřte prosím další údaje."}</strong><small>Ověřte kontakty a projektové vazby před vytvořením nového záznamu.</small></span></div>{matches.map(match=><article key={match.id} className={match.strength==="strong"?"strong-match":"possible-match"}><div><strong>{match.name}</strong><small>{[match.email,match.phone].filter(Boolean).join(" · ")||"Kontakt není dostupný"}</small><small>{[...match.projects,...match.units].join(" · ")||"Bez aktivní projektové vazby"}</small><span>{match.reasons.join(", ")}</span></div><div><button type="button" className="secondary-button compact" onClick={()=>openExisting(match.id)}>Otevřít klienta</button><button type="button" className="primary-button compact" onClick={()=>void useExisting(match.id,projectId)}>Použít existujícího klienta</button></div></article>)}<button type="button" className="text-button duplicate-override" onClick={()=>setDuplicateOverride(true)}>Přesto vytvořit nového</button>{duplicateOverride&&<small>Vytvoření nového záznamu bude zaznamenáno do auditu.</small>}</div>}</FormModal>;
}
function HandoverScheduleModal({units:unitRows,memberships,defaultUnit,defaultProject,close,save}:{units:UnitRecord[];memberships:MembershipOption[];defaultUnit?:UnitRecord;defaultProject?:ProjectRecord;close:()=>void;save:(value:{unitId:string;scheduledAt:string;responsibleMembershipId:string;place?:string|null;note?:string|null;idempotencyKey:string})=>Promise<void>}){
  const candidates=unitRows.filter(unit=>unit.status!=="Volný"&&(!defaultProject||unitBelongsToProject(unit,defaultProject)));const [unitId,setUnitId]=useState(defaultUnit?.backendId??candidates[0]?.backendId??"");const [responsibleMembershipId,setResponsibleMembershipId]=useState(memberships[0]?.id??"");const [scheduledAt,setScheduledAt]=useState(()=>{const initial=addCalendarDays(new Date(),1);initial.setHours(10,0,0,0);return localDateTimeInput(initial);});const [place,setPlace]=useState(defaultProject?.location??"");const [note,setNote]=useState("");const [idempotencyKey]=useState(()=>crypto.randomUUID());const selected=unitRows.find(unit=>unit.backendId===unitId);
  return <FormModal title="Naplánovat předání" close={close} saveLabel="Naplánovat" onSave={async()=>{if(!unitId)throw new Error("Vyberte jednotku");if(!responsibleMembershipId)throw new Error("Vyberte odpovědnou osobu");const date=new Date(scheduledAt);if(Number.isNaN(date.getTime())||date<=new Date())throw new Error("Termín musí být v budoucnu");await save({unitId,scheduledAt:date.toISOString(),responsibleMembershipId,place:place.trim()||null,note:note.trim()||null,idempotencyKey});}}><div className="context-links"><div><Building2 size={16}/><span><small>Projekt</small><strong>{selected?.project??defaultProject?.name??"Vyberte jednotku"}</strong></span></div><div><Home size={16}/><span><small>Jednotka</small><strong>{selected?.id??"—"}</strong></span></div><div><UserRound size={16}/><span><small>Klient</small><strong>{selected?.client||"Bez přiřazeného klienta"}</strong></span></div></div><label><span>Jednotka</span><select value={unitId} disabled={Boolean(defaultUnit)} onChange={event=>setUnitId(event.target.value)}>{candidates.map(unit=><option key={unit.backendId} value={unit.backendId}>{unit.id} · {unit.project}{unit.client?` · ${unit.client}`:""}</option>)}</select>{!candidates.length&&<small>Žádná vhodná jednotka pro naplánování předání.</small>}</label><div className="form-row"><label><span>Datum a čas</span><input type="datetime-local" value={scheduledAt} onChange={event=>setScheduledAt(event.target.value)}/></label><label><span>Odpovědná osoba</span><select value={responsibleMembershipId} onChange={event=>setResponsibleMembershipId(event.target.value)}>{memberships.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><label><span>Místo</span><input value={place} onChange={event=>setPlace(event.target.value)} placeholder="Např. kancelář projektu"/></label><label><span>Poznámka</span><textarea rows={3} value={note} onChange={event=>setNote(event.target.value)} placeholder="Volitelné upřesnění pro předání"/></label></FormModal>;
}

function HandoverEditModal({record,memberships,close,save}:{record:HandoverRecord;memberships:MembershipOption[];close:()=>void;save:(value:{scheduledAt:string;responsibleMembershipId:string;status:string;readiness:number;attention?:string|null;place?:string|null;note?:string|null;completedAt?:string|null})=>Promise<void>}){
  const owner=memberships.find(item=>item.name===record.owner);const [scheduledAt,setScheduledAt]=useState(localDateTimeInput(new Date(record.scheduledAt)));const [responsibleMembershipId,setResponsibleMembershipId]=useState(owner?.id??memberships[0]?.id??"");const [place,setPlace]=useState(record.place??"");const [note,setNote]=useState(record.note??"");const [readiness,setReadiness]=useState(record.readiness);const [status,setStatus]=useState(record.status);const [completedAt,setCompletedAt]=useState(localDateTimeInput(new Date()));
  return <FormModal title={`Předání jednotky ${record.unit}`} close={close} saveLabel={status==="completed"?"Dokončit předání":status==="cancelled"?"Zrušit předání":"Uložit"} onSave={async()=>{if(!responsibleMembershipId)throw new Error("Vyberte odpovědnou osobu");if(status==="cancelled"&&!window.confirm("Opravdu chcete naplánované předání zrušit?"))return;if(status==="completed"&&!window.confirm("Potvrďte, že jednotka byla skutečně předána."))return;await save({scheduledAt:new Date(scheduledAt).toISOString(),responsibleMembershipId,status,readiness,attention:null,place:place.trim()||null,note:note.trim()||null,completedAt:status==="completed"?new Date(completedAt).toISOString():null});}}><div className="context-links"><div><Home size={16}/><span><small>Jednotka</small><strong>{record.unit}</strong></span></div><div><UserRound size={16}/><span><small>Klient</small><strong>{record.client}</strong></span></div><div><Building2 size={16}/><span><small>Projekt</small><strong>{record.project}</strong></span></div></div><div className="form-row"><label><span>Datum a čas</span><input type="datetime-local" value={scheduledAt} onChange={event=>setScheduledAt(event.target.value)}/></label><label><span>Odpovědná osoba</span><select value={responsibleMembershipId} onChange={event=>setResponsibleMembershipId(event.target.value)}>{memberships.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><div className="form-row"><label><span>Stav</span><select value={status} onChange={event=>setStatus(event.target.value)}><option value="planned">Naplánováno</option><option value="ready">Připraveno</option><option value="in_progress">Probíhá</option><option value="completed">Dokončeno</option><option value="cancelled">Zrušeno</option></select></label><label><span>Připravenost</span><input type="number" min="0" max="100" value={readiness} onChange={event=>setReadiness(Number(event.target.value))}/></label></div>{status==="completed"&&<label><span>Skutečné datum a čas předání</span><input type="datetime-local" value={completedAt} onChange={event=>setCompletedAt(event.target.value)}/></label>}<label><span>Místo</span><input value={place} onChange={event=>setPlace(event.target.value)}/></label><label><span>Poznámka</span><textarea rows={3} value={note} onChange={event=>setNote(event.target.value)}/></label></FormModal>;
}
type GlobalContractInput={salesCaseId:string;type:"rs"|"sbk"|"ks"|"amendment";reference:string;title:string;idempotencyKey:string;paymentCalculationType?:"percentage"|"fixed";paymentInputValue?:number;paymentDueAt?:string};
type ContractModalInput=GlobalContractInput|ContextualContractInput;
function NewContractModal({units:unitRows,context,close,save}:{units:UnitRecord[];context?:{unit:UnitRecord;action:UnitNextContractAction};close:()=>void;save:(value:ContractModalInput)=>Promise<void>}){
  const candidates=unitRows.filter(unit=>Boolean(unitCommercialContexts[unit.id]?.salesCaseId));const [unitKey,setUnitKey]=useState(context?.unit.id??candidates[0]?.id??"");const [type,setType]=useState<"rs"|"sbk"|"ks"|"amendment">(context?.action.kind==="create_contract"?context.action.contractType:"rs");const [paymentMode,setPaymentMode]=useState<"percentage"|"fixed">("percentage");const [paymentValue,setPaymentValue]=useState(type==="sbk"?"10":"2");const [dueMode,setDueMode]=useState("5");const [customDueAt,setCustomDueAt]=useState(()=>localDateKey(addCalendarDays(new Date(),5)));const [idempotencyKey]=useState(()=>crypto.randomUUID());const selectedUnit=context?.unit??candidates.find(unit=>unit.id===unitKey);const hasPayment=type==="rs"||type==="sbk";const parsedPayment=Number(paymentValue.replace(/\s/g,"").replace(",","."));const calculatedPayment=selectedUnit&&Number.isFinite(parsedPayment)?paymentMode==="percentage"?Math.round(selectedUnit.price*parsedPayment/100):parsedPayment:0;const dueAt=dueMode==="custom"?new Date(`${customDueAt}T23:59:59`):addCalendarDays(new Date(),Number(dueMode));const contractCode=selectedUnit?`${type.toUpperCase()} ${selectedUnit.id}`:type.toUpperCase();const contractTitle=selectedUnit?`${({rs:"Rezervační smlouva",sbk:"Smlouva o budoucí kupní smlouvě",ks:"Kupní smlouva",amendment:"Dodatek"} as const)[type]} · ${selectedUnit.id}`:type.toUpperCase();
  return <FormModal title={context?`Vytvořit ${type.toUpperCase()}`:"Nová smlouva"} close={close} saveLabel="Vytvořit smlouvu" onSave={async()=>{if(!selectedUnit)throw new Error("Vyberte jednotku s aktivním obchodním procesem");if(hasPayment&&(!Number.isFinite(parsedPayment)||parsedPayment<=0))throw new Error("Doplňte platnou výši platby");if(hasPayment&&(Number.isNaN(dueAt.getTime())||dueAt<=new Date()))throw new Error("Vyberte budoucí datum splatnosti");const payment=hasPayment?{paymentCalculationType:paymentMode,paymentInputValue:parsedPayment,paymentDueAt:dueAt.toISOString()}:{};if(context){const unitId=backendEntityId(selectedUnit.backendId);if(!unitId)throw new Error("Jednotka nemá platný databázový identifikátor");await save({unitId,idempotencyKey,...payment});return;}const salesCaseId=unitCommercialContexts[unitKey]?.salesCaseId;if(!salesCaseId)throw new Error("Vyberte jednotku s aktivním obchodním procesem");await save({salesCaseId,type,reference:contractCode,title:contractTitle,idempotencyKey,...payment});}}>{context?<div className="context-links"><div><Home size={16}/><span><small>Jednotka</small><strong>{selectedUnit?.id}</strong></span></div><div><UserRound size={16}/><span><small>Klient</small><strong>{context.action.buyerNames.join(" a ")||selectedUnit?.client||"Bez přiřazeného klienta"}</strong></span></div><div><FileText size={16}/><span><small>Smlouva</small><strong>{contractCode}</strong></span></div></div>:<><label><span>Jednotka a klient</span><select value={unitKey} onChange={event=>setUnitKey(event.target.value)}>{candidates.map(unit=><option key={unit.id} value={unit.id}>{unit.id} · {unit.client||"aktivní obchodní proces"} · {unit.project}</option>)}</select>{!candidates.length&&<small>Nejdříve u jednotky vytvořte předrezervaci nebo rezervaci.</small>}</label><div className="form-row"><label><span>Typ smlouvy</span><select value={type} onChange={event=>{const next=event.target.value as typeof type;setType(next);setPaymentValue(next==="rs"?"2":next==="sbk"?"10":"");}}><option value="rs">RS</option><option value="sbk">SBK</option><option value="ks">KS</option><option value="amendment">Dodatek</option></select></label><span className="form-derived-value"><small>Označení</small><strong>{contractCode}</strong></span></div></>}{hasPayment&&<fieldset className="contract-payment-terms"><legend>{type==="rs"?"Rezervační poplatek":"Platba při SBK"}</legend><div className="form-row"><label><span>Způsob výpočtu</span><select value={paymentMode} onChange={event=>setPaymentMode(event.target.value as typeof paymentMode)}><option value="percentage">Procento z aktuální ceny</option><option value="fixed">Pevná částka v Kč</option></select></label><label><span>{paymentMode==="percentage"?"Procento":"Částka v Kč"}</span><input inputMode="decimal" value={paymentValue} onChange={event=>setPaymentValue(event.target.value)}/></label></div><div className="payment-calculation"><span><small>Výsledná platební povinnost</small><strong>{formatMoney(calculatedPayment)}</strong></span><small>Základ: aktuální cena {formatMoney(selectedUnit?.price??0)}</small></div><div className="form-row"><label><span>Splatnost</span><select value={dueMode} onChange={event=>setDueMode(event.target.value)}><option value="3">3 dny</option><option value="5">5 dní</option><option value="7">7 dní</option><option value="10">10 dní</option><option value="14">14 dní</option><option value="custom">Vlastní datum</option></select></label>{dueMode==="custom"&&<label><span>Datum splatnosti</span><input type="date" value={customDueAt} onChange={event=>setCustomDueAt(event.target.value)}/></label>}</div></fieldset>}<p className="form-help"><Link2 size={14}/> Jednotka, klient, projekt i obchodní proces se doplní automaticky. První logická verze vznikne při uložení.</p></FormModal>;
}
function ContractVersionModal({contract,close,save}:{contract:(typeof contracts)[number];close:()=>void;save:(value:{name:string;source:string;basedOnVersionId?:string})=>Promise<void>}){const latest=contract.versions?.[0];const next=(latest?.number??0)+1;const [name,setName]=useState(`${contract.reference??`${contract.type}-${contract.unit}`}_v${String(next).padStart(2,"0")}`);const [source,setSource]=useState("manual");return <FormModal title={`Nová verze · ${contract.reference??contract.type}`} close={close} saveLabel="Vytvořit verzi" onSave={async()=>{if(!name.trim())throw new Error("Doplňte název verze");await save({name:name.trim(),source,basedOnVersionId:latest?.id});}}><label><span>Název logické verze</span><input autoFocus value={name} onChange={event=>setName(event.target.value)}/></label><label><span>Zdroj verze</span><select value={source} onChange={event=>setSource(event.target.value)}><option value="manual">Ručně připravená verze</option><option value="imported">Nahraná nebo vrácená verze</option><option value="generated">Vygenerováno z CRM</option></select></label>{latest&&<p className="form-help"><Link2 size={14}/> Nová verze naváže na v{latest.number} a předchozí záznam zůstane zachován.</p>}</FormModal>}

function ClientActivityModal({client,close,save}:{client:(typeof clients)[number];close:()=>void;save:(value:{activityType:"note"|"call"|"email"|"meeting"|"other";note:string})=>Promise<void>}){const [activityType,setActivityType]=useState<"note"|"call"|"email"|"meeting"|"other">("note");const [note,setNote]=useState("");return <FormModal title={`Přidat aktivitu · ${client.name}`} close={close} saveLabel="Uložit aktivitu" onSave={async()=>{if(note.trim().length<2)throw new Error("Doplňte stručnou poznámku");await save({activityType,note:note.trim()});}}><label><span>Typ aktivity</span><select value={activityType} onChange={event=>setActivityType(event.target.value as typeof activityType)}><option value="note">Poznámka</option><option value="call">Telefonát</option><option value="email">E-mail</option><option value="meeting">Schůzka</option><option value="other">Jiná aktivita</option></select></label><label><span>Poznámka</span><textarea autoFocus rows={5} value={note} onChange={event=>setNote(event.target.value)} placeholder="Co se s klientem řešilo?"/></label></FormModal>}

type ContractAssignmentForm={buyers?:Array<{partyId:string;role:"buyer"|"co_buyer";isPrimary:boolean;share:null}>;newParty?:{kind:"individual"|"organization";salutation?:string;firstName?:string;lastName?:string;legalName?:string;registrationNumber?:string;email?:string;phone?:string};effectiveAt:string;note?:string;idempotencyKey:string};
function BuyerChangeModal({unit,clients:clientRows,context,close,save}:{unit:UnitRecord;clients:(typeof clients)[number][];context?:UnitCommercialContext;close:()=>void;save:(value:ContractAssignmentForm)=>Promise<void>}){
  const currentIds=new Set(context?.buyers.map(item=>item.partyId)??[]);const available=clientRows.filter(client=>client.lifecycleStatus!=="archived"&&!currentIds.has(client.id));
  const [mode,setMode]=useState<"existing"|"new">("existing");const [selected,setSelected]=useState<string[]>([]);const [primary,setPrimary]=useState("");const [effectiveAt,setEffectiveAt]=useState(localDateKey(new Date()));const [note,setNote]=useState("");const [idempotencyKey]=useState(()=>crypto.randomUUID());
  const [kind,setKind]=useState<"individual"|"organization">("individual");const [salutation,setSalutation]=useState("");const [firstName,setFirstName]=useState("");const [lastName,setLastName]=useState("");const [legalName,setLegalName]=useState("");const [registrationNumber,setRegistrationNumber]=useState("");const [email,setEmail]=useState("");const [phone,setPhone]=useState("");
  const toggle=(id:string)=>setSelected(rows=>{const next=rows.includes(id)?rows.filter(item=>item!==id):[...rows,id];if(!next.includes(primary))setPrimary(next[0]??"");return next;});
  return <FormModal title={`Postoupit smlouvu · ${unit.id}`} close={close} saveLabel="Vytvořit dokument o postoupení" onSave={async()=>{
    if(!effectiveAt)throw new Error("Vyberte datum postoupení");
    if(mode==="existing"&&(!selected.length||!primary))throw new Error("Vyberte alespoň jednoho nového kupujícího a označte hlavního");
    if(mode==="new"&&kind==="individual"&&(!firstName.trim()||!lastName.trim()))throw new Error("Doplňte jméno a příjmení nového kupujícího");
    if(mode==="new"&&kind==="organization"&&!legalName.trim())throw new Error("Doplňte název společnosti");
    if(!window.confirm("Vznikne nový dokument o postoupení. Aktuální kupující se změní až po jeho podpisu. Pokračovat?"))return;
    await save({effectiveAt:new Date(`${effectiveAt}T12:00:00`).toISOString(),note:note.trim()||undefined,idempotencyKey,...(mode==="existing"?{buyers:selected.map(partyId=>({partyId,role:partyId===primary?"buyer":"co_buyer",isPrimary:partyId===primary,share:null}))}:{newParty:{kind,salutation:salutation||undefined,firstName:firstName.trim()||undefined,lastName:lastName.trim()||undefined,legalName:legalName.trim()||undefined,registrationNumber:registrationNumber.trim()||undefined,email:email.trim()||undefined,phone:phone.trim()||undefined}})});
  }}><div className="form-help"><GitBranch size={14}/> Typ postoupení se určí automaticky podle poslední podepsané RS nebo SBK. Původní smlouva, podpisy, verze i platby zůstanou beze změny.</div><div className="form-segmented"><button type="button" className={mode==="existing"?"active":""} onClick={()=>setMode("existing")}>Existující klient</button><button type="button" className={mode==="new"?"active":""} onClick={()=>setMode("new")}>Nový klient</button></div>{mode==="existing"?<><fieldset className="buyer-assignment-list"><legend>Nové smluvní strany</legend>{available.map(client=><label key={client.id}><input type="checkbox" checked={selected.includes(client.id)} onChange={()=>toggle(client.id)}/><span><strong>{client.name}</strong><small>{client.email||client.phone||client.kind}</small></span>{selected.includes(client.id)&&<input type="radio" name="primary-buyer" checked={primary===client.id} onChange={()=>setPrimary(client.id)} aria-label={`${client.name} jako hlavní kupující`}/>}</label>)}{!available.length&&<div className="empty-filter-state"><UserRound size={18}/><strong>Není dostupný jiný klient</strong><small>Založte nového klienta přímo v tomto formuláři.</small></div>}</fieldset><small className="form-hint">Lze vybrat více kupujících; tečkou vpravo určíte hlavního.</small></>:<><div className="form-row"><label><span>Typ klienta</span><select value={kind} onChange={event=>setKind(event.target.value as typeof kind)}><option value="individual">Fyzická osoba</option><option value="organization">Právnická osoba</option></select></label>{kind==="individual"&&<label><span>Oslovení / titul (volitelné)</span><input value={salutation} onChange={event=>setSalutation(event.target.value)} placeholder="paní, Ing.…"/></label>}</div>{kind==="individual"?<div className="form-row"><label><span>Jméno</span><input value={firstName} onChange={event=>setFirstName(event.target.value)}/></label><label><span>Příjmení</span><input value={lastName} onChange={event=>setLastName(event.target.value)}/></label></div>:<div className="form-row"><label><span>Název společnosti</span><input value={legalName} onChange={event=>setLegalName(event.target.value)}/></label><label><span>IČO (volitelné)</span><input value={registrationNumber} onChange={event=>setRegistrationNumber(event.target.value)}/></label></div>}<div className="form-row"><label><span>E-mail (volitelné)</span><input type="email" value={email} onChange={event=>setEmail(event.target.value)}/></label><label><span>Telefon (volitelné)</span><input value={phone} onChange={event=>setPhone(event.target.value)}/></label></div></>}<div className="form-row"><label><span>Datum postoupení</span><input type="date" max={localDateKey(new Date())} value={effectiveAt} onChange={event=>setEffectiveAt(event.target.value)}/></label><label><span>Poznámka (volitelné)</span><input value={note} onChange={event=>setNote(event.target.value)} placeholder="Důvod nebo interní poznámka"/></label></div><p className="form-help"><ShieldCheck size={14}/> Kupující se v jednotce a obchodním procesu přepne teprve po označení dokumentu o postoupení jako podepsaného.</p></FormModal>;
}
function ContractSignedModal({contract,close,save}:{contract:(typeof contracts)[number];close:()=>void;save:(value:{signedAt:string;note?:string})=>Promise<void>}){const latest=contract.versions?.[0];const today=new Date().toLocaleDateString("en-CA");const [signedDate,setSignedDate]=useState(today);const [note,setNote]=useState("");return <FormModal title="Označit smlouvu jako podepsanou" close={close} saveLabel="Označit jako podepsané" onSave={async()=>{if(!latest)throw new Error("Smlouvu nelze podepsat, protože nemá platnou aktuální verzi.");if(!signedDate)throw new Error("Vyberte datum podpisu");if(signedDate>today)throw new Error("Datum podpisu nesmí být v budoucnosti");if(!window.confirm(`Potvrzujete, že smlouva ${contract.reference??contract.type} ve verzi v${String(latest.number).padStart(2,"0")} byla podepsána?`))return;await save({signedAt:new Date(`${signedDate}T12:00:00`).toISOString(),note:note.trim()||undefined});}}><div className="contract-sign-confirm"><FileCheck2 size={22}/><div><strong>{contract.reference??`${contract.type} · ${contract.unit}`}</strong><small>Aktuální logická verze v{String(latest?.number??1).padStart(2,"0")} · {contract.client}</small></div></div><label><span>Datum podpisu</span><input type="date" value={signedDate} max={today} onChange={event=>setSignedDate(event.target.value)}/></label><label><span>Poznámka (volitelné)</span><textarea rows={3} value={note} onChange={event=>setNote(event.target.value)} placeholder="Například kde je podepsaný originál uložen"/></label></FormModal>}
function ContractWorkflowModal({contract,close,save}:{contract:(typeof contracts)[number];close:()=>void;save:(value:{to:string;reason:string})=>Promise<void>}){const options=availableContractTransitions(contract.statusCode??contract.state);const [to,setTo]=useState<string>(options[0]??"");const [reason,setReason]=useState("");const destructive=to==="cancelled"||to==="terminated";return <FormModal title={`Workflow ${contract.type} · ${contract.unit}`} close={close} onSave={async()=>{if(!to)throw new Error("Pro aktuální stav není dostupný ruční přechod");if(destructive&&!reason.trim())throw new Error("Doplňte důvod zrušení nebo ukončení");if(destructive&&!window.confirm("Tato změna je obchodně významná. Opravdu pokračovat?"))return;await save({to,reason:reason.trim()});}}><label><span>Aktuální stav</span><input value={contractStatusLabel(contract.statusCode??contract.state)} disabled/></label><label><span>Nový stav</span><select value={to} onChange={e=>setTo(e.target.value)}>{options.map(item=><option key={item} value={item}>{contractStatusLabel(item)}</option>)}</select></label><label><span>{destructive?"Důvod":"Poznámka (volitelné)"}</span><textarea rows={3} value={reason} onChange={e=>setReason(e.target.value)}/></label><p className="form-help"><History size={14}/> Dostupné jsou pouze povolené přechody. Podpis se eviduje samostatně v detailu smlouvy.</p></FormModal>}
function FormModal({title,close,onSave,children,saveLabel="Uložit"}:{title:string;close:()=>void;onSave:()=>Promise<void>;children:React.ReactNode;saveLabel?:string}){const [busy,setBusy]=useState(false);const [error,setError]=useState("");const submit=async()=>{setBusy(true);setError("");try{await onSave();}catch(problem){setError(problem instanceof Error?problem.message:"Změnu se nepodařilo uložit");}finally{setBusy(false);}};return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label="Zavřít dialog" /><div className="modal form-modal"><div className="modal-head"><div><h2>{title}</h2><p>Změna se uloží přes řízenou doménovou operaci.</p></div><button className="icon-button" onClick={close}><X size={19}/></button></div><div className="modal-form">{children}{error&&<div className="form-error"><AlertTriangle size={15}/>{error}</div>}</div><div className="modal-foot"><button className="secondary-button" onClick={close} disabled={busy}>Zrušit</button><button className="primary-button" onClick={()=>void submit()} disabled={busy}>{busy?"Ukládám…":saveLabel}</button></div></div></div>}

function NewProjectModal({memberships,close,save}:{memberships:MembershipOption[];close:()=>void;save:(value:{name:string;code:string;location:string;address:string;description:string;constructionStatus:string;plannedHandoverFrom:string|null;managerMembershipId:string|null;projectCompany:string;defaultCurrency:string;plannedUnitCount:number|null;note:string})=>Promise<void>}){
  const [name,setName]=useState("");const [code,setCode]=useState("");const [location,setLocation]=useState("");const [address,setAddress]=useState("");const [description,setDescription]=useState("");const [constructionStatus,setConstructionStatus]=useState("preparation");const [completionMonth,setCompletionMonth]=useState("");const [completionYear,setCompletionYear]=useState("");const [managerMembershipId,setManagerMembershipId]=useState("");const [projectCompany,setProjectCompany]=useState("");const [defaultCurrency,setDefaultCurrency]=useState("CZK");const [plannedUnitCount,setPlannedUnitCount]=useState("");const [note,setNote]=useState("");
  return <FormModal title="Nový projekt" close={close} saveLabel="Založit projekt" onSave={async()=>{const normalizedCode=code.trim().toUpperCase();if(name.trim().length<2)throw new Error("Doplňte název projektu");if(!/^[A-Z0-9ČŘŠŽÝÁÍÉÚŮĚ_-]{2,16}$/.test(normalizedCode))throw new Error("Kód musí mít 2–16 velkých písmen, číslic, pomlček nebo podtržítek");if(!location.trim())throw new Error("Doplňte lokalitu projektu");if(Boolean(completionMonth)!==Boolean(completionYear))throw new Error("Vyberte měsíc i rok plánovaného dokončení");await save({name:name.trim(),code:normalizedCode,location:location.trim(),address:address.trim(),description:description.trim(),constructionStatus,plannedHandoverFrom:projectCompletionStorageDate(completionMonth&&completionYear?`${completionYear}-${completionMonth}`:""),managerMembershipId:managerMembershipId||null,projectCompany:projectCompany.trim(),defaultCurrency,plannedUnitCount:plannedUnitCount?Number(plannedUnitCount):null,note:note.trim()});}}>
    <div className="form-row"><label><span>Název projektu</span><input autoFocus value={name} onChange={event=>{setName(event.target.value);if(!code)setCode(projectCodeSuggestion(event.target.value));}} placeholder="Např. Rezidence Vltavská"/></label><label><span>Kód projektu</span><input maxLength={16} value={code} onChange={event=>setCode(event.target.value.toUpperCase())} placeholder="RVL"/></label></div>
    <div className="form-row"><label><span>Lokalita</span><input value={location} onChange={event=>setLocation(event.target.value)} placeholder="Praha 6"/></label><label><span>Adresa</span><input value={address} onChange={event=>setAddress(event.target.value)} placeholder="Ulice a číslo"/></label></div>
    <label><span>Stručný popis</span><textarea rows={3} value={description} onChange={event=>setDescription(event.target.value)}/></label>
    <label><span>Počáteční fáze výstavby</span><select value={constructionStatus} onChange={event=>setConstructionStatus(event.target.value)}>{PROJECT_CONSTRUCTION_PHASES.map(option=><option key={option.code} value={option.code}>{option.label}</option>)}</select></label><MonthYearPicker month={completionMonth} year={completionYear} onMonth={setCompletionMonth} onYear={setCompletionYear}/>
    <div className="form-row"><label><span>Vedoucí projektu</span><select value={managerMembershipId} onChange={event=>setManagerMembershipId(event.target.value)}><option value="">Zatím nepřiřazen</option>{memberships.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label><span>Projektová společnost</span><input value={projectCompany} onChange={event=>setProjectCompany(event.target.value)} placeholder="SPV / vlastník projektu"/></label></div>
    <div className="form-row"><label><span>Měna</span><select value={defaultCurrency} onChange={event=>setDefaultCurrency(event.target.value)}><option value="CZK">CZK</option><option value="EUR">EUR</option></select></label><label><span>Plánovaný počet jednotek</span><input type="number" min="0" value={plannedUnitCount} onChange={event=>setPlannedUnitCount(event.target.value)}/></label></div>
    <label><span>Interní poznámka</span><textarea rows={2} value={note} onChange={event=>setNote(event.target.value)}/></label>
    <p className="form-help"><ShieldCheck size={14}/> Projekt vznikne prázdný. Jednotky, klienti ani jiné demo záznamy se automaticky nevytvoří.</p>
  </FormModal>;
}

function projectCodeSuggestion(value:string){return value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").split(/\s+/).filter(Boolean).map(part=>part[0]).join("").replace(/[^A-Z0-9]/gi,"").slice(0,8).toUpperCase();}
function slugifyProject(value:string){const slug=value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");return slug||`projekt-${Date.now()}`;}
function numberValue(value:string){if(!value.trim())return undefined;const number=Number(value.replace(",","."));return Number.isFinite(number)?number:undefined;}
function projectMatchesName(project:ProjectRecord,name:string){return name===project.name||name===project.sourceName;}
function unitBelongsToProject(unit:UnitRecord,project:ProjectRecord){return Boolean((unit.projectBackendId&&project.backendId&&unit.projectBackendId===project.backendId)||(unit.projectCode&&unit.projectCode===project.code)||projectMatchesName(project,unit.project));}
function clientBelongsToProject(client:ClientRecord,project:ProjectRecord){return project.backendId?Boolean(client.projectIds?.includes(project.backendId)||client.unitRelations?.some(relation=>relation.projectId===project.backendId)):client.projectNames.some(name=>projectMatchesName(project,name));}
function contractBelongsToProject(contract:ContractRecord,project:ProjectRecord){return project.backendId?contract.projectId===project.backendId:projectMatchesName(project,contract.project);}
function taskBelongsToProject(task:TaskRecord,project:ProjectRecord){return project.backendId?task.projectId===project.backendId:projectMatchesName(project,task.project);}
function isDejviceUnit(unit:UnitRecord){return unit.projectCode==="DEJ"||unit.project==="Rezidence Dejvice"||unit.project==="Rezidence Dejvice Test";}
function backendEntityId(value?:string|null){return value&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)?value:null;}
function projectRouteId(project:ProjectRecord){return project.backendId??project.code;}
function unitRouteId(unit:UnitRecord){return unit.backendId??unit.id;}

type TaskTarget={kind:"project"|"unit"|"party"|"contract";id:string;projectId:string;label:string};
function taskTargetOptions():TaskTarget[]{
  const result:TaskTarget[]=[];
  for(const project of projects){const projectId=backendEntityId(project.backendId);if(projectId)result.push({kind:"project",id:projectId,projectId,label:`Projekt · ${project.name}`});}
  for(const unit of units){const id=backendEntityId(unit.backendId),projectId=backendEntityId(unit.projectBackendId);if(id&&projectId)result.push({kind:"unit",id,projectId,label:`Jednotka ${unit.id} · ${unit.project}`});}
  for(const client of clients){const project=projects.find(item=>client.projectNames.some(name=>projectMatchesName(item,name)));const projectId=backendEntityId(project?.backendId);if(backendEntityId(client.id)&&projectId)result.push({kind:"party",id:client.id,projectId,label:`Klient · ${client.name}`});}
  for(const contract of contracts){const project=projects.find(item=>projectMatchesName(item,contract.project));const projectId=backendEntityId(project?.backendId);if(contract.id&&backendEntityId(contract.id)&&projectId)result.push({kind:"contract",id:contract.id,projectId,label:`Smlouva ${contract.type} · ${contract.unit}`});}
  return result;
}

function TaskModal({ close, save,memberships,targets,defaultUnit }: { close: () => void; save: (value:{title:string;description:string;target:TaskTarget;assigneeMembershipId:string;priority:"low"|"medium"|"high";dueAt:string}) => Promise<void>;memberships:MembershipOption[];targets:TaskTarget[];defaultUnit?:string }) {
  const initialTarget=targets.find(item=>item.kind==="unit"&&item.id===defaultUnit)??targets.find(item=>item.kind==="unit")??targets[0];
  const [title,setTitle]=useState("");const [description,setDescription]=useState("");const [targetId,setTargetId]=useState(initialTarget?`${initialTarget.kind}:${initialTarget.id}`:"");const [assigneeId,setAssigneeId]=useState(memberships[0]?.id??"");const [priority,setPriority]=useState<"low"|"medium"|"high">("medium");const [dueAt,setDueAt]=useState(()=>localDateKey(addCalendarDays(new Date(),1)));
  return <FormModal title="Nový úkol" close={close} saveLabel="Vytvořit úkol" onSave={async()=>{if(!title.trim())throw new Error("Doplňte název úkolu");const target=targets.find(item=>`${item.kind}:${item.id}`===targetId);if(!target)throw new Error("Vyberte objekt, ke kterému úkol patří");if(!assigneeId)throw new Error("Vyberte odpovědnou osobu");await save({title:title.trim(),description:description.trim(),target,assigneeMembershipId:assigneeId,priority,dueAt});}}><label><span>Název úkolu</span><input autoFocus value={title} onChange={event=>setTitle(event.target.value)} placeholder="Co je potřeba udělat?"/></label><label><span>Popis</span><textarea rows={3} value={description} onChange={event=>setDescription(event.target.value)} placeholder="Kontext a očekávaný výsledek"/></label><label><span>Vazba na objekt</span><select value={targetId} onChange={event=>setTargetId(event.target.value)}><option value="" disabled>Vyberte projekt, jednotku, klienta nebo smlouvu</option>{targets.map(item=><option key={`${item.kind}:${item.id}`} value={`${item.kind}:${item.id}`}>{item.label}</option>)}</select></label><div className="form-row"><label><span>Termín</span><input type="date" value={dueAt} onChange={event=>setDueAt(event.target.value)}/></label><label><span>Odpovědná osoba</span><select value={assigneeId} onChange={event=>setAssigneeId(event.target.value)}><option value="" disabled>Vyberte aktivního uživatele</option>{memberships.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label><span>Priorita</span><select value={priority} onChange={event=>setPriority(event.target.value as "low"|"medium"|"high")}><option value="low">Nízká</option><option value="medium">Střední</option><option value="high">Vysoká</option></select></label></div></FormModal>;
}

function IssueReportModal({page,close,save}:{page:Page;close:()=>void;save:(value:{subject:string;description:string;priority:"normal"|"high"})=>Promise<void>}){
  const [subject,setSubject]=useState("");const [description,setDescription]=useState("");const [priority,setPriority]=useState<"normal"|"high">("normal");
  return <FormModal title="Nahlásit problém" close={close} saveLabel="Odeslat hlášení" onSave={async()=>{if(subject.trim().length<3||description.trim().length<5)throw new Error("Doplňte stručný název a popis problému");await save({subject:subject.trim(),description:description.trim(),priority});}}><p className="form-help"><MessageSquare size={14}/> Hlášení se uloží jako interní záznam včetně aktuální stránky: {pageTitles[page].title}.</p><label><span>Název problému</span><input autoFocus value={subject} onChange={event=>setSubject(event.target.value)} placeholder="Co nefunguje nebo není srozumitelné?"/></label><label><span>Popis a očekávané chování</span><textarea rows={5} value={description} onChange={event=>setDescription(event.target.value)} placeholder="Popište postup, výsledek a co jste očekávali."/></label><label><span>Priorita</span><select value={priority} onChange={event=>setPriority(event.target.value as "normal"|"high")}><option value="normal">Běžná</option><option value="high">Vysoká – blokuje práci</option></select></label></FormModal>;
}

function ProfileModal({session,close,openSettings,openAdmin,canAdmin}:{session:IdentitySession;close:()=>void;openSettings:()=>void;openAdmin:()=>void;canAdmin:boolean}){const scopes=session.workspace.projectScopes??[];const [workspaces,setWorkspaces]=useState<Array<{tenantId:string;tenantName:string;tenantSlug:string}>>([]);useEffect(()=>{const controller=new AbortController();identityRepository.listWorkspaces(controller.signal).then(setWorkspaces).catch(()=>undefined);return()=>controller.abort();},[]);return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label="Zavřít profil"/><div className="modal profile-modal"><div className="modal-head"><div><h2>Profil a pracovní prostor</h2><p>Přihlášený uživatel a jeho efektivní oprávnění.</p></div><button className="icon-button" onClick={close}><X size={19}/></button></div><div className="profile-summary"><Avatar initials={session.user.initials||initials(session.user.displayName)}/><span><strong>{session.user.displayName}</strong><small>{session.user.email}{session.user.jobTitle?` · ${session.user.jobTitle}`:""}</small></span><Badge tone="success">Aktivní</Badge></div><div className="profile-workspace"><Building2 size={18}/><span><small>PRACOVNÍ PROSTOR</small><strong>{session.workspace.tenantName}</strong></span>{session.workspace.roles.map(role=><Badge key={role} tone="neutral">{roleLabel([role])}</Badge>)}</div>{workspaces.length>1&&<label className="workspace-switch"><span>Přepnout pracovní prostor</span><select defaultValue={session.workspace.tenantId} onChange={()=>window.location.reload()}>{workspaces.map(workspace=><option key={workspace.tenantId} value={workspace.tenantId}>{workspace.tenantName}</option>)}</select></label>}<section className="profile-section"><h3>Projektové rozsahy</h3>{scopes.length?scopes.map(scope=><div key={scope.projectId}><span><strong>{scope.projectName}</strong><small>{scope.roles.map(role=>roleLabel([role])).join(", ")}</small></span></div>):<p>Tenantová role umožňuje práci ve všech dostupných projektech.</p>}</section><div className="profile-actions"><button className="secondary-button" onClick={openSettings}><Settings size={16}/> Nastavení profilu</button>{canAdmin&&<button className="secondary-button" onClick={openAdmin}><ShieldCheck size={16}/> Uživatelé a role</button>}{session.source==="production-api"?<button className="secondary-button danger-text" onClick={()=>void entraAuth.logout()}><LogOut size={16}/> Odhlásit se</button>:<Link className="secondary-button danger-text" href="/signout-with-chatgpt?return_to=%2F"><LogOut size={16}/> Odhlásit se</Link>}</div></div></div>}

function ProfileSettingsModal({user,close,save}:{user:IdentitySession["user"];close:()=>void;save:(value:ProfileInput)=>Promise<void>}){
  const [displayName,setDisplayName]=useState(user.displayName);const [jobTitle,setJobTitle]=useState(user.jobTitle??"");const [phone,setPhone]=useState(user.phone??"");const [profileInitials,setProfileInitials]=useState(user.initials??initials(user.displayName));const [language,setLanguage]=useState<"cs"|"en">(user.language??"cs");const [timezone,setTimezone]=useState(user.timezone??"Europe/Prague");const [emailNotifications,setEmailNotifications]=useState(user.notifications?.email??true);const [inAppNotifications,setInAppNotifications]=useState(user.notifications?.inApp??true);
  return <FormModal title="Nastavení profilu" close={close} onSave={async()=>{if(displayName.trim().length<2)throw new Error("Doplňte zobrazované jméno");await save({displayName:displayName.trim(),jobTitle,phone,initials:profileInitials,language,timezone,notifications:{email:emailNotifications,inApp:inAppNotifications}});}}><div className="form-row"><label><span>Zobrazované jméno</span><input value={displayName} onChange={event=>setDisplayName(event.target.value)}/></label><label><span>Iniciály</span><input maxLength={4} value={profileInitials} onChange={event=>setProfileInitials(event.target.value.toUpperCase())}/></label></div><div className="form-row"><label><span>Pracovní pozice</span><input value={jobTitle} onChange={event=>setJobTitle(event.target.value)}/></label><label><span>Telefon</span><input value={phone} onChange={event=>setPhone(event.target.value)}/></label></div><label><span>Pracovní e-mail z Microsoft Entra ID</span><input value={user.email} disabled/><small>Tento údaj se spravuje v Microsoft 365.</small></label><div className="form-row"><label><span>Jazyk</span><select value={language} onChange={event=>setLanguage(event.target.value as "cs"|"en")}><option value="cs">Čeština</option><option value="en">English</option></select></label><label><span>Časové pásmo</span><select value={timezone} onChange={event=>setTimezone(event.target.value)}><option value="Europe/Prague">Europe/Prague</option><option value="Europe/Bratislava">Europe/Bratislava</option><option value="Europe/London">Europe/London</option></select></label></div><fieldset className="admin-check-grid"><legend>Notifikace</legend><label><input type="checkbox" checked={inAppNotifications} onChange={event=>setInAppNotifications(event.target.checked)}/><span>V aplikaci</span></label><label><input type="checkbox" checked={emailNotifications} onChange={event=>setEmailNotifications(event.target.checked)}/><span>E-mailem</span></label></fieldset><p className="form-help"><ShieldCheck size={14}/> Změny profilu se ukládají a zapisují do auditu.</p></FormModal>;
}

function MediaModal({value,close,save}:{value:{title:string;kind:"cover"|"floorplan"};close:()=>void;save:(file:File)=>Promise<void>}){
  const [file,setFile]=useState<File|null>(null);const [preview,setPreview]=useState<string|null>(null);const [selectionError,setSelectionError]=useState("");
  useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview);},[preview]);
  const isPdf=file?.type==="application/pdf";
  return <FormModal title={value.title} close={close} saveLabel={value.kind==="cover"?"Uložit titulní obrázek":"Uložit půdorys"} onSave={async()=>{if(!file)throw new Error(value.kind==="floorplan"?"Vyberte půdorys":"Vyberte obrázek");validateMediaFile(file,value.kind);await save(file);}}><label className="media-dropzone">{value.kind==="floorplan"?<FileText size={25}/>:<ImagePlus size={25}/>}<span><strong>{value.kind==="floorplan"?"Vyberte půdorys":"Vyberte obrázek"}</strong><small>{value.kind==="floorplan"?"JPG, PNG a WebP do 12 MB · PDF do 25 MB":"JPG, PNG nebo WebP · maximálně 12 MB"}</small></span><input type="file" accept={mediaAccept(value.kind)} onChange={event=>{const selected=event.target.files?.[0]??null;if(preview)URL.revokeObjectURL(preview);if(!selected){setFile(null);setPreview(null);setSelectionError("");return;}try{validateMediaFile(selected,value.kind);setFile(selected);setPreview(URL.createObjectURL(selected));setSelectionError("");}catch(error){setFile(null);setPreview(null);setSelectionError(error instanceof Error?error.message:"Nepodporovaný formát souboru.");event.target.value="";}}}/></label>{selectionError&&<p className="form-error" role="alert"><AlertTriangle size={15}/>{selectionError}</p>}{preview&&(isPdf?<div className="media-pdf-preview"><iframe src={`${preview}#page=1&toolbar=0&navpanes=0`} title="Náhled první stránky PDF"/><span><FileText size={20}/><strong>{file?.name}</strong><small>PDF · první stránka</small></span></div>:<img className={`media-preview ${value.kind}`} src={preview} alt="Náhled vybraného obrázku"/>)}</FormModal>
}
